GENESIS_TEXT[14]=[
"Naqueles dias, Anrafel, rei de Sinear, Arioque, rei de Elasar, Quedorlaomer, rei de Elão, e Tidal, rei de Goim,",
"fizeram guerra contra Bera, rei de Sodoma, contra Birsa, rei de Gomorra, contra Sinabe, rei de Admá, contra Semeber, rei de Zeboim, e contra o rei de Bela, isto é, Zoar.",
"Todos estes se reuniram no vale de Sidim, onde fica o Mar Salgado.",
"Durante doze anos haviam servido a Quedorlaomer, mas no décimo terceiro ano se rebelaram.",
"No décimo quarto ano, Quedorlaomer e os reis que estavam com ele vieram e derrotaram os refains em Astarote-Carnaim, os zuzins em Hã, os emins em Savé-Quiriataim",
"e os horeus na região montanhosa de Seir, até El-Parã, junto ao deserto.",
"Depois voltaram e chegaram a En-Mispate, isto é, Cades, e conquistaram todo o território dos amalequitas e também dos amorreus que habitavam em Hazazom-Tamar.",
"Então o rei de Sodoma, o rei de Gomorra, o rei de Admá, o rei de Zeboim e o rei de Bela, isto é, Zoar, saíram e se prepararam para a batalha no vale de Sidim,",
"contra Quedorlaomer, rei de Elão, Tidal, rei de Goim, Anrafel, rei de Sinear, e Arioque, rei de Elasar: quatro reis contra cinco.",
"O vale de Sidim estava cheio de poços de betume. Quando os reis de Sodoma e Gomorra fugiram, alguns caíram neles; os demais fugiram para a região montanhosa.",
"Os vencedores tomaram todos os bens de Sodoma e Gomorra e todo o seu alimento, e partiram.",
"Também levaram Ló, sobrinho de Abrão, e seus bens, pois ele habitava em Sodoma.",
"Um fugitivo veio e contou tudo a Abrão, o hebreu, que habitava junto aos carvalhos de Manre, o amorreu, irmão de Escol e Aner; eles eram aliados de Abrão.",
"Quando Abrão soube que seu parente havia sido levado cativo, reuniu os homens treinados nascidos em sua casa, trezentos e dezoito, e perseguiu os invasores até Dã.",
"Dividiu seus homens durante a noite, atacou-os e os perseguiu até Hobá, ao norte de Damasco.",
"Recuperou todos os bens e trouxe de volta também Ló, seu parente, com os bens dele, as mulheres e o povo.",
"Quando Abrão voltou depois de derrotar Quedorlaomer e os reis que estavam com ele, o rei de Sodoma saiu ao seu encontro no vale de Savé, isto é, o vale do Rei.",
"Melquisedeque, rei de Salém, trouxe pão e vinho. Ele era sacerdote do Deus Altíssimo.",
"Melquisedeque abençoou Abrão, dizendo: “Bendito seja Abrão pelo Deus Altíssimo, Criador dos céus e da terra.",
"E bendito seja o Deus Altíssimo, que entregou teus adversários em tuas mãos”. Abrão lhe deu o dízimo de tudo.",
"O rei de Sodoma disse a Abrão: “Entrega-me as pessoas e fica com os bens”.",
"Abrão respondeu ao rei de Sodoma: “Levanto minha mão diante de YHWH, Deus Altíssimo, Criador dos céus e da terra,",
"e juro que não tomarei coisa alguma do que é teu, nem um fio, nem uma correia de sandália, para que não digas: ‘Eu enriqueci Abrão’.",
"Ficarei somente com o que os jovens comeram e com a parte dos homens que foram comigo: Aner, Escol e Manre. Que eles recebam sua parte”."
];
GENESIS_TEXT[15]=[
"Depois desses acontecimentos, a palavra de YHWH veio a Abrão numa visão: “Não temas, Abrão. Eu sou teu escudo; tua recompensa será muito grande”.",
"Abrão respondeu: “Senhor YHWH, que me darás, se continuo sem filhos e o herdeiro de minha casa é Eliézer de Damasco?”",
"Abrão acrescentou: “Não me deste descendência, e um servo nascido em minha casa será meu herdeiro”.",
"Então a palavra de YHWH veio a ele: “Esse não será teu herdeiro; aquele que sair de teu próprio corpo será teu herdeiro”.",
"Deus o levou para fora e disse: “Olha para os céus e conta as estrelas, se és capaz de contá-las”. E lhe disse: “Assim será tua descendência”.",
"Abrão confiou em YHWH, e isso lhe foi considerado como justiça.",
"YHWH lhe disse: “Eu sou YHWH, que te tirei de Ur dos caldeus para dar-te esta terra como herança”.",
"Abrão perguntou: “Senhor YHWH, como saberei que a receberei como herança?”",
"YHWH respondeu: “Traz-me uma novilha de três anos, uma cabra de três anos, um carneiro de três anos, uma rolinha e um pombinho”.",
"Abrão trouxe todos esses animais, partiu-os ao meio e colocou cada metade diante da outra; as aves, porém, não partiu.",
"Aves de rapina desciam sobre os animais mortos, mas Abrão as afugentava.",
"Ao pôr do sol, um sono profundo caiu sobre Abrão; e um grande temor e uma grande escuridão o envolveram.",
"YHWH disse a Abrão: “Sabe com certeza que tua descendência será estrangeira numa terra que não será sua; ali será escravizada e oprimida durante quatrocentos anos.",
"Mas julgarei a nação a quem servirão; depois sairão com muitos bens.",
"Tu, porém, irás em paz para junto de teus pais e serás sepultado em boa velhice.",
"Na quarta geração, teus descendentes voltarão para cá, porque a culpa dos amorreus ainda não chegou ao seu limite”.",
"Quando o sol se pôs e veio a escuridão, apareceu um braseiro fumegante e uma tocha de fogo que passaram entre aquelas partes.",
"Naquele dia, YHWH estabeleceu uma aliança com Abrão, dizendo: “À tua descendência dou esta terra, desde o rio do Egito até o grande rio, o Eufrates:",
"a terra dos queneus, dos quenizeus, dos cadmoneus,",
"dos heteus, dos ferezeus, dos refains,",
"dos amorreus, dos cananeus, dos girgaseus e dos jebuseus”."
];

GENESIS_TEXT[16]=["Sarai, mulher de Abrão, não lhe dava filhos. Ela tinha uma serva egípcia chamada Hagar.","Sarai disse a Abrão: “Eis que YHWH me impediu de ter filhos. Une-te, por favor, à minha serva; talvez eu consiga filhos por meio dela”. Abrão ouviu a voz de Sarai.","Assim, depois de Abrão ter habitado dez anos na terra de Canaã, Sarai, sua mulher, tomou Hagar, a egípcia, sua serva, e a deu por mulher a Abrão, seu marido.","Abrão uniu-se a Hagar, e ela concebeu. Quando viu que havia concebido, sua senhora passou a ser desprezada aos seus olhos.","Então Sarai disse a Abrão: “Que a injustiça que sofro recaia sobre ti! Eu mesma coloquei minha serva em teus braços; mas, quando ela viu que havia concebido, passei a ser desprezada aos seus olhos. Que YHWH julgue entre mim e ti”.","Abrão respondeu a Sarai: “Tua serva está em tuas mãos; faze com ela o que te parecer bom”. Sarai a tratou com dureza, e Hagar fugiu de sua presença.","O mensageiro de YHWH a encontrou junto a uma fonte de água no deserto, junto à fonte que fica no caminho de Sur.","Ele perguntou: “Hagar, serva de Sarai, de onde vens e para onde vais?” Ela respondeu: “Estou fugindo da presença de Sarai, minha senhora”.","O mensageiro de YHWH lhe disse: “Volta para tua senhora e submete-te à autoridade dela”.","O mensageiro de YHWH também lhe disse: “Multiplicarei grandemente tua descendência, de modo que não poderá ser contada por sua multidão”.","O mensageiro de YHWH lhe disse ainda: “Eis que concebeste e darás à luz um filho; chamarás seu nome Ismael, porque YHWH ouviu tua aflição.","Ele será como um jumento selvagem entre os homens; sua mão será contra todos, e a mão de todos será contra ele; habitará diante de todos os seus irmãos”.","Hagar chamou YHWH, que lhe falava, de “Deus que me vê”, pois disse: “Também aqui olhei para aquele que me vê?”","Por isso aquele poço foi chamado Beer-Laai-Roi; ele fica entre Cades e Berede.","Hagar deu à luz um filho a Abrão, e Abrão chamou Ismael o filho que Hagar lhe dera.","Abrão tinha oitenta e seis anos quando Hagar deu à luz Ismael."];
GENESIS_TEXT[17]=["Quando Abrão tinha noventa e nove anos, YHWH lhe apareceu e disse: “Eu sou El Shaddai; anda diante de mim e sê íntegro.","Estabelecerei minha aliança entre mim e ti e te multiplicarei grandemente”.","Abrão caiu com o rosto em terra, e Deus falou com ele, dizendo:","“Quanto a mim, esta é minha aliança contigo: serás pai de uma multidão de nações.","Teu nome já não será Abrão; teu nome será Abraão, porque te constituí pai de uma multidão de nações.","Farei tua descendência extremamente numerosa; farei de ti nações, e reis sairão de ti.","Estabelecerei minha aliança entre mim e ti e tua descendência depois de ti, por suas gerações, como aliança perpétua, para ser teu Deus e o Deus de tua descendência depois de ti.","Darei a ti e à tua descendência depois de ti a terra em que és estrangeiro, toda a terra de Canaã, como propriedade perpétua; e serei o Deus deles”.","Deus disse ainda a Abraão: “Tu, porém, guardarás minha aliança, tu e tua descendência depois de ti, por suas gerações.","Esta é minha aliança, que guardareis entre mim e vós e tua descendência depois de ti: todo homem entre vós será circuncidado.","Fareis a circuncisão da carne do vosso prepúcio; isso será o sinal da aliança entre mim e vós.","Todo menino entre vós, ao completar oito dias, será circuncidado, por todas as vossas gerações: tanto o nascido em casa como o comprado por dinheiro de qualquer estrangeiro que não seja da tua descendência.","Deverá ser circuncidado tanto o nascido em tua casa como o comprado por teu dinheiro. Minha aliança estará em vossa carne como aliança perpétua.","O homem incircunciso, cujo prepúcio não tiver sido circuncidado, será eliminado de seu povo; ele quebrou minha aliança”.","Deus disse a Abraão: “Quanto a Sarai, tua mulher, não a chamarás mais Sarai; Sara será seu nome.","Eu a abençoarei e também te darei um filho por meio dela. Eu a abençoarei, e ela se tornará nações; reis de povos procederão dela”.","Abraão caiu com o rosto em terra, riu e disse consigo: “Nascerá um filho a um homem de cem anos? Sara, aos noventa anos, dará à luz?”","Abraão disse a Deus: “Que Ismael viva diante de ti!”","Deus respondeu: “De fato, Sara, tua mulher, dará à luz um filho, e lhe darás o nome de Isaque. Estabelecerei minha aliança com ele como aliança perpétua para sua descendência depois dele.","Quanto a Ismael, também te ouvi: eu o abençoarei, farei que seja fecundo e o multiplicarei grandemente. Ele gerará doze príncipes, e farei dele uma grande nação.","Mas estabelecerei minha aliança com Isaque, que Sara te dará nesta mesma época, no ano que vem”.","Quando terminou de falar com Abraão, Deus subiu de diante dele.","Abraão tomou Ismael, seu filho, todos os nascidos em sua casa e todos os comprados por seu dinheiro, todo homem entre os homens da casa de Abraão, e naquele mesmo dia circuncidou a carne do prepúcio deles, conforme Deus lhe havia ordenado.","Abraão tinha noventa e nove anos quando foi circuncidado na carne de seu prepúcio.","Ismael, seu filho, tinha treze anos quando foi circuncidado na carne de seu prepúcio.","Naquele mesmo dia foram circuncidados Abraão e Ismael, seu filho,","e todos os homens de sua casa, tanto os nascidos em casa como os comprados por dinheiro de estrangeiros, foram circuncidados com ele."];
GENESIS_TEXT[18]=["YHWH apareceu a Abraão junto aos carvalhos de Manre, enquanto ele estava sentado à entrada da tenda, no calor do dia.","Abraão levantou os olhos e viu três homens de pé diante dele. Ao vê-los, correu da entrada da tenda ao encontro deles e inclinou-se até o chão.","Disse: “Meu senhor, se encontrei favor aos teus olhos, peço-te que não passes sem parar junto a teu servo.","Que se traga um pouco de água; lavai os pés e descansai debaixo desta árvore.","Trarei um pedaço de pão para que recupereis as forças; depois podereis seguir viagem, pois foi para isso que passastes junto a vosso servo”. Eles responderam: “Faze como disseste”.","Abraão apressou-se para dentro da tenda, até Sara, e disse: “Depressa! Toma três medidas de farinha fina, amassa-a e faze pães”.","Abraão correu ao rebanho, tomou um bezerro tenro e bom e o entregou ao servo, que se apressou em prepará-lo.","Tomou coalhada, leite e o bezerro que havia preparado e os colocou diante deles. Ficou de pé junto a eles, debaixo da árvore, enquanto comiam.","Eles lhe perguntaram: “Onde está Sara, tua mulher?” Ele respondeu: “Está na tenda”.","Um deles disse: “Certamente voltarei a ti nesta mesma época, no ano que vem, e Sara, tua mulher, terá um filho”. Sara escutava à entrada da tenda, atrás dele.","Abraão e Sara eram idosos, avançados em idade; Sara já havia passado da idade de ter filhos.","Por isso Sara riu consigo mesma, dizendo: “Depois de envelhecer, terei ainda prazer, sendo também velho o meu senhor?”","YHWH perguntou a Abraão: “Por que Sara riu, dizendo: ‘Será mesmo que darei à luz, agora que estou velha?’","Existe algo difícil demais para YHWH? Na época determinada voltarei a ti, no ano que vem, e Sara terá um filho”.","Sara negou, dizendo: “Não ri”, pois estava com medo. Mas ele disse: “Não; tu riste”.","Os homens se levantaram dali e olharam na direção de Sodoma. Abraão caminhou com eles para acompanhá-los.","YHWH disse: “Esconderei de Abraão o que estou para fazer,","visto que Abraão certamente se tornará uma nação grande e poderosa, e nele serão abençoadas todas as nações da terra?","Pois eu o escolhi para que ordene a seus filhos e à sua casa depois dele que guardem o caminho de YHWH, praticando justiça e direito, a fim de que YHWH faça vir sobre Abraão o que lhe prometeu”.","YHWH disse: “O clamor contra Sodoma e Gomorra é grande, e seu pecado é muito grave.","Descerei e verei se agiram inteiramente conforme o clamor que chegou até mim; se não, saberei”.","Os homens partiram dali e foram em direção a Sodoma, mas Abraão permaneceu de pé diante de YHWH.","Abraão aproximou-se e perguntou: “Destruirás o justo com o perverso?","Talvez haja cinquenta justos dentro da cidade. Ainda assim destruirás o lugar? Não pouparás a cidade por causa dos cinquenta justos que nela estão?","Longe de ti fazer tal coisa: matar o justo com o perverso, tratando o justo como o perverso. Longe de ti! Não fará justiça o Juiz de toda a terra?”","YHWH respondeu: “Se eu encontrar em Sodoma cinquenta justos dentro da cidade, pouparei todo o lugar por causa deles”.","Abraão respondeu: “Eis que me atrevo a falar ao Senhor, embora eu seja pó e cinza.","Talvez faltem cinco para completar os cinquenta justos; destruirás toda a cidade por causa de cinco?” Ele respondeu: “Não a destruirei se encontrar ali quarenta e cinco”.","Abraão tornou a falar: “Talvez se encontrem ali quarenta”. Ele respondeu: “Não o farei por causa dos quarenta”.","Abraão disse: “Que o Senhor não se ire, e falarei: talvez se encontrem ali trinta”. Ele respondeu: “Não o farei se encontrar ali trinta”.","Abraão disse: “Eis que me atrevi a falar ao Senhor: talvez se encontrem ali vinte”. Ele respondeu: “Não a destruirei por causa dos vinte”.","Abraão disse: “Que o Senhor não se ire, e falarei só mais esta vez: talvez se encontrem ali dez”. Ele respondeu: “Não a destruirei por causa dos dez”.","Quando terminou de falar com Abraão, YHWH partiu, e Abraão voltou para o seu lugar."];
GENESIS_TEXT[19]=["Os dois mensageiros chegaram a Sodoma ao anoitecer, e Ló estava sentado à porta da cidade. Ao vê-los, levantou-se para recebê-los e inclinou-se com o rosto em terra.","Disse: “Meus senhores, peço-vos que venhais à casa de vosso servo, passeis a noite, laveis os pés e, de manhã, seguireis vosso caminho”. Eles responderam: “Não; passaremos a noite na praça”.","Mas ele insistiu muito, e eles foram com ele e entraram em sua casa. Ló preparou-lhes uma refeição, assou pães sem fermento, e eles comeram.","Antes que se deitassem, os homens da cidade, os homens de Sodoma, cercaram a casa: jovens e velhos, todo o povo, de todos os lados.","Chamaram Ló e disseram: “Onde estão os homens que vieram à tua casa esta noite? Traz-nos para fora, para que os conheçamos”.","Ló saiu à porta, fechou-a atrás de si","e disse: “Peço-vos, meus irmãos, não façais esse mal.","Eis que tenho duas filhas que ainda não conheceram homem; deixai-me trazê-las para fora, e fazei com elas o que vos parecer bem. Mas nada façais a estes homens, pois vieram para a proteção de meu teto”.","Mas eles disseram: “Sai da frente!” E acrescentaram: “Este indivíduo veio morar aqui como estrangeiro e agora quer ser juiz! Faremos contigo pior do que com eles”. Apertaram Ló com violência e avançaram para arrombar a porta.","Os homens, porém, estenderam as mãos, puxaram Ló para dentro da casa e fecharam a porta.","Feriram de cegueira os homens que estavam à entrada da casa, do menor ao maior, de modo que se cansaram procurando a porta.","Então os homens disseram a Ló: “Tens mais alguém aqui? Genros, filhos, filhas ou qualquer pessoa tua na cidade? Tira-os deste lugar,","pois vamos destruir este lugar, porque o clamor contra seus habitantes se tornou grande diante de YHWH, e YHWH nos enviou para destruí-lo”.","Ló saiu e falou aos seus genros, que estavam para casar com suas filhas: “Levantai-vos, saí deste lugar, porque YHWH vai destruir a cidade”. Mas seus genros pensaram que ele estava brincando.","Quando amanheceu, os mensageiros apressaram Ló, dizendo: “Levanta-te, toma tua mulher e tuas duas filhas que estão aqui, para que não pereças na punição da cidade”.","Como ele demorasse, os homens o seguraram pela mão, bem como sua mulher e suas duas filhas, pois YHWH teve misericórdia dele. Eles o tiraram e o deixaram fora da cidade.","Quando os levaram para fora, um deles disse: “Foge por tua vida! Não olhes para trás e não pares em lugar algum da planície. Foge para os montes, para que não pereças”.","Ló respondeu: “Não, meu senhor, peço-te!","Eis que teu servo encontrou favor aos teus olhos, e grande foi a bondade que me demonstraste, preservando minha vida. Mas não consigo fugir para os montes; o desastre me alcançaria, e eu morreria.","Eis que esta cidade está perto o bastante para eu fugir para lá, e é pequena. Permite que eu fuja para lá; não é pequena? Assim minha vida será preservada”.","Ele respondeu: “Também nisso te atenderei: não destruirei a cidade de que falaste.","Depressa, foge para lá, pois nada poderei fazer até que chegues”. Por isso a cidade foi chamada Zoar.","O sol havia surgido sobre a terra quando Ló chegou a Zoar.","Então YHWH fez chover sobre Sodoma e Gomorra enxofre e fogo, da parte de YHWH, desde os céus.","Destruiu aquelas cidades, toda a planície, todos os habitantes das cidades e o que crescia no solo.","A mulher de Ló olhou para trás e tornou-se uma coluna de sal.","Abraão levantou-se de madrugada e foi ao lugar onde estivera diante de YHWH.","Olhou na direção de Sodoma e Gomorra e de toda a terra da planície; viu a fumaça subir da terra como a fumaça de uma fornalha.","Quando Deus destruiu as cidades da planície, lembrou-se de Abraão e tirou Ló do meio da destruição, quando arrasou as cidades em que Ló havia habitado.","Ló subiu de Zoar e foi morar nos montes com suas duas filhas, pois tinha medo de permanecer em Zoar. Ele habitou numa caverna, ele e suas duas filhas.","A filha mais velha disse à mais nova: “Nosso pai é velho, e não há homem na terra que se una a nós, segundo o costume de toda a terra.","Vem, façamos nosso pai beber vinho e deitemo-nos com ele, para conservarmos descendência de nosso pai”.","Naquela noite deram vinho a seu pai, e a mais velha entrou e se deitou com ele. Ele não percebeu quando ela se deitou nem quando se levantou.","No dia seguinte, a mais velha disse à mais nova: “Na noite passada deitei-me com nosso pai. Vamos fazê-lo beber vinho também esta noite; então entra e deita-te com ele, para conservarmos descendência de nosso pai”.","Também naquela noite deram vinho a seu pai, e a mais nova se deitou com ele. Ele não percebeu quando ela se deitou nem quando se levantou.","Assim, as duas filhas de Ló conceberam de seu pai.","A mais velha deu à luz um filho e chamou seu nome Moabe; ele é o pai dos moabitas até hoje.","A mais nova também deu à luz um filho e chamou seu nome Ben-Ami; ele é o pai dos filhos de Amom até hoje."];
GENESIS_TEXT[20]=["Abraão partiu dali para a região do Neguebe e habitou entre Cades e Sur. Depois permaneceu por algum tempo em Gerar.","Abraão dizia a respeito de Sara, sua mulher: “Ela é minha irmã”. Abimeleque, rei de Gerar, mandou buscar Sara e a tomou.","Mas Deus veio a Abimeleque num sonho durante a noite e lhe disse: “Eis que estás para morrer por causa da mulher que tomaste, pois ela tem marido”.","Abimeleque ainda não havia se aproximado dela. Ele perguntou: “Senhor, matarás até mesmo uma nação inocente?","Não foi ele que me disse: ‘Ela é minha irmã’? E ela também disse: ‘Ele é meu irmão’. Fiz isso com coração íntegro e mãos inocentes”.","Deus lhe respondeu no sonho: “Eu também sei que fizeste isso com coração íntegro; por isso te impedi de pecar contra mim e não permiti que a tocasses.","Agora, devolve a mulher ao marido, pois ele é profeta e intercederá por ti, e viverás. Mas, se não a devolveres, sabe que certamente morrerás, tu e todos os que são teus”.","Abimeleque levantou-se cedo, chamou todos os seus servos e contou-lhes todas essas coisas; os homens ficaram muito assustados.","Abimeleque chamou Abraão e lhe disse: “Que fizeste conosco? Em que pequei contra ti, para trazeres sobre mim e sobre meu reino um pecado tão grande? Fizeste comigo coisas que não se devem fazer”.","Abimeleque perguntou a Abraão: “O que tinhas em vista ao fazer isso?”","Abraão respondeu: “Pensei: certamente não há temor de Deus neste lugar, e me matarão por causa de minha mulher.","Além disso, ela é de fato minha irmã, filha de meu pai, mas não filha de minha mãe; e tornou-se minha mulher.","Quando Deus me fez sair errante da casa de meu pai, eu lhe disse: ‘Esta será a bondade que me farás: em todo lugar aonde chegarmos, dirás a meu respeito: Ele é meu irmão’”.","Abimeleque tomou ovelhas, bois, servos e servas, deu-os a Abraão e devolveu-lhe Sara, sua mulher.","Abimeleque disse: “Minha terra está diante de ti; habita onde te parecer melhor”.","A Sara disse: “Dou a teu irmão mil peças de prata. Isso será para ti uma cobertura diante de todos os que estão contigo; assim estarás plenamente justificada”.","Abraão orou a Deus, e Deus curou Abimeleque, sua mulher e suas servas, de modo que puderam ter filhos.","Pois YHWH havia fechado completamente o ventre de todas as mulheres da casa de Abimeleque por causa de Sara, mulher de Abraão."];

GENESIS_TEXT[21]=["YHWH visitou Sara, como havia dito, e YHWH fez por Sara conforme havia falado.","Sara concebeu e deu a Abraão um filho em sua velhice, no tempo determinado de que Deus lhe havia falado.","Abraão deu o nome de Isaque ao filho que lhe nasceu, que Sara lhe deu à luz.","Abraão circuncidou Isaque, seu filho, quando ele tinha oito dias, conforme Deus lhe havia ordenado.","Abraão tinha cem anos quando Isaque, seu filho, lhe nasceu.","Sara disse: “Deus me deu motivo de riso; todo aquele que ouvir isso rirá comigo”.","E acrescentou: “Quem teria dito a Abraão que Sara amamentaria filhos? Pois lhe dei um filho na sua velhice!”.","O menino cresceu e foi desmamado; e Abraão fez um grande banquete no dia em que Isaque foi desmamado.","Sara viu o filho de Hagar, a egípcia, que ela havia dado a Abraão, zombando.","Ela disse a Abraão: “Expulsa esta serva e seu filho, pois o filho desta serva não herdará com meu filho, com Isaque”.","Isso desagradou muito a Abraão, por causa de seu filho.","Mas Deus disse a Abraão: “Não fique desagradado por causa do rapaz e da tua serva. Em tudo o que Sara te disser, ouve a voz dela, pois é por meio de Isaque que tua descendência será chamada”.","Também farei do filho da serva uma nação, porque ele é tua descendência.","Abraão levantou-se cedo pela manhã, tomou pão e um odre de água, entregou-os a Hagar, colocando-os sobre o ombro dela, e também lhe entregou o menino; então a despediu. Ela partiu e andou errante pelo deserto de Berseba.","Quando a água do odre acabou, ela deixou o menino debaixo de um dos arbustos.","Então foi sentar-se à distância, à distância de um tiro de arco, pois dizia: “Não quero ver a morte do menino”. Sentou-se à distância, levantou a voz e chorou.","Deus ouviu a voz do rapaz, e o mensageiro de Deus chamou Hagar desde os céus e lhe disse: “O que tens, Hagar? Não temas, pois Deus ouviu a voz do rapaz, no lugar onde ele está”.","Levanta-te, ergue o rapaz e segura-o pela mão, pois farei dele uma grande nação.","Então Deus abriu os olhos dela, e ela viu um poço de água. Foi até lá, encheu o odre de água e deu de beber ao rapaz.","Deus estava com o rapaz; ele cresceu, habitou no deserto e tornou-se arqueiro.","Ele habitou no deserto de Parã, e sua mãe tomou para ele uma mulher da terra do Egito.","Naquele tempo, Abimeleque e Ficol, comandante de seu exército, disseram a Abraão: “Deus está contigo em tudo o que fazes.","Agora, jura-me aqui por Deus que não agirás falsamente comigo, nem com meus descendentes nem com minha posteridade; segundo a bondade que te demonstrei, agirás comigo e com a terra em que tens residido como estrangeiro”.","Abraão respondeu: “Eu jurarei”.","Abraão, porém, repreendeu Abimeleque por causa do poço de água que os servos de Abimeleque haviam tomado à força.","Abimeleque disse: “Não sei quem fez isso. Tu não me informaste, e eu também não ouvi falar disso até hoje”.","Abraão tomou ovelhas e bois e os deu a Abimeleque; e os dois fizeram uma aliança.","Abraão separou sete cordeiras do rebanho.","Abimeleque perguntou a Abraão: “Que significam estas sete cordeiras que separaste?”.","Ele respondeu: “Receberás estas sete cordeiras de minha mão, para que sejam testemunho para mim de que cavei este poço”.","Por isso aquele lugar foi chamado Berseba, porque ali os dois fizeram juramento.","Assim fizeram uma aliança em Berseba. Depois Abimeleque e Ficol, comandante de seu exército, levantaram-se e voltaram à terra dos filisteus.","Abraão plantou uma tamargueira em Berseba e ali invocou o nome de YHWH, Deus eterno.","Abraão residiu como estrangeiro na terra dos filisteus por muitos dias."];
GENESIS_TEXT[22]=["E aconteceu depois destas coisas, que tentou Deus a Abraão, e disse-lhe: Abraão! E ele disse: Eis-me aqui.","E disse: Toma agora o teu filho, o teu unico filho, Isaac, a quem amas, e vae-te a terra de Moriah, e offerece-o ali em holocausto sobre uma das montanhas, que eu te direi.","Então se levantou Abraão pela manhã de madrugada, e albardou o seu jumento, e tomou comsigo dois de seus moços e Isaac seu filho; e fendeu lenha para o holocausto, e levantou-se, e foi ao lugar que Deus lhe dissera.","Ao terceiro dia levantou Abraão os seus olhos, e viu o lugar de longe.","E disse Abraão a seus moços: Ficae-vos aqui com o jumento, e eu e o moço iremos até ali; e havendo adorado, tornaremos a vós","E tomou Abraão a lenha do holocausto, e pôl-a sobre Isaac seu filho; e ele tomou o fogo e o cutelo na sua mão, e foram ambos juntos.","Então falou Isaac a Abraão seu pai, e disse: Meu pai! E ele disse: Eis-me aqui, meu filho! E ele disse: Eis aqui o fogo e a lenha, mas onde esta o cordeiro para o holocausto?","E disse Abraão: Deus provera para si o cordeiro para o holocausto, meu filho. Assim caminharam ambos juntos.","E vieram ao lugar que Deus lhe dissera, e edificou Abraão ali um altar, e pôs em ordem a lenha, e amarrou a Isaac seu filho, e deitou-o sobre o altar em cima da lenha.","E estendeu Abraão a sua mão, e tomou o cutelo para immolar o seu filho;","Mas o anjo do Senhor lhe bradou desde os céus, e disse: Abraão, Abraão! E ele disse: Eis-me aqui.","Então disse: Não estendas a tua mão sobre o moço, e não lhe faças nada: porquanto agora sei que temes a Deus, e não me negaste o teu filho, o teu unico.","Então levantou Abraão o seus olhos, e olhou; e eis um carneiro detraz dele, travado pelas suas pontas num matto; e foi Abraão, e tomou o carneiro, e offereceu-o em holocausto, em lugar de seu filho.","E chamou Abraão o nome daquele lugar, o Senhor provera; d'onde se diz até ao dia de hoje: No monte do Senhor se provera.","Então o anjo do Senhor bradou a Abraão pela segunda vez desde os céus,","E disse: Por mim mesmo, jurei, diz o Senhor: Porquanto fizeste esta acção, e não negaste o teu filho, o teu unico,","Que devéras te abençoarei, e grandissimamente multiplicarei a tua semente como as estrelas dos céus, e como a areia que esta na praia do mar; e a tua semente possuira a porta dos seus inimigos;","E em tua semente serão bemditas todas as nações da terra; porquanto obedeceste a minha voz","Então Abraão tornou aos seus moços, e levantaram-se, e foram juntos para Berseba; e Abraão habitou em Berseba.","E sucedeu depois destas coisas, que annunciaram a Abraão, dizendo: Eis que também Milcah pariu filhos a Nahor teu irmão:","Uz o seu primogenito, e Buz seu irmão, e Kemuel, pai d'Aram,","E Chesed, e Hazo, e Pildas, e Jidlaph, e Bethuel.","E Bethuel gerou Rebecca: estes oito pariu Milcah a Nahor, irmão de Abraão.","E a sua concubina, cujo nome era Reuma, ela pariu também a Tebah, e Gaham, e Tahash e Maacah."];
GENESIS_TEXT[23]=["E foi a vida de Sarah cento e vinte e sete anos: estes foram os anos da vida de Sarah.","E morreu Sarah em Kiriath-arba, que é Hebron, na terra de Canaã; e veiu Abraão lamentar a Sarah e chorar por ela.","Depois se levantou Abraão de diante do seu morto, e falou aos filhos de Heth, dizendo:","Estrangeiro e peregrino sou entre vós: dae-me possessão de sepultura comvosco, para que eu sepulte o meu morto de diante da minha face.","E responderam os filhos de Heth a Abraão, dizendo-lhe:","Ouve-nos, meu senhor; principe de Deus és no meio de nós; enterra o teu morto na mais escolhida de nossas sepulturas; nenhum de nós te vedara a sua sepultura, para enterrar o teu morto.","Então se levantou Abraão, e inclinou-se diante do povo da terra, diante dos filhos de Heth.","E falou com eles, dizendo: Se é de vossa vontade que eu sepulte o meu morto de diante de minha face, ouvi-me e fallae por mim a Ephron, filho de Zohar,","Que ele me dê a cova de Machpelah, que ele tem no fim do seu campo; que m'a dê pelo devido preço em herança de sepulchro no meio de vós","Ora Ephron habitava no meio dos filhos de Heth: e respondeu Ephron hetheo a Abraão, aos ouvidos dos filhos de Heth, de todos os que entravam pela porta da sua cidade, dizendo:","Não, meu senhor: ouve-me, o campo te dou, também te dou a cova que nele esta, diante dos olhos dos filhos do meu povo t'a dou; sepulta o teu morto.","Então Abraão se inclinou diante da face do povo da terra,","E falou a Ephron, aos ouvidos do povo da terra, dizendo: Mas se tu estàs por isto, ouve-me, peço-te: o preço do campo o darei; toma-o de mim, e sepultarei ali o meu morto.","E respondeu Ephron a Abraão, dizendo-lhe:","Meu senhor, ouve-me, a terra é de quatrocentos siclos de prata; que é isto entre mim e ti? sepulta o teu morto.","E Abraão deu ouvidos a Ephron e Abraão pesou a Ephron a prata de que tinha fallado aos ouvidos dos filhos de Heth, quatrocentos siclos de prata, correntes entre mercadores.","Assim o campo de Ephron, que estava em Machpelah, em frente de Mamre, o campo e a cova que nele estava, e todo o arvoredo que no campo havia, que estava em todo o seu contorno ao redor,","Se confirmou a Abraão em possessão diante dos olhos dos filhos de Heth, de todos os que entravam pela porta da sua cidade.","E depois sepultou Abraão a Sarah sua mulher na cova do campo de Machpelah, em frente de Mamre, que é Hebron, na terra de Canaã.","Assim o campo e a cova que nele estava se confirmou a Abraão em possessão de sepultura pelos filhos de Heth."];
GENESIS_TEXT[24]=["E era Abraão ja velho e adiantado em idade, e o Senhor havia abençoado a Abraão em tudo.","E disse Abraão ao seu servo, o mais velho da casa, que tinha o governo sobre tudo o que possuia: Põe agora a tua mão debaixo da minha coxa,","Para que eu te faça jurar pelo Senhor Deus dos céus e Deus da terra, que não tomaràs para meu filho mulher das filhas dos cananeos no meio dos quaes eu habito,","Mas que iràs a minha terra e a minha parentela, e dali tomaràs mulher para meu filho Isaac.","E disse-lhe o servo: Porventura não querera seguir-me a mulher a esta terra. Farei pois tornar o teu filho a terra d'onde saiste?","E Abraão lhe disse: Guarda-te, que não faças la tornar o meu filho.","O Senhor, Deus dos céus, que me tomou da casa de meu pai e da terra da minha parentela, e que me falou, e que me jurou, dizendo: A tua semente darei esta terra: Ele enviara o seu anjo adiante da tua face, para que tomes mulher de la para meu filho.","Se a mulher, porém, não quizer seguir-te, seràs livre deste meu juramento; somente não faças la tornar a meu filho.","Então pôs o servo a sua mão debaixo da coxa de Abraão seu senhor, e jurou-lhe sobre este negocio.","E o servo tomou dez camelos, dos camelos do seu senhor, e partiu, pois que toda a fazenda de seu senhor estava em sua mão, e levantou-se e partiu para Mesopotamia, para a cidade de Nahor,","E fez ajoelhar os camelos fora da cidade, junto a um poço d'agua, pela tarde, ao tempo que as moças sahiam a tirar agua.","E disse: Ó Senhor, Deus de meu senhor Abraão! da-me hoje bom encontro, e faze beneficencia ao meu senhor Abraão!","Eis que eu estou em pé junto a fonte d'agua, e as filhas dous varões desta cidade saem para tirar agua;","Seja pois que a donzela, a quem eu disser: Abaixa agora o teu cantaro para que eu beba; e ela disser: Bebe, e também darei de beber aos teus camelos; esta seja a quem designaste ao teu servo Isaac, e que eu conheça n'isso que fizeste beneficencia a meu senhor.","E sucedeu que, antes que ele acabasse de falar, eis que Rebecca, que havia nascido a Bethuel, filho de Milcah, mulher de Nahor, irmão de Abraão, sahia com o seu cantaro sobre o seu hombro.","E a donzela era mui formosa a vista, virgem, a quem varão não havia conhecido: e desceu a fonte, e encheu o seu cantaro, e subiu.","Então o servo correu-lhe ao encontro, e disse: Ora deixa-me beber uma pouca d'agua do teu cantaro.","E ela disse: Bebe, meu senhor. E apressou-se, e abaixou o seu cantaro sobre a sua mão, e deu-lhe de beber.","E, acabando ela de lhe dar de beber, disse: Tirarei também agua para os teus camelos, até que acabem de beber.","E apressou-se, e vasou o seu cantaro na pia, e correu outra vez ao poço para tirar agua, e tirou para todos os seus camelos.","E o varão estava admirado de vel-a, calando-se, para saber se o Senhor havia prosperado a sua jornada, ou não.","E aconteceu que, acabando os camelos de beber, tomou o varão um pendente de oiro de meio siclo de peso, e duas pulseiras para as suas mãos, do peso de dez siclos de oiro.","E disse: De quem és filha? faze-m'o saber, peço-te; ha também em casa de teu pai lugar para nós pousarmos?","E ela lhe disse: Eu sou a filha de Bethuel, filho de Milcah, o qual ela pariu a Nahor.","Disse-lhe mais: Também temos palha e muito pasto, e lugar para passar a noite.","Então inclinou-se aquele varão, e adorou ao Senhor,","E disse: Bemdito seja o Senhor Deus de meu senhor Abraão, que não retirou a sua beneficencia e a sua verdade de meu senhor: quanto a mim, o Senhor me guiou no caminho a casa dos irmãos de meu senhor.","E a donzela correu, e fez saber estas coisas na casa de sua mãe.","E Rebecca tinha um irmão, cujo nome era Labão; e Labão correu ao encontro daquele varão a fonte.","E aconteceu que, quando ele viu o pendente, e as pulseiras sobre as mãos de sua irmã, e quando ouviu as palavras de sua irmã Rebecca, que dizia: Assim me falou aquele varão; veiu o varão, e eis que estava em pé junto aos camelos a fonte.","E disse: Entra, bemdito do Senhor, porque estaràs fora? pois eu ja preparei a casa, e o lugar para os camelos.","Então veiu aquele varão a casa, e desataram os camelos, e deram palha e pasto aos camelos, e agua para lavar os pés dele e os pés dos varões que estavam com ele.","Depois pôseram de comer diante dele; ele porém disse: Não comerei, até que tenha dito as minhas palavras. E ele disse: Falla.","Então disse: Eu sou o servo d'Abraão.","E o Senhor abençoou muito o meu senhor, de maneira que foi engrandecido, e deu-lhe ovelhas e vacas, e prata e oiro, e servos e servas, e camelos e jumentos.","E Sarah, a mulher do meu senhor, pariu um filho a meu senhor depois da sua velhice, e ele deu-lhe tudo quanto tem.","E meu senhor me fez jurar, dizendo: Não tomaràs mulher para meu filho das filhas dos cananeos, em cuja terra habito:","Iràs porém a casa de meu pai, e a minha familia, e tomaràs mulher para meu filho.","Então disse eu ao meu senhor: Porventura não me seguira a mulher.","E ele me disse: O Senhor, em cuja presença tenho andado, enviara o seu anjo comtigo, e prosperara o teu caminho, para que tomes mulher para meu filho da minha familia e da casa de meu pai:","Então seràs livre do meu juramento, quando fores a minha familia; e se não t'a derem, livre seràs do meu juramento.","E hoje cheguei a fonte, e disse: Ó Senhor, Deus de meu senhor Abraão! se tu agora prosperas o meu caminho, no qual eu ando,","Eis que estou junto a fonte d'agua: seja pois que a donzela que sair para tirar agua e a qual eu disser: Ora da-me uma pouca d'agua do teu cantaro;","E ela me disser: Bebe tu também, e também tirarei agua para os teus camelos; esta seja a mulher que o Senhor designou ao filho de meu senhor.","E antes que eu acabasse de falar no meu coração, eis que Rebecca sahia com o seu cantaro sobre o seu hombro, e desceu a fonte, e tirou agua; e eu lhe disse: Ora da-me de beber.","E ela se apressou, e abaixou o seu cantaro de sobre si, e disse: Bebe, e também darei de beber aos teus camelos; e bebi, e ela deu também de beber aos camelos.","Então lhe perguntei, e disse: De quem és filha? E ela disse: Filha de Bethuel, filho de Nahor, que lhe pariu Milcah. Então eu puz o pendente no seu rosto, e as pulseiras sobre as suas mãos;","E inclinando-me adorei ao Senhor, e bemdisse ao Senhor, Deus do meu senhor Abraão, que me havia encaminhado pelo caminho da verdade, para tomar a filha do irmão de meu senhor para seu filho.","Agora pois, se vós haveis de fazer beneficencia e verdade a meu senhor, fazei-m'o saber; e se não também m'o fazei saber, para que eu olhe a mão direita, ou a esquerda.","Então responderam Labão e Bethuel, e disseram: Do Senhor procedeu este negocio; não podemos falar-te mal ou bem.","Eis que, Rebecca esta diante da tua face; toma-a, e vae-te; seja a mulher do filho de teu senhor, como tem dito o Senhor.","E aconteceu que, o servo de Abraão, ouvindo as suas palavras, inclinou-se a terra diante do Senhor,","E tirou o servo vasos de prata e vasos de oiro, e vestidos, e deu-os a Rebecca; também deu coisas preciosas a seu irmão e a sua mãe.","Então comeram e beberam, ele e os varões que com ele estavam, e passaram a noite. E levantaram-se pela manhã, e disse: Deixae-me ir a meu senhor.","Então disseram seu irmão e sua mãe: Fique a donzela comnosco alguns dias, ou pelo menos dez dias, depois ira.","Ele porém lhes disse: Não me detenhaes, pois o Senhor tem prosperado o meu caminho; deixae-me partir, que eu volte a meu senhor.","E disseram: Chamemos a donzela, e perguntemos-lh'o.","E chamaram a Rebecca, e disseram-lhe: Iràs tu com este varão? Ela respondeu: Irei.","Então despediram a Rebecca sua irmã, e sua ama, e o servo de Abraão, e seus varões","E abençoaram a Rebecca, e disseram-lhe: O nossa irmã, sejas tu em milhares de milhares, e que a tua semente possua a porta de seus aborrecedores!","E Rebecca se levantou com as suas moças, e subiram sobre os camelos, e seguiram o varão: e tomou aquele servo a Rebecca, e partiu.","Ora Isaac vinha d'onde se vem do poço de Lahai-roi; porque habitava na terra do sul.","E Isaac saira a orar no campo, sobre a tarde: e levantou os seus olhos, e olhou, e eis que os camelos vinham.","Rebecca também levantou seus olhos, e viu a Isaac, e lançou-se do camelo.","E disse ao servo: Quem é aquele varão que vem pelo campo ao nosso encontro? E o servo disse: Este é meu senhor. Então tomou ela o véu, e cobriu-se.","E o servo contou a Isaac todas as coisas que fizera.","E Isaac trouxe-a para a tenda de sua mãe Sarah, e tomou a Rebecca, e foi-lhe por mulher, e amou-a. Assim Isaac foi consolado depois da morte de sua mãe."];
GENESIS_TEXT[25]=["E Abraão tomou outra mulher; e o seu nome era Ketura;","E pariu-lhe Zimran, e Joksan, e Medan, e Midian, e Jisbac, e Shuah.","E Joksan gerou Seba e Dedan: e os filhos de Dedan foram Assurim, e Letusim e Leummim.","E os filhos de Midian foram Epha, e Epher, e Henoch, e Abidah, e Eldah: estes todos foram filhos de Ketura.","Porém Abraão deu tudo o que tinha a Isaac;","Mas aos filhos das concubinas que Abraão tinha, deu Abraão presentes, e, vivendo ele ainda, despediu-os do seu filho Isaac, ao oriente, para a terra oriental.","Estes pois são os dias dos anos da vida de Abraão, que viveu cento e setenta e cinco anos.","E Abraão expirou e morreu em boa velhice, velho e farto de dias: e foi congregado ao seu povo;","E sepultaram-o Isaac e Ishmael, seus filhos, na cova de Machpelah, no campo d'Ephron, filho de Zohar hetheo, que estava em frente de Mamre,","O campo que Abraão comprara aos filhos de Heth. Ali esta sepultado Abraão, e Sarah sua mulher.","E aconteceu depois da morte de Abraão, que Deus abençoou a Isaac seu filho; e habitava Isaac junto ao poço Lahai-roi.","Estas porém são as gerações de Ishmael filho de Abraão, que a serva de Sarah, Hagar Egypcia, pariu a Abraão.","E estes são os nomes dos filhos de Ishmael pelos seus nomes, segundo as suas gerações: o primogenito de Ishmael era Nebajoth, depois Kedar, e Abdeel, e Mibsam,","E Misma, e Duma, e Massa,","Hadar, e Tema, Jetur, Nafis, e Kedma.","Estes são os filhos de Ishmael, e estes são os seus nomes pelas suas villas e pelos seus castellos: doze principes segundo as suas familias.","E estes são os anos da vida de Ishmael, cento e trinta e sete anos; e ele expirou, e morreu, e foi congregado ao seu povo.","E habitaram desde Havila até Sur, que esta em frente do Egito, indo para Assur; e fez o seu assento diante da face de todos os seus irmãos.","E estas são as gerações de Isaac, filho de Abraão: Abraão gerou a Isaac:","E era Isaac da idade de quarenta anos, quando tomou a Rebecca, filha de Bethuel arameo de Paddan-aram, irmã de Labão arameo, por sua mulher.","E Isaac orou instantemente ao Senhor por sua mulher, porquanto era esteril; e o Senhor ouviu as suas orações, e Rebecca sua mulher concebeu.","E os filhos luctavam dentro dela; então disse: Se assim é, porque sou eu assim? E foi-se a perguntar ao Senhor.","E o Senhor lhe disse: Duas nações ha no teu ventre, e dois povos se dividirão das tuas entranhas, e um povo-*sera mais forte do que o outro povo, e o maior servira ao menor.","E cumprindo-se os seus dias para parir, eis gemeos no seu ventre.","E saiu o primeiro ruivo e todo como um vestido cabelludo; por isso chamaram o seu nome Esaú.","E depois saiu o seu irmão, agarrada sua mão ao calcanhar de Esaú; por isso se chamou o seu nome Jacó. E era Isaac da idade de sessenta anos quando os gerou.","E cresceram os meninos, e Esaú foi varão perito na caça, varão do campo; mas Jacó era varão simples, habitando em tendas.","E amava Isaac a Esaú, porque a caça era de seu gosto, mas Rebecca amava a Jacó.","E Jacó cozera um guisado; e veiu Esaú do campo, e estava ele cançado:","E disse Esaú a Jacó: Deixa-me, peço-te, sorver d'esse guisado vermelho, porque estou cançado. Por isso se chamou o seu nome Edom.","Então disse Jacó: Vende-me hoje a tua primogenitura.","E disse Esaú: Eis que estou a ponto de morrer, e para que me servira logo a primogenitura?","Então disse Jacó: Jura-me hoje. E jurou-lhe e vendeu a sua primogenitura a Jacó.","E Jacó deu pão a Esaú e o guisado das lentilhas; e comeu, e bebeu, e levantou-se, e foi-se. Assim desprezou Esaú a sua primogenitura."];
GENESIS_TEXT[26]=["E havia fome na terra, além da primeira fome, que foi nos dias de Abraão: por isso foi-se Isaac a Abimelech, rei dos philisteus, em Gerar.","E apareceu-lhe o Senhor, e disse: Não desças ao Egito; habita na terra que eu te disser:","Peregrina n'esta terra, e serei comtigo, e te abençoarei; porque a ti e a tua semente darei todas estas terras, e confirmarei o juramento que tenho jurado a Abraão teu pai;","E multiplicarei a tua semente como as estrelas dos céus, e darei a tua semente todas estas terras; e em tua semente serão bemditas todas as nações da terra;","Porquanto Abraão obedeceu a minha voz, e guardou o meu mandado, os meus preceitos, os meus estatutos, e as minhas leis.","Assim habitou Isaac em Gerar.","E perguntando-lhe os varões daquele lugar acerca de sua mulher, disse: É minha irmã; porque temia de dizer: É minha mulher; para que porventura (dizia ele) me não matem os varões daquele lugar por amor de Rebecca; porque era formosa a vista.","E aconteceu que, como ele esteve ali muito tempo, Abimelech rei dos philisteus olhou por uma janela, e viu, e eis que Isaac estava brincando com Rebecca sua mulher.","Então chamou Abimelech a Isaac, e disse: Eis que na verdade é tua mulher; como pois disseste: É minha irmã? E disse-lhe Isaac: Porque eu dizia: Para que eu porventura não morra por causa dela.","E disse Abimelech: Que é isto que nos fizeste? Facilmente se teria deitado alguem deste povo com a tua mulher, e tu terias trazido sobre nós um delicto.","E mandou Abimelech a todo o povo, dizendo: Qualquer que tocar a este varão ou a sua mulher, certamente morrera.","E semeou Isaac n'aquela mesma terra, e achou n'aquele mesmo ano cem medidas, porque o Senhor o abençoava.","E engrandeceu-se o varão, e ia-se engrandecendo, até que se tornou mui grande;","E tinha possessão d'ovelhas, e possessão de vacas, e muita gente de serviço, de maneira que os philisteus o invejavam.","E todos os poços, que os servos de seu pai tinham cavado nos dias de seu pai Abraão, os philisteus entulharam e encheram de terra.","Disse também Abimelech a Isaac: Aparta-te de nós; porque muito mais poderoso te tens feito do que nós.","Então Isaac foi-se d'ali e fez o seu assento no valle de Gerar, e habitou la.","E tornou Isaac, e cavou os poços d'agua que cavaram nos dias de Abraão seu pai, e que os philisteus taparam depois da morte de Abraão, e chamou-*os pelos nomes que os chamara seu pai.","Cavaram pois os servos de Isaac n'aquele valle, e acharam ali um poço d'aguas vivas.","E os pastores de Gerar porfiaram com os pastores de Isaac, dizendo. Esta agua é nossa. Por isso chamou o nome daquele poço Esek, porque contenderam com ele.","Então cavaram outro poço, e também porfiaram sobre ele: por isso chamou o seu nome Sitnah.","E partiu d'ali, e cavou outro poço, e não porfiaram sobre ele: por isso chamou o seu nome Rehoboth, e disse: Porque agora nos alargou o Senhor, e crescemos n'esta terra.","Depois subiu d'ali a Berseba,","E apareceu-lhe o Senhor n'aquela mesma noite, e disse: Eu sou o Deus de Abraão teu pai: não temas, porque eu sou comtigo, e abençoar-te-hei, e multiplicarei a tua semente por amor de Abraão meu servo.","Então edificou ali um altar, e invocou o nome do Senhor, e armou ali a sua tenda; e os servos de Isaac cavaram ali um poço.","E Abimelech veiu a ele de Gerar, com Ahuzzath seu amigo, e Phichol, principe do seu exercito.","E disse-lhes Isaac: Porque viestes a mim, pois que vós me aborreceis, e me enviastes de vós?","E eles disseram: Havemos visto, na verdade, que o Senhor é comtigo, pelo que dissemos: Haja agora juramento entre nós, entre nós e ti; e façamos concerto comtigo,","Que nos não faças mal, como nós te não temos tocado, e como te fizemos somente bem, e te deixamos ir em paz. Agora tu és o bemdito do Senhor","Então lhes fez um banquete, e comeram e beberam;","E levantaram-se de madrugada, e juraram um ao outro; depois os despediu Isaac, e despediram-se dele em paz.","E aconteceu n'aquele mesmo dia que vieram os servos de Isaac, e annunciaram-lhe acerca do negocio do peço, que tinham cavado; e disseram-lhe: Temos achado agua.","E chamou-o Seba: por isso é o nome daquela cidade Berseba até o dia de hoje.","Ora sendo Esaú da idade de quarenta anos, tomou por mulher a Judith, filha de Beeri, hetheo, e a Basmath filha de Elon, hetheo.","E estas foram a Isaac e a Rebecca uma amargura de espirito."];
GENESIS_TEXT[27]=["E aconteceu que, como Isaac envelheceu, e os seus olhos se escureceram, de maneira que não podia ver, chamou a Esaú, seu filho mais velho, e disse-lhe: Meu filho. E ele lhe disse: Eis-me aqui.","E ele disse: Eis que ja agora estou velho, e não sei o dia da minha morte;","Agora pois, toma as tuas armas, a tua aljava e o teu arco, e sae ao campo, e apanha para mim alguma caça,","E faze-me um guisado saboroso, como eu o amo, e traze-m'o, para que eu coma; para que minha alma te abençoe, antes que morra.","E Rebecca escutou quando Isaac fallava ao seu filho Esaú: e foi-se Esaú ao campo, para apanhar caça que havia de trazer.","Então falou Rebecca a Jacó seu filho, dizendo: Eis que tenho ouvido o teu pai que fallava com Esaú teu irmão, dizendo:","Traze-me caça, e faze-me um guisado saboroso, para que eu coma, e te abençoe diante da face do Senhor, antes da minha morte.","Agora pois, filho meu, ouve a minha voz n'aquillo que eu te mando:","Vae agora ao rebanho, e traze-me de la dois bons cabritos das cabras, e eu farei deles um guisado saboroso para teu pai, como ele ama,","E leval-o-has a teu pai, para que o coma; para que te abençoe antes da sua morte.","Então disse Jacó a Rebecca, sua mãe: Eis que Esaú meu irmão é varão cabelludo. e eu varão liso;","Porventura me apalpara o meu pai, e serei em seus olhos enganador: assim trarei eu sobre mim maldição, e não benção.","E disse-lhe sua mãe: Meu filho, sobre mim seja a tua maldição; somente obedece a minha voz, e vae, traze-m'os.","E foi, e tomou-os, e trouxe-os a sua mãe; e sua mãe fez um guisado saboroso, como seu pai amava.","Depois tomou Rebecca os vestidos de gala de Esaú, seu filho mais velho, que tinha comsigo em casa, e vestiu a Jacó, seu filho menor;","E com as peles dos cabritos das cabras cobriu as suas mãos e a lisura do seu pescoço;","E deu o guisado saboroso, e o pão que tinha preparado, na mão de Jacó seu filho.","E veiu ele a seu pai, e disse: Meu pai! E ele disse: Eis-me aqui; quem és tu, meu filho?","E Jacó disse a seu pai: Eu sou Esaú, teu primogenito; tenho feito como me disseste: levanta-te agora, assenta-te, e come da minha caça, para que a tua alma me abençoe.","Então disse Isaac a seu filho: Como é isto, que tão cedo a achaste, filho meu? E ele disse: Porque o Senhor teu Deus a mandou ao meu encontro.","E disse Isaac a Jacó: Chega-te agora, para que te apalpe, meu filho, se és meu filho Esaú mesmo, ou não.","Então se chegou Jacó a Isaac seu pai, que o apalpou, e disse: A voz é a voz de Jacó, porém as mãos são as mãos de Esaú.","E não o conheceu, porquanto as suas mãos estavam cabelludas, como as mãos de Esaú seu irmão: e abençoou-o.","E disse: És tu meu filho Esaú mesmo? E ele disse: Eu sou.","Então disse: Faze chegar isso perto de mim, para que coma da caça de meu filho; para que a minha alma te abençoe. E chegou-lh'o, e comeu; trouxe-lhe também vinho, e bebeu.","E disse-lhe Isaac seu pai: Ora chega-te, e beija-me, filho meu.","E chegou-se, e beijou-o; então cheirou o cheiro dos seus vestidos, e abençoou-o, e disse: Eis que o cheiro do meu filho é como o cheiro do campo, que o Senhor abençoou:","Assim pois te dê Deus do orvalho dos céus, e das gorduras da terra, e abundancia de trigo e de mosto:","Sirvam-te povos, e nações se incurvem a ti: sê senhor de teus irmãos, e os filhos da tua mãe se incurvem a ti: malditos sejam os que te amaldiçoarem, e bemditos sejam os que te abençoarem.","E aconteceu que, acabando Isaac de abençoar a Jacó, apenas Jacó acabava de sair da face de Isaac seu pai, veiu Esaú, seu irmão, da sua caça;","E fez também ele um guisado saboroso, e trouxe-o a seu pai; e disse a seu pai: Levanta-te, meu pai, e come da caça de teu filho, para que me abençoe a tua alma.","E disse-lhe Isaac seu pai: Quem és tu? E ele disse: Eu sou teu filho, o teu primogenito, Esaú.","Então estremeceu Isaac de um estremecimento muito grande; e disse: Quem, pois, é aquele que apanhou a caça, e m'a trouxe? e comi de tudo, antes que tu viesses, e abençoei-o: também sera bemdito.","Esaú, ouvindo as palavras de seu pai, bradou com grande e mui amargo brado, e disse a seu pai: Abençoa-me também a mim, meu pai.","E ele disse: Veiu o teu irmão com subtileza, e tomou a tua benção.","Então disse ele: Não foi o seu nome justamente chamado Jacó, por isso que ja duas vezes me enganou? a minha primogenitura me tomou, e eis que agora me tomou a minha benção. Mais disse: Não reservaste pois para mim benção alguma?","Então respondeu Isaac, e disse a Esaú: Eis que o tenho posto por senhor sobre ti, e todos os seus irmãos lhe tenho dado por servos: e de trigo e de mosto o tenho fortalecido;--que te farei pois agora a ti, meu filho?","E disse Esaú a seu pai: Tens uma só benção, meu pai? abençoa-me também a mim, meu pai. E levantou Esaú a sua voz, e chorou.","Então respondeu Isaac seu pai, e disse-lhe: Eis que nas gorduras da terra sera a tua habitação, e do orvalho dos céus do alto seràs abençoado,","E pela tua espada viveràs, e ao teu irmão serviràs. Acontecera, porém, que quando te senhoreares, então sacudiràs o seu jugo do teu pescoço.","E aborreceu Esaú a Jacó por causa daquela benção, com que seu pai o tinha abençoado; e Esaú disse no seu coração: Chegar-se-hão os dias de luto de meu pai: e matarei a Jacó meu irmão.","E foram denunciadas a Rebecca estas palavras de Esaú, seu filho mais velho; e ela enviou, e chamou a Jacó seu filho menor, e disse-lhe: Eis que Esaú teu irmão se consola a teu respeito, propondo-se matar-te.","Agora pois, meu filho, ouve a minha voz, e levanta-te; acolhe-te a Labão meu irmão, em Haran,","E mora com ele alguns dias, até que passe o furor de teu irmão;","Até que se desvie de ti a ira de teu irmão, e se esqueça do que lhe fizeste: então enviarei, e te farei vir de la; porque seria eu desfilhada também de vós ambos num mesmo dia?","E disse Rebecca a Isaac: Enfadada estou da minha vida, por causa das filhas de Heth; se Jacó tomar mulher das filhas de Heth, como estas são das filhas desta terra, para que me sera a vida?"];
GENESIS_TEXT[28]=["E Isaac chamou a Jacó, e abençoou-o, e ordenou-lhe, e disse-lhe: Não tomes mulher de entre as filhas de Canaã:","Levanta-te, vae a Paddan-aram, a casa de Bethuel, pai de tua mãe, e toma de la uma mulher das filhas de Labão, irmão de tua mãe;","E Deus Todo-poderoso te abençoe, e te faça fructificar, e te multiplique, para que sejas uma multidão de povos;","E te dê abenção de Abraão, a ti e a tua semente comtigo, para que em herança possuas a terra de tuas peregrinações, que Deus deu a Abraão","Assim enviou Isaac a Jacó, o qual se foi a Paddan-aram, a Labão, filho de Bethuel arameo, irmão de Rebecca, mãe de Jacó e de Esaú.","Vendo pois Esaú que Isaac abençoara a Jacó, e o enviara a Paddan-aram, para tomar mulher para si d'ali, e que, abençoando-o, lhe ordenara, dizendo: Não tomes mulher das filhas de Canaã;","E que Jacó obedecera a seu pai e a sua mãe, e se fôra a Paddan-aram;","Vendo também Esaú que as filhas de Canaã eram màs aos olhos de Isaac seu pai,","Foi-se Esaú a Ishmael, e tomou para si por mulher, além das suas mulheres, a Mahalath filha de Ishmael, filho de Abraão, irmã de Nebajoth.","Partiu pois Jacó de Berseba, e foi-se a Haran;","E chegou a um lugar onde passou a noite, porque ja o sol era posto; e tomou uma das pedras daquele lugar, e a pôs por sua cabeceira, e deitou-se n'aquele lugar,","E sonhou: e eis uma escada era posta na terra, cujo topo tocava nos céus: e eis que os anjos de Deus subiam e desciam por ela;","E eis que o Senhor estava em cima dela, e disse: Eu sou o Senhor, o Deus de Abraão teu pai, e o Deus de Isaac: esta terra, em que estàs deitado, t'a darei a ti e a tua semente:","E a tua semente sera como o pó da terra, e estender-se-ha ao occidente, e ao oriente, e ao norte, e ao sul, e em ti e na tua semente serão bemditas todas as familias da terra:","E eis que estou comtigo, e te guardarei por onde quer que fores, e te farei tornar a esta terra: porque te não deixarei, até que te haja feito o que te tenho dito.","Acordado pois Jacó do seu somno, disse: Na verdade o Senhor esta n'este lugar; e eu não o sabia.","E temeu, e disse: Quão terrivel é este lugar! Este não é outro lugar senão a casa de Deus; e este é a porta dos céus.","Então levantou-se Jacó pela manhã de madrugada, e tomou a pedra que tinha posto por sua cabeceira, e a pôs por columna, e derramou azeite em cima dela.","E chamou o nome daquele lugar Bethel: o nome porém daquela cidade d'antes era Luz.","E Jacó votou um voto, dizendo: Se Deus fôr commigo, e me guardar n'esta viagem que faço, e me der pão para comer, e vestidos para vestir;","E eu em paz tornar a casa de meu pai, o Senhor me sera por Deus;","E esta pedra que tenho posto por columna sera casa de Deus; e de tudo quanto me deres, certamente te darei o dizimo."];
GENESIS_TEXT[29]=["Então pôs-se Jacó a pé, e foi-se a terra dos filhos de oriente;","E olhou, e eis um poço no campo, e eis tres rebanhos d'ovelhas que estavam deitados junto a ele; porque daquele poço davam de beber aos rebanhos: e havia uma grande pedra sobre a bocca do poço.","E ajuntavam ali todos os rebanhos, e removiam a pedra de sobre a bocca do poço, e davam de beber às ovelhas: e tornavam a pôr a pedra sobre a bocca do poço, no seu lugar.","E disse-lhes Jacó: Meus irmãos, d'onde sois? E disseram: Somos de Haran.","E ele lhes disse: Conheceis a Labão, filho de Nachor? E disseram: Conhecemos.","Disse-lhes mais: Esta ele bem? E disseram: Esta bem, e eis aqui Raquel sua filha, que vem com as ovelhas.","E ele disse: Eis que ainda é muito dia, não é tempo de ajuntar o gado; dae de beber às ovelhas, e ide, apascentae-as.","E disseram: Não podemos, até que todos os rebanhos se ajuntem, e removam a pedra de sobre a bocca do poço, para que demos de beber às ovelhas.","Estando ele ainda fallando com eles, veiu Raquel com as ovelhas de seu pai: porque ela era pastora.","E aconteceu que, vendo Jacó a Raquel, filha de Labão, irmão de sua mãe, e as ovelhas de Labão, irmão de sua mãe, chegou Jacó, e revolveu a pedra de sobre a bocca do poço, e deu de beber às ovelhas de Labão, irmão de sua mãe.","E Jacó beijou a Raquel, e levantou a sua voz, e chorou.","E Jacó annunciou a Raquel que era irmão de seu pai, e que era filho de Rebecca: então ela correu, e o annunciou a seu pai.","E aconteceu que, ouvindo Labão as novas de Jacó, filho de sua irmã, correu-lhe ao encontro, e abraçou-o, e beijou-o, e levou-o a sua casa: e contou ele a Labão todas estas coisas.","Então Labão disse-lhe: Verdadeiramente és tu o meu osso e a minha carne. E ficou com ele um mez inteiro.","Depois disse Labão a Jacó: Porque tu és meu irmão, has de servir-me de graça? declara-me qual sera o teu salario.","E Labão tinha duas filhas; o nome da mais velha era Lia, e o nome da menor Raquel.","Lia porém tinha olhos tenros, mas Raquel era de formoso semblante e formosa a vista.","E Jacó amava a Raquel, e disse: Sete anos te servirei por Raquel, tua filha menor.","Então disse Labão: Melhor é que eu t'a dê, do que eu a dê a outro varão: fica commigo.","Assim serviu Jacó sete anos por Raquel; e foram aos seus olhos como poucos dias, pelo muito que a amava.","E disse Jacó a Labão: Da-me minha mulher, porque meus dias são cumpridos, para que eu entre a ela.","Então ajuntou Labão a todos os varões daquele lugar, e fez um banquete.","E aconteceu, a tarde, que tomou Lia sua filha, e trouxe-lh'a: e entrou a ela.","E Labão deu sua serva Zilpah a Lia sua filha por serva.","E aconteceu pela manhã, eis que era Lia; pelo que disse a Labão: Porque me fizeste isso? não te tenho servido por Raquel? porque pois me enganaste?","E disse Labão: Não se faz assim no nosso lugar, que a menor se dê antes da primogenita.","Cumpre a semana desta; então te daremos também a outra, pelo serviço que ainda outros sete anos servires commigo.","E Jacó fez assim: e cumpriu a semana desta: então lhe deu por mulher Raquel sua filha.","E Labão deu sua serva Bilha por serva a Raquel, sua filha.","E entrou também a Raquel, e amou também a Raquel mais do que a Lia; e serviu com ele ainda outros sete anos.","Vendo pois o Senhor que Lia era aborrecida, abriu a sua madre; porém Raquel era esteril.","E concebeu Lia, e pariu um filho, e chamou o seu nome Ruben, porque disse: Porque o Senhor attendeu a minha afflicção, por isso agora me amara o meu marido.","E concebeu outra vez, e pariu um filho, dizendo: Porquanto o Senhor ouviu que eu era aborrecida, me deu também este; e chamou o seu nome Simeão.","E concebeu outra vez, e pariu um filho, dizendo: Agora esta vez se ajuntara meu marido commigo, porque tres filhos lhe tenho parido: por isso chamou o seu nome Levi.","E concebeu outra vez, e pariu um filho, dizendo: Esta vez louvarei ao Senhor. Por isso chamou o seu nome Judah: e cessou de parir."];
GENESIS_TEXT[30]=["Vendo pois Raquel que não paria filhos a Jacó, teve Raquel inveja de sua irmã, e disse a Jacó: Da-me filhos, ou se não morro.","Então se accendeu a ira de Jacó contra Raquel, e disse: Estou eu no lugar de Deus, que te impediu o fruto de teu ventre?","E ela disse: Eis aqui minha serva Bilha; entra a ela, para que para sobre os meus joelhos, e eu também seja edificada dela.","Assim lhe deu a Bilha sua serva por mulher: e Jacó entrou a ela.","E concebeu Bilha, e pariu a Jacó um filho.","Então disse Raquel: Julgou-me Deus, e também ouviu a minha voz, e me deu um filho; por isso chamou o seu nome Dan.","E Bilha, serva de Raquel, concebeu outra vez, e pariu a Jacó o segundo filho.","Então disse Raquel: Com luctas de Deus tenho luctado com minha irmã, também venci; e chamou o seu nome Naphtali.","Vendo pois Lia que cessava de parir, tomou também a Zilpah sua serva, e deu-a a Jacó por mulher.","E pariu Zilpah, serva de Lia, um filho a Jacó.","Então disse Lia: Vem uma turba: e chamou o seu nome Gad.","Depois pariu Zilpah, serva de Lia, um segundo filho a Jacó.","Então disse Lia: Para minha ventura; porque as filhas me terão por bemaventurada: e chamou o seu nome Asher.","E foi Ruben nos dias da sega do trigo, e achou mandragoras no campo. E trouxe-as a Lia, sua mãe. Então disse Raquel a Lia: Ora da-me das mandragoras do teu filho.","E ela lhe disse: É ja pouco que hajas tomado o meu marido, tomaràs também as mandragoras do meu filho? Então disse Raquel: Por isso se deitara comtigo esta noite pelas mandragoras de teu filho.","Vindo pois Jacó a tarde do campo, saiu-lhe Lia ao encontro, e disse: A mim entraràs, porque certamente te aluguei com as mandragoras do meu filho. E deitou-se com ela aquela noite.","E ouviu Deus a Lia, e concebeu, e pariu um quinto filho.","Então disse Lia: Deus me tem dado o meu galardão, pois tenho dado minha serva ao meu marido: e chamou o seu nome Issacar.","E Lia concebeu outra vez, e pariu a Jacó um sexto filho.","E disse Lia: Deus me deu a mim uma boa dadiva; desta vez morara o meu marido commigo, porque lhe tenho parido seis filhos: e chamou o seu nome Zebulon.","E depois pariu uma filha, e chamou o seu nome Dinah.","E lembrou-se Deus de Raquel, e Deus a ouviu, e abriu a sua madre,","E ela concebeu, e pariu um filho, e disse: Tirou-me Deus a minha vergonha.","E chamou o seu nome José, dizendo: O Senhor me accrescente outro filho.","E aconteceu que, como Raquel pariu a José, disse Jacó a Labão: Deixa-me ir, que me va ao meu lugar, e a minha terra.","Da-me as minhas mulheres, e os meus filhos, pelas quaes te tenho servido, e ir-me-hei; pois tu sabes o meu serviço, que te tenho feito.","Então lhe disse Labão: Se agora tenho achado graça em teus olhos, fica commigo. Tenho experimentado que o Senhor me abençoou por amor de ti.","E disse mais: Determina-me o teu salario, que t'o darei.","Então lhe disse: Tu sabes como te tenho servido, e como passou o teu gado commigo.","Porque o pouco que tinhas antes de mim, é augmentado até uma multidão: e o Senhor te tem abençoado por meu trabalho. Agora pois, quando hei-de trabalhar também por minha casa?","E disse ele: Que te darei? Então disse Jacó: Nada me daràs; se me fizeres isto, tornarei a apascentar e a guardar o teu rebanho.","Passarei hoje por todo o teu rebanho, separando dele todos os salpicados e malhados, e todos os morenos entre os cordeiros, e os malhados e salpicados entre as cabras: e isto sera o meu salario.","Assim testificara por mim a minha justiça no dia d'amanhã, quando vieres e o meu salario estiver diante de tua face: tudo o que não for salpicado e malhado entre as cabras e moreno entre os cordeiros, ser-me-ha por furto.","Então disse Labão: Eis que oxala seja conforme a tua palavra.","E separou n'aquele mesmo dia os bodes listrados e malhados e todas as cabras salpicadas e malhadas, tudo em que havia brancura, e todo o moreno entre os cordeiros; e deu-os nas mãos dos seus filhos.","E pôs tres dias de caminho entre si e Jacó: e Jacó apascentava o resto dos rebanhos de Labão.","Então tomou Jacó varas verdes d'alamo, e d'aveleira e de castanheiro, e descascou nelas riscas brancas, descobrindo a brancura que nas varas havia,","E pôs estas varas, que tinha descascado, em frente do rebanho, nos canos e nas pias d'agua, aonde o rebanho vinha a beber, e conceberam vindo a beber.","E concebia o rebanho diante das varas, e as ovelhas pariam listrados, salpicados e malhados.","Então separou Jacó os cordeiros, e pôs as faces do rebanho para os listrados, e todo o moreno entre o rebanho de Labão; e pôs o seu rebanho a parte, e não o pôs com o rebanho de Labão.","E succedia que cada vez que concebiam as ovelhas fortes, punha Jacó as varas diante dos olhos do rebanho nos canos, para que concebessem diante das varas.","Mas quando enfraqueceu o rebanho, não as pôs. Assim as fracas eram de Labão, e as fortes de Jacó.","E cresceu o varão em grande maneira, e teve muitos rebanhos, e servas, e servos, e camelos e jumentos."];
GENESIS_TEXT[31]=["Então ouvia as palavras dos filhos de Labão, que diziam: Jacó tem tomado tudo o que era de nosso pai, e do que era de nosso pai fez ele toda esta gloria.","Viu também Jacó o rosto de Labão, e eis que não era para com ele como d'hontem e d'ante-hontem.","E disse o Senhor a Jacó: Torna-te a terra dos teus pais, e a tua parentela, e eu serei comtigo.","Então enviou Jacó, e chamou a Raquel e a Lia ao campo, ao seu rebanho,","E disse-lhes: Vejo que o rosto de vosso pai para commigo não é como d'hontem e d'ante-hontem; porém o Deus de meu pai esteve commigo;","E vós mesmas sabeis que com todo o meu poder tenho servido a vosso pai;","Mas vosso pai me enganou e mudou o salario dez vezes; porém Deus não lhe permittiu que me fizesse mal.","Quando ele dizia assim: Os salpicados serão o teu salario; então todos os rebanhos pariam salpicados. E quando ele dizia assim: Os listrados serão o teu salario, então todos os teus rebanhos pariam listrados.","Assim Deus tirou o gado de vosso pai, e m'o deu a mim.","E sucedeu que, ao tempo em que o rebanho concebia, eu levantei os meus olhos, e vi em sonhos, e eis que os bodes, que cobriam as ovelhas, eram listrados, salpicados e malhados.","E disse-me o anjo de Deus em sonhos: Jacó. E eu disse: Eis-me aqui.","E disse ele: Levanta agora os teus olhos, e vê todos os bodes que cobrem o rebanho, que são listrados, salpicados e malhados: porque tenho visto tudo o que Labão te fez.","Eu sou o Deus de Beth-el, onde teus ungido uma columna, onde me tens votado o voto; levanta-te agora, sae-te desta terra, e torna-te a terra da tua parentela.","Então responderam Raquel e Lia, e disseram-lhe: Ha ainda para nós parte ou herança na casa de nosso pai?","Não nos considera ele como estranhas? pois vendeu-nos, e comeu de todo o nosso dinheiro.","Porque toda a riqueza, que Deus tirou de nosso pai, é nossa e de nossos filhos: agora pois, faze tudo o que Deus te tem dito.","Então se levantou Jacó, pondo os seus filhos e as suas mulheres sobre os camelos;","E levou todo o seu gado, e toda a sua fazenda, que havia adquirido, o gado que possuia, que alcançara em Paddan*-aram, para ir a Isaac, seu pai, a terra de Canaã.","E havendo Labão ido a tosquiar as suas ovelhas, furtou Raquel os idolos que seu pai tinha.","E esquivou-se Jacó de Labão o arameo, porque não lhe fez saber que fugia.","E fugiu ele com tudo o que tinha, e levantou-se, e passou o rio: e pôs o seu rosto para a montanha de Gilead.","E no terceiro dia foi annunciado a Labão que Jacó tinha fugido.","Então tomou comsigo os seus irmãos, e atraz dele proseguiu o caminho por sete dias; e alcançou-o na montanha de Gilead.","Veiu porém Deus a Labão o arameo em sonhos de noite, e disse-lhe: Guarda-te, que não falles com Jacó nem bem nem mal.","Alcançou pois Labão a Jacó, e armara Jacó a sua tenda n'aquela montanha: armou também Labão com os seus irmãos a sua na montanha de Gilead.","Então disse Labão a Jacó: Que fizeste, que te esquivaste de mim, e levaste as minhas filhas como captivas pela espada?","Porque fugiste occultamente, e te esquivaste de mim, e não me fizeste saber, para que eu te enviasse com alegria, e com canticos, e com tamboril e com harpa?","Também não me permittiste beijar os meus filhos e as minhas filhas. Loucamente pois agora fizeste, fazendo assim.","Poder havia em minha mão para vos fazer mal, mas o Deus de vosso pai me falou hontem a noite, dizendo: Guarda-te, que não falles com Jacó nem bem nem mal.","E agora te querias ir embora, porquanto tinhas saudades de voltar a casa de teu pai; porque furtaste os meus deuses?","Então respondeu Jacó, e disse a Labão: Porque temia; pois que dizia commigo, se porventura me não arrebatarias as tuas filhas.","Com quem achares os teus deuses, esse não viva; reconhece diante de nossos irmãos o que é teu do que esta commigo, e toma-o para ti. Pois Jacó não sabia que Raquel os tinha furtado.","Então entrou Labão na tenda de Jacó, e na tenda de Lia, e na tenda d'ambas as servas, e não os achou; e saindo da tenda de Lia, entrou na tenda de Raquel.","Mas tinha tomado Raquel os idolos, e os tinha posto na albarda de um camelo, e assentara-se sobre eles; e apalpou Labão toda a tenda, e não os achou.","E ela disse a seu pai: Não se accenda a ira aos olhos de meu senhor, que não posso levantar-me diante da tua face; porquanto tenho o costume das mulheres. E ele procurou, mas não achou os idolos.","Então irou-se Jacó, e contendeu com Labão; e respondeu Jacó, e disse a Labão: Qual é a minha transgressão? qual é o meu peccado, que tão furiosamente me tens perseguido?","Havendo apalpado todos os meus moveis, que achaste de todos os moveis da tua casa? põe-o aqui diante dos meus irmãos, e teus irmãos; e que julguem entre nós ambos.","Estes vinte anos eu estive comtigo, as tuas ovelhas e as tuas cabras nunca moveram, e não comi os carneiros do teu rebanho.","Não te trouxe eu o despedaçado; eu o pagava; o furtado de dia e o furtado de noite da minha mão o requerias.","Estive eu de sorte que de dia me consumia o calor, e de noite a geada; e o meu somno foi-se dos meus olhos.","Tenho estado agora vinte anos na tua casa; quatorze anos te servi por tuas duas filhas, e seis anos por teu rebanho; mas o meu salario tens mudado dez vezes.","Se o Deus de meu pai, o Deus de Abraão, e o Temor de Isaac não fôra commigo, por certo me enviarias agora vazio. Deus attendeu a minha afflicção, e ao trabalho das minhas mãos, e reprehendeu-te hontem a noite.","Então respondeu Labão, e disse a Jacó: Estas filhas são minhas filhas, e estes filhos são meus filhos, e este rebanho é o meu rebanho, e tudo o que vês, meu é: e que farei hoje a estas minhas filhas, ou a seus filhos, que pariram?","Agora pois vem, e façamos concerto eu e tu, que seja por testemunho entre mim e ti.","Então tomou Jacó uma pedra, e erigiu-a por columna.","E disse Jacó a seus irmãos: Ajuntae pedras. E tomaram pedras, e fizeram um montão, e comeram ali sobre aquele montão.","E chamou-o Labão Jegar-sahadutha: porém Jacó chamou-o Galeed.","Então disse Labão: Este montão seja hoje por testemunha entre mim e entre ti: por isso se chamou o seu nome Galeed,","E Mizpah, porquanto disse: Attente o Senhor entre mim e ti, quando nós estivermos apartados um do outro:","Se affligires as minhas filhas, e se tomares mulheres além das minhas filhas, ninguem esta comnosco: attenta que Deus é testemunha entre mim e ti","Disse mais Labão a Jacó: Eis aqui este mesmo montão, e eis aqui essa columna que levantei entre mim e entre ti.","Este montão seja testemunha, e esta columna seja testemunha, que eu não passarei este montão a ti, e que tu não passaràs este montão e esta columna a mim, para mal.","O Deus de Abraão, e o Deus de Nahor, o Deus de seu pai julgue entre nós. E jurou Jacó pelo Temor de seu pai Isaac.","E sacrificou Jacó um sacrificou na montanha, e convidou seus irmãos, para comer pão; e comeram pão, e passaram a noite na montanha.","E levantou-se Labão pela manhã de madrugada, e beijou seus filhos, e suas filhas, e abençoou-os, e partiu; e voltou Labão ao seu lugar."];
GENESIS_TEXT[32]=["E foi também Jacó o seu caminho, e encontraram-o os anjos de Deus.","E Jacó disse, quando os viu: Este é o exercito de Deus. E chamou o nome daquele lugar Mahanaim.","E enviou Jacó mensageiros diante da sua face a Esaú seu irmão, a terra de Seir, territorio de Edom.","E ordenou-lhes, dizendo: Assim direis a meu senhor Esaú: Assim diz Jacó, teu servo: Como peregrino morei com Labão, e me detive la até agora;","E tenho bois e jumentos, ovelhas, e servos e servas; e enviei para o annunciar a meu senhor, para que ache graça em teus olhos.","E os mensageiros tornaram a Jacó, dizendo: Viemos a teu irmão Esaú; e também ele vem a encontrar-te, e quatrocentos varões com ele.","Então Jacó temeu muito, e angustiou-se; e repartiu o povo que com ele estava, e as ovelhas, e as vacas, e os camelos, em dois bandos.","Porque dizia: Se Esaú vier a um bando, e o ferir, o outro bando escapara.","Disse mais Jacó: Deus de meu pai Abraão, e Deus de meu pai Isaac, o Senhor, que me disseste: Torna-te a tua terra, e a tua parentela, e far-te-hei bem;","Menor sou eu que todas as beneficencias, e que toda a fidelidade que fizeste ao teu servo; porque com meu cajado passei este Jordão, e agora me tornei em dois bandos;","Livra-me, peço-te, da mão de meu irmão, da mão de Esaú: porque o temo, que porventura não venha, e me fira, e a mãe com os filhos","E tu o disseste: Certamente te farei bem, e farei a tua semente como a areia do mar, que pela multidão não se pode contar.","E passou ali aquela noite; e tomou do que lhe veiu a sua mão, um presente para seu irmão Esaú:","Duzentas cabras, e vinte bodes; duzentas ovelhas, e vinte carneiros;","Trinta camelas de leite com suas crias, quarenta vacas, e dez novilhos; vinte jumentas, e dez jumentinhos;","E deu-o na mão dos seus servos, cada rebanho a parte, e disse a seus servos: Passae adiante da minha face, e ponde espaço entre rebanho e rebanho.","E ordenou ao primeiro, dizendo: Quando Esaú, meu irmão, te encontrar, e te perguntar, dizendo: De quem és, e para onde vaes, e cujos são estes diante da tua face,","Então diràs: São de teu servo Jacó, presente que envia a meu senhor, a Esaú; e eis que ele mesmo vem também atraz de nós","E ordenou também ao segundo, e ao terceiro, e a todos os que vinham atraz dos rebanhos, dizendo: Conforme a esta mesma palavra, falareis a Esaú, quando o achardes.","E direis também: Eis que o teu servo Jacó vem atraz de nós. Porque dizia: Eu o aplacarei com o presente, que vae diante de mim, e depois verei a sua face; porventura acceitara a minha face.","Assim passou o presente diante da sua face; ele porém passou aquela noite no arraial.","E levantou-se aquela mesma noite, e tomou as suas duas mulheres, e as suas duas servas, e os seus onze filhos, e passou o vao de Jabbok.","E tomou-os, e fel-os passar o ribeiro; e fez passar tudo o que tinha.","Jacó porém ficou só; e luctou com ele um varão, até que a alva subia.","E vendo que não prevalecia contra ele, tocou a juntura de sua côxa, e se deslocou a juntura da côxa de Jacó, luctando com ele.","E disse: Deixa-me ir, porque ja a alva subiu. Porém ele disse: Não te deixarei ir, se me não abençoares.","E disse-lhe: Qual é o teu nome? E ele disse: Jacó.","Então disse: Não se chamara mais o teu nome Jacó, mas Israel: pois como principe luctaste com Deus, e com os homens, e prevaleceste.","E Jacó lhe perguntou, e disse: Da-me, peço-te, a saber o teu nome. E disse: Porque perguntas pelo meu nome? E abençoou-o ali.","E chamou Jacó o nome daquele lugar Peniel, porque dizia: Tenho visto a Deus face a face, e a minha alma foi salva.","E saiu-lhe o sol, quando passou a Penuel; e manquejava da sua côxa.","Por isso os filhos de Israel não comem o nervo encolhido, que esta sobre a juntura da côxa, até o dia de hoje; porquanto tocara a juntura da côxa de Jacó no nervo encolhido."];
GENESIS_TEXT[33]=["E levantou Jacó os seus olhos, e olhou, e eis que vinha Esaú, e quatrocentos homens com ele. Então repartiu os filhos entre Lia e Raquel, e as duas servas.","E pôs as servas e seus filhos na frente, e a Lia e seus filhos atraz: porém a Raquel e José os derradeiros.","E ele mesmo passou adiante deles, e inclinou-se a terra sete vezes, até que chegou a seu irmão.","Então Esaú correu-lhe ao encontro, e abraçou-o, e lançou-se sobre o seu pescoço, e beijou-o; e choraram.","Depois levantou os seus olhos, e viu as mulheres, e os meninos, e disse: Quem são estes comtigo? E ele disse: Os filhos que Deus graciosamente tem dado a teu servo.","Então chegaram as servas; elas, e os seus filhos, e inclinaram-se.","E chegou também Lia com seus filhos, e inclinaram-se: e depois chegou José e Raquel, e inclinaram-se.","E disse Esaú: De que te serve todo este bando que tenho encontrado? E ele disse: Para achar graça aos olhos de meu senhor.","Mas Esaú disse: Eu tenho bastante, meu irmão; seja para ti o que tens.","Então disse Jacó: Não, se agora tenho achado graça em teus olhos, peço-*te que tomes o meu presente da minha mão: porquanto tenho visto o teu rosto, como se tivesse visto o rosto de Deus, e tomaste contentamento em mim.","Toma, peço-te, a minha benção, que te foi trazida; porque Deus graciosamente m'a tem dado; e porque tenho de tudo. E instou com ele, até que a tomou.","E disse: Caminhemos, e andemos, e eu partirei adiante de ti.","Porém ele lhe disse: Meu senhor sabe que estes filhos são tenros, e que tenho commigo ovelhas e vacas de leite; se as afadigarem somente um dia, todo o rebanho morrera.","Ora passe o meu senhor diante da face de seu servo; e eu irei como guia pouco a pouco, conforme ao passo do gado que é adiante da minha face, e conforme ao passo dos meninos, até que chegue a meu senhor em Seir.","E Esaú disse: Deixarei logo comtigo desta gente, que esta commigo. E ele disse: Para que é isso? Basta que eu ache graça aos olhos de meu senhor.","Assim se tornou Esaú aquele dia pelo seu caminho a Seir.","Jacó, porém, partiu para Succoth e edificou para si uma casa; e fez cabanas para o seu gado: por isso chamou o nome daquele lugar Succoth.","E chegou Jacó salvo a cidade de Sichem, que esta na terra de Canaã, quando vinha de Paddan-aram; e fez o seu assento diante da cidade.","E comprou uma parte do campo em que estendera a sua tenda, da mão dos filhos de Hemor, pai de Sichem, por cem peças de dinheiro.","E levantou ali um altar, e chamou-o Deus, o Deus d'Israel."];
GENESIS_TEXT[34]=["E saiu Dinah filha de Lia, que parira a Jacó, para ver as filhas da terra.","E Sichem filho de Hemor heveo, principe daquela terra, viu-a, e tomou-a, e deitou-se com ela, e humilhou-a.","E apegou-se a sua alma com Dinah filha de Jacó, e amou a moça e falou affectuosamente a moça.","Falou também Sichem a Hemor seu pai, dizendo: Toma-me esta por mulher.","Quando Jacó ouviu que contaminara a Dinah sua filha, estavam os seus filhos no campo com o gado; e calou-se Jacó até que viessem.","E saiu Hemor pai de Sichem a Jacó, para falar com ele.","E vieram os filhos de Jacó do campo, ouvindo isso, e entristeceram-se os varões, e iraram-se muito, porquanto fizera doidice em Israel, deitando-se com a filha de Jacó; o que não se devia fazer assim.","Então falou Hemor com eles, dizendo: A alma de Sichem meu filho esta namorada da vossa filha; dae-lh'a, peço-te, por mulher;","E aparentae-vos comnosco, dae-nos as vossas filhas, e tomae as nossas filhas para vós;","E habitareis comnosco; e a terra estara diante da vossa face: habitae e negociae nela, e tomae possessão nela.","E disse Sichem ao pai dela, e aos irmãos dela: Ache eu graça em vossos olhos, e darei o que me disserdes:","Augmentae muito sobre mim o dote e a dadiva, e darei o que me disserdes; dae-me somente a moça por mulher.","Então responderam os filhos de Jacó a Sichem e a Hemor seu pai enganosamente, e falaram, porquanto havia contaminado a Dinah sua irmã.","E disseram-lhes: Não podemos fazer isso, que déssemos a nossa irmã a um varão não circumcidado; porque isso seria uma vergonha para nós;","N'isso, porém, consentiremos a vós: se fôrdes como nós, que se circumcide todo o macho entre vós","Então dar-vos-hemos as nossas filhas, e tomaremos nós as vossas filhas, e habitaremos comvosco, e seremos um povo;","Mas se não nos ouvirdes, e não vos circumcidardes, tomaremos a nossa filha e ir-nos-hemos.","E suas palavras foram boas aos olhos de Hemor, e aos olhos de Sichem filho de Hemor.","E não tardou o mancebo em fazer isto; porque a filha de Jacó lhe contentava: e ele era o mais honrado de toda a casa de seu pai.","Veiu pois Hemor e Sichem seu filho a porta da sua cidade, e falaram aos varões da sua cidade, dizendo:","Estes varões são pacificos comnosco; portanto habitarão n'esta terra, e negociarão nela; eis que a terra é larga de espaço diante da sua face: tomaremos nós as suas filhas por mulheres, e lhes daremos as nossas filhas","N'isto, porém, consentirão aqueles varões, de habitar comnosco, para que sejamos um povo, se todo o macho entre nós se circumcidar, como eles são circumcidados.","O seu gado, as suas possessões, e todos os seus animaes não serão nossos? consintamos somente com eles, e habitarão comnosco.","E deram ouvidos a Hemor, e a Sichem seu filho todos os que sahiam da porta da cidade; e foi circumcidado todo o macho, de todos os que sahiam pela porta da sua cidade.","E aconteceu que, ao terceiro dia, quando estavam com a mais violenta dôr, os dois filhos de Jacó, Simeão e Levi, irmãos de Dinah, tomaram cada um a sua espada, e entraram afoitamente na cidade, e mataram todo o macho.","Mataram também ao fio da espada a Hemor, e a seu filho Sichem; e tomaram a Dinah da casa de Sichem, e sairam.","Vieram os filhos de Jacó aos mortos e saquearam a cidade; porquanto contaminaram a sua irmã.","As suas ovelhas, e as suas vacas, e os seus jumentos, e o que na cidade, e o que no campo havia, tomaram,","E toda a sua fazenda, e todos os seus meninos, e as suas mulheres levaram presas, e despojaram-as, e tudo o que havia em casa.","Então disse Jacó a Simeão e a Levi: Tendes-me turbado, fazendo-me cheirar mal entre os moradores desta terra, entre os Cananeus e Phereseus, sendo eu pouco povo em numero; ajuntar-se-hão, e ficarei destruido, eu e minha casa.","E eles disseram: Faria pois ele a nossa irmã como a uma prostituta?"];
GENESIS_TEXT[35]=["Depois disse Deus a Jacó: Levanta-te, sobe a Bethel, e habita ali; e faz ali um altar ao Deus que te apareceu, quando fugiste diante da face de Esaú teu irmão.","Então disse Jacó a sua familia, e a todos os que com ele estavam: Tirae os deuses estranhos, que ha no meio de vós, e purificae-vos, e mudae os vossos vestidos.","E levantemo-nos, e subamos a Bethel; e ali farei um altar ao Deus que me respondeu no dia da minha angustia, e que foi commigo no caminho que tenho andado.","Então deram a Jacó todos os deuses estranhos, que tinham em suas mãos, e as arrecadas que estavam em suas orelhas; e Jacó os escondeu debaixo do carvalho que esta junto a Sichem.","E partiram; e o terror de Deus foi sobre as cidades que estavam ao redor deles, e não seguiram após os filhos de Jacó.","Assim chegou Jacó a Luz, que esta na terra de Canaã, (esta é Bethel), ele e todo o povo que com ele havia.","E edificou ali um altar, e chamou aquele lugar El-beth-el: porquanto Deus ali se lhe tinha manifestado quando fugia diante da face de seu irmão.","E morreu Debora, a ama de Rebecca, e foi sepultada ao pé de Bethel, debaixo do carvalho cujo nome chamou Allonbachuth.","E apareceu Deus outra vez a Jacó, vindo de Paddan-aram, e abençoou-o.","E disse-lhe Deus: O teu nome é Jacó; não se chamara mais o teu nome Jacó, mas Israel sera o teu nome. E chamou o seu nome Israel.","Disse-lhe mais Deus: Eu sou o Deus Todo-poderoso; fructifica e multiplica-te; uma nação e multidão de nações sairão de ti, e reis procederão dos teus lombos","E te darei a ti a terra que tenho dado a Abraão e a Isaac, e a tua semente depois de ti darei a terra.","E Deus subiu dele, do lugar onde falara com ele.","E Jacó pôs uma columna no lugar onde falara com ele, uma columna de pedra; e derramou sobre ela uma libação, e deitou sobre ela azeite.","E chamou Jacó o nome daquele lugar, onde Deus falara com ele, Bethel.","E partiram de Bethel: e havia ainda um pequeno espaço de terra para chegar a Ephrata, e pariu Raquel, e ela teve trabalho em seu parto.","E aconteceu que, tendo ela trabalho em seu parto, lhe disse a parteira: Não temas, porque também este filho teràs.","E aconteceu que, saindo-se-lhe a alma (porque morreu), chamou o seu nome Benoni; mas seu pai o chamou Benjamin.","Assim morreu Raquel; e foi sepultada no caminho d'Ephrata, este é Beth-lehem.","E Jacó pôs uma columna sobre a sua sepultura; esta é a columna da sepultura de Raquel até ao dia de hoje.","Então partiu Israel, e estendeu a sua tenda d'além de Migdal Eder.","E aconteceu que, habitando Israel n'aquela terra, foi Ruben, e deitou-se com Bilhah, concubina de seu pai; e Israel ouviu-o. E eram doze os filhos de Jacó:","Os filhos de Lia: Ruben, o primogenito de Jacó, depois Simeão e Levi, e Judah, e Issacar e Zebulon;","Os filhos de Raquel: José e Benjamin;","E os filhos de Bilhah, serva de Raquel: Dan e Naphtali;","E os filhos de Zilpah, serva de Lia: Gad e Aser. Estes são os filhos de Jacó, que lhe nasceram em Paddan-aram.","E Jacó veiu a seu pai Isaac, a Mamre, a Kiriath-arba (que é Hebron), onde peregrinaram Abraão e Isaac.","E foram os dias de Isaac cento e oitenta anos.","E Isaac expirou, e morreu, e foi recolhido aos seus povos, velho e farto de dias; e Esaú e Jacó, seus filhos, o sepultaram."];
GENESIS_TEXT[36]=["E estas são as gerações de Esaú ( que é Edom).","Esaú tomou suas mulheres das filhas de Canaã: a Adah, filha de Elon hetheo, e a Aholibamah, filha de Anah, filha de Zibeon heveo.","E a Basemath, filha de Ishmael, irmã de Nebajoth.","E Adah pariu a Esaú Eliphaz; e Basemath pariu a Rehuel;","E Aholibamah pariu a Jeush, e Jaelam e Corah: estes são os filhos de Esaú, que lhe nasceram na terra de Canaã.","E Esaú tomou suas mulheres, e seus filhos, e suas filhas, e todas as almas de sua casa, e seu gado, e todos os seus animaes, e toda a sua fazenda, que havia adquirido na terra de Canaã; e foi-se a outra terra de diante da face de Jacó seu irmão;","Porque a fazenda deles era muita para habitarem juntos; e a terra de suas peregrinações não os podia sustentar por causa do seu gado.","Portanto Esaú habitou na montanha de Seir; Esaú é Edom.","Estas pois são as gerações de Esaú, pai dos Idumeos, na montanha de Seir.","Estes são os nomes dos filhos de Esaú: Eliphaz, filho de Adah, mulher de Esaú; Rehuel, filho de Basemath, mulher de Esaú.","E os filhos de Eliphsz foram: Teman, Omar, Zepho, e Gaetam, e Kenaz.","E Timnah era concubina de Eliphaz, filho de Esaú, e pariu a Eliphaz Amelek: estes são os filhos de Adah, mulher de Esaú.","E estes foram os filhos de Rehuel: Nahath, e Zerah, Shammah, e Mizzah: estes foram os filhos de Basemath, mulher de Esaú.","E estes foram os filhos de Aholibamah, filha de Anah, filha de Zibeon, mulher de Esaú: e pariu a Esaú: Jeush, e Jalam, e Corah.","Estes são os principes dos filhos de Esaú; o filhos de Eliphaz, o primogenito de Esaú, foram: o principe Teman, o principe Omar, o principe Zepho, o principe Kenaz,","O principe Corah, o principe Gatam, o principe Amalek; estes são os principes de Eliphaz na terra de Edom, estes são os filhos de Adah.","E estes são os filhos de Rehuel, filho de Esaú: o principe Nahath, o principe Zerah, o principe Shammah, o principe Mizzah; estes são os principes de Rehuel, na terra de Edom, estes são os filhos de Besemath, mulher de Esaú.","E estes são os filhos de Aholibamah, mulher de Esaú: o principe Jeush, o principe Jalam, o principe Corah; estes são os principes do Aholibamah, filha de Anah, mulher de Esaú.","Estes são os filhos de Esaú, e estes são seus principes: ele é Edom.","Estes são os filhos de Seir horeo, moradores daquela terra: Lotan, e Sobal e Zibeon, e Anah.","E Dishon, e Eser, e Dishan; estes são os principes dos horeos, filhos de Seir, na terra de Edom.","E os filhos de Lotan foram: Hori e Hemam; e a irmã de Lotan era Timnah.","Estes são os filhos de Sobal: Alvan, e Manahath, e Ebal, e Shepho, e Onam.","E estes são os filhos de Zibeon: Ajah, e Anah; este é o Anah que achou os mulos no deserto, quando apascentava os jumentos de Zibeon seu pai.","E estes são os filhos de Anah: Dishon, e Aholibamah, a filha de Anah.","E estes são os filhos de Dishon: Hemdam, e Eshban, e Ithran, e Cheran.","Estes são os filhos de Eser: Bilhan, e Zaavan, e Akan.","Estes são os filhos de Dishan: Uz, e Aran.","Estes são os principes dos horeos: O principe Lotan, o principe Shobal, o principe Zibeon, o principe Anah,","O principe Dishon, o principe Eser, o principe Dishan; estes são os principes dos horeos segundo seus principes na terra de Seir.","E estes são os reis que reinaram na terra de Edom, antes que reinasse rei algum sobre os filhos d'Israel.","Reinou pois em Edom Bela, filho de Beor, e o nome da sua cidade foi Dinhaba.","E morreu Bela; e Jobab, filho de Zerah de Bosrah, reinou em seu lugar.","E morreu Jobab; e Husam, da terra dos Temanitas, reinou em seu lugar.","E morreu Husam, e em seu lugar reinou Hadad, filho de Bedad, o que feriu a Midian no campo de Moab; e o nome da sua cidade foi Avith.","E morreu Hadad: e Samlah de Masreca reinou em seu lugar.","E morreu Samlah; e Shaul de Rehoboth, pelo rio, reinou em seu lugar.","E morreu Shaul; e Baal-hanan, filho de Achbor, reinou em seu lugar.","E morreu Baal-hanan, filho de Achbor; e Hadar reinou em seu lugar, e o nome da sua cidade foi Pau; e o nome de sua mulher foi Mehetabel, filha de Matred, filha de Mezahab.","E estes são os nomes dos principes de Esaú; segundo as suas gerações, segundo os seus lugares, com os seus nomes: o principe Timnah, o principe Alvah, o principe Jetheth,","O principe Aholibamah, o principe Elah o principe Pinon,","O principe Kenez, o principe Teman, o principe Mibzar,","O principe Magdiel, o principe Iram: estes são os principes de Edom, segundo as suas habitações, na terra da sua possessão; este é Esaú, pai de Edom."];
GENESIS_TEXT[37]=["E Jacó habitou na terra das peregrinações de seu pai, na terra de Canaã.","Estas são as gerações de Jacó. Sendo José de dezesete anos, apascentava as ovelhas com seus irmãos, e estava este mancebo com os filhos de Bilhah, e com os filhos de Zilpah, mulheres de seu pai; e José trazia uma ma fama deles a seu pai.","E Israel amava a José mais do que a todos os seus filhos, porque era filho da sua velhice; e fez-lhe uma tunica de varias côres.","Vendo pois seus irmãos que seu pai o amava mais do que a todos os seus irmãos, aborreceram-o, e não podiam falar com ele pacificamente.","Sonhou também José um sonho, que contou a seus irmãos: por isso o aborreciam ainda mais.","E disse-lhes: Ouvi, peço-vos, este sonho, que tenho sonhado:","Eis que estavamos atando mólhos no meio do campo, e eis que o meu mólho se levantava, e também ficava em pé, e eis que os vossos mólhos o rodeavam, e se inclinavam ao meu mólho.","Então lhe disseram seus irmãos: Tu pois devéras reinaràs sobre nós? Por isso tanto mais o aborreciam por seus sonhos e por suas palavras.","E sonhou ainda outro sonho, e o contou a seus irmãos, e disse: Eis que ainda sonhei um sonho; e eis que o sol, e a lua, e onze estrelas se inclinavam a mim.","E contando-o a seu pai e a seus irmãos, reprehendeu-o seu pai, e disse-lhe: Que sonho é este que sonhaste? porventura viremos, eu e tua mãe, e teus irmãos, para inclinar-nos a ti em terra?","Seus irmãos pois o invejavam; seu pai porém guardava este negocio no seu coração.","E seus irmãos foram apascentar o rebanho de seu pai, junto de Sichem.","Disse pois Israel a José: Não apascentam os teus irmãos junto de Sichem? vem, e enviar-te-hei a eles. E ele lhe disse: Eis-me aqui.","E ele lhe disse: Ora vae-te, vê como estão teus irmãos, e como esta o rebanho, e traze-me resposta. Assim o enviou do valle de Hebron, e veiu a Sichem.","E achou-o um varão, porque eis que andava errado pelo campo, e perguntou-lhe o varão, dizendo: Que procuras?","E ele disse: Procuro meus irmãos; dize-me, peço-te, onde eles apascentam.","E disse aquele varão: Foram-se daqui; porque ouvi-lhes dizer: Vamos a Dothan. José pois seguiu atraz de seus irmãos, e achou-os em Dothan.","E viram-o de longe, e, antes que chegasse a eles, conspiraram contra ele, para o matarem.","E disseram um ao outro: Eis la vem o sonhador-mór!","Vinde pois agora, e matemel-o, e lancemol-o numa destas covas, e diremos: Uma besta fera o comeu; e veremos que sera dos seus sonhos.","E ouvindo-o Ruben, livrou-o das suas mãos, e disse: Não lhe tiremos a vida.","Também lhes disse Ruben: Não derrameis sangue; lançae-o n'esta cova, que esta no deserto, e não lanceis mãos nele; para livral-o das suas mãos, e para tornal-o a seu pai.","E aconteceu que, chegando José a seus irmãos, tiraram a José a sua tunica, a tunica de varias côres, que trazia.","E tomaram-o, e lançaram-o na cova; porém a cova estava vasia, não havia agua nela.","Depois assentaram-se a comer pão; e levantaram os seus olhos, e olharam, e eis que uma companhia de ishmaelitas vinha de Gilead; e seus camelos traziam especiarias, e balsamo, e myrrha, e iam leval-os ao Egito.","Então Judah disse aos seus irmãos: Que proveito havera que matemos a nosso irmão, e escondamos a sua morte?","Vinde, e vendamol-o a estes ishmaelitas, e não seja nossa mão sobre ele; porque ele é nosso irmão, nossa carne. E seus irmãos obedeceram.","Passando pois os mercadores midianitas, tiraram, e alçaram a José da cova, e venderam José por vinte moedas de prata aos ishmaelitas, os quaes levaram José ao Egito.","Tornando pois Ruben a cova, eis que José não estava na cova; então rasgou os seus vestidos,","E tornou a seus irmãos, e disse: O moço não apparece; e eu aonde irei?","Então tomaram a tunica de José, e mataram um cabrito, e tingiram a tunica no sangue,","E enviaram a tunica de varias côres, e fizeram leval-a a seu pai, e disseram: Temos achado esta tunica; conhece agora se esta sera ou não a tunica de teu filho.","E conheceu-a, e disse: É a tunica de meu filho; uma besta fera o comeu; certamente é despedaçado José.","Então Jacó rasgou os seus vestidos, e pôs sacco sobre os seus lombos, e lamentou a seu filho muitos dias.","E levantaram-se todos os seus filhos e todas as suas filhas, para o consolarem; recusou porém ser consolado, e disse: Porquanto com chôro hei de descer ao meu filho até a sepultura. Assim o chorou seu pai","E os midianitas venderam-o no Egito a Potifar, eunucho de Faraó, capitão da guarda."];
GENESIS_TEXT[38]=["E aconteceu no mesmo tempo que Judah desceu de entre seus irmãos, e entrou na casa d'um varão de Adullam, cujo nome era Hirah,","E viu Judah ali a filha d'um varão cananeu, cujo nome era Shuah; e tomou-a, e entrou a ela.","E ela concebeu, e pariu um filho, e chamou o seu nome Er;","E tornou a conceber, e pariu um filho, e chamou o seu nome Onan;","E continuou ainda, e pariu um filho, e chamou o seu nome Selah; e ele estava em Chezib, quando ela o pariu.","Judah pois tomou uma mulher para Er, o seu primogenito, e o seu nome era Tamar.","Er, porém, o primogenito de Judah, era mau aos olhos do Senhor, pelo que o Senhor o matou.","Então disse Judah a Onan: Entra a mulher do teu irmão, e casa-te com ela, e suscita semente a teu irmão.","Onan, porém, soube que esta semente não havia de ser para ele; e aconteceu que, quando entrava a mulher de seu irmão, derramava-a na terra, para não dar semente a seu irmão.","E o que fazia era mau aos olhos do Senhor, pelo que também o matou.","Então disse Judah a Tamar sua nóra: Fica-te viuva na casa de teu pai, até que Selah, meu filho, seja grande. Porquanto disse: Para que porventura não morra também este, como seus irmãos. Assim foi-se Tamar, e ficou-se na casa de seu pai.","Passando-se pois muitos dias, morreu a filha de Shuah, mulher de Judah; e depois se consolou Judah, e subiu aos tosquiadores das suas ovelhas em Timnah, ele e Hirah seu amigo, o adullamita.","E deram aviso a Tamar, dizendo: Eis que o teu sogro sobe a Timnah, a tosquiar as suas ovelhas.","Então ela tirou de sobre si os vestidos da sua viuvez, e cobriu-se com o véu, e envolveu-se, e assentou-se a entrada das duas fontes que estão no caminho de Timnah, porque via que Selah ja era grande, e ela lhe não fôra dada por mulher","E vendo-a Judah, teve-a por uma prostituta; porque ela tinha coberto o seu rosto.","E apartou-se a ela ao caminho, e disse: Vem, peço-te, deixa-me entrar a ti. Porquanto não sabia que era sua nóra: e ela disse: Que daràs, para que entres a mim","E ele disse: Eu te enviarei um cabrito do rebanho. E ela disse: Dàs-me penhor até que o envies?","Então ele disse: Que penhor é que te darei? E ela disse: O teu sello, e o teu lenço, e o cajado que esta em tua mão. O que ele lhe deu, e entrou a ela, e ela concebeu dele.","E ela levantou-se, e foi-se, e tirou de sobre si o seu véu, e vestiu os vestidos da sua viuvez.","E Judah enviou o cabrito por mão do seu amigo o adullamita, para tomar o penhor da mão da mulher, porém não a achou.","E perguntou aos homens daquele lugar, dizendo: Onde esta a prostituta que estava no caminho junto às duas fontes? E disseram: Aqui não esteve prostituta alguma.","E tornou-se a Judah, e disse: Não a achei; e também disseram os homens daquele lugar: Aqui não esteve prostituta.","Então disse Judah: Tome-o para si, para que porventura não venhamos em desprezo; eis que tenho enviado este cabrito; mas tu não a achaste.","E aconteceu que, quasi tres mezes depois, deram aviso a Judah, dizendo: Tamar, tua nóra, tem fornicado, e eis que esta pejada da fornicação. Então disse Judah: Tirae-a fora para que seja queimada.","E tirando-a fora, ela mandou dizer a seu sogro: Do varão de quem são estas coisas eu concebi. E ela disse mais: Conhece, peço-te, de quem é este sello, e estes lenços e este cajado.","E conheceu-os Judah, e disse: Mais justa é ela do que eu. porquanto não a tenho dado a Selah meu filho. E nunca mais a conheceu.","E aconteceu ao tempo de parir, eis que havia gemeos em seu ventre;","E aconteceu que, parindo ela, que um pôs fora a mão, e a parteira tomou-a, e atou em sua mão um fio de grã, dizendo: Este saiu primeiro.","Mas aconteceu que, tornando ele a recolher a sua mão, eis que saiu o seu irmão, e ela disse: Como tu tens rompido? sobre ti é a rotura. E chamaram o seu nome Perez;","E depois saiu o seu irmão, em cuja mão estava o fio de grã; e chamaram o seu nome Zerah."];
GENESIS_TEXT[39]=["E José foi levado ao Egito, e Potifar, eunucho de Faraó, capitão da guarda, varão egípcio, comprou-o da mão dos ishmaelitas que o tinham levado la.","E o Senhor estava com José, e foi varão prospero; e estava na casa de seu senhor egípcio.","Vendo pois o seu senhor que o Senhor estava com ele, e tudo o que fazia o Senhor prosperava em sua mão,","José achou graça em seus olhos, e servia-o; e ele o pôs sobre a sua casa, e entregou na sua mão tudo o que tinha.","E aconteceu que, desde que o puzera sobre a sua casa, e sobre tudo o que tinha, o Senhor abençoou a casa do egípcio por amor de José; e a benção do Senhor foi sobre tudo o que tinha, na casa e no campo.","E deixou tudo o que tinha na mão de José, de maneira que de nada sabia do que estava com ele, mais do que do pão que comia. E José era formoso de parecer, e formoso a vista.","E aconteceu depois destas coisas que a mulher de seu senhor pôs os seus olhos em José, e disse: Deita-te commigo.","Porém ele recusou, e disse a mulher do seu senhor: Eis que o meu senhor não sabe do que ha em casa commigo, e entregou em minha mão tudo o que tem","Ninguem ha maior do que eu n'esta casa, e nenhuma coisa me vedou, senão a ti, porquanto tu és sua mulher; como pois faria eu este tamanho mal, e peccaria contra Deus?","E aconteceu que, fallando ela cada dia a José, e não lhe dando ele ouvidos, para deitar-se com ela, e estar com ela,","Sucedeu num certo dia que veiu a casa para fazer seu serviço; e nenhum dos da casa estava ali em casa;","E ela lhe pegou pelo seu vestido, dizendo: Deita-te commigo. E ele deixou o seu vestido na mão dela, e fugiu, e saiu para fora.","E aconteceu que, vendo ela que deixara o seu vestido em sua mão, e fugira para fora,","Chamou aos homens de sua casa, e falou-lhes, dizendo: Vêde, trouxe-nos o varão hebreu, para escarnecer de nós; entrou a mim para deitar-se commigo, e eu gritei com grande voz,","E aconteceu que, ouvindo ele que eu levantava a minha voz e gritava, deixou o seu vestido commigo, e fugiu, e saiu para fora.","E ela pôs o seu vestido perto de si, até que o seu senhor veiu a sua casa.","Então falou-lhe conforme as mesmas palavras, dizendo: Veiu a mim o servo hebreo, que nos trouxeste para escarnecer de nim;","E aconteceu que, levantando eu a minha voz e gritando, ele deixou o seu vestido commigo, e fugiu para fora.","E aconteceu que, ouvindo o seu senhor as palavras de sua mulher, que lhe fallava, dizendo: Conforme a estas mesmas palavras me fez teu servo; a sua ira se accendeu.","E o senhor de José o tomou, e o entregou na casa do carcere, no lugar onde os presos do rei estavam presos; assim esteve ali na casa do carcere.","O Senhor, porém, estava com José, e estendeu sobre ele a sua benignidade, e deu-lhe graça aos olhos do carcereiro-mór.","E o carcereiro-mór entregou na mão de José todos os presos que estavam na casa do carcere, e ele fazia tudo o que se fazia ali.","E o carcereiro-mór não teve cuidado de nenhuma coisa que estava na mão dele; porquanto o Senhor estava com ele, e tudo o que fazia o Senhor prosperava."];
GENESIS_TEXT[40]=["E aconteceu depois destas coisas que peccaram o copeiro do rei do Egito, e o padeiro, contra o seu senhor, o rei do Egito.","E indignou-se Faraó muito contra os seus dois eunuchos, contra o copeiro-mór e contra o padeiro mór,","E entregou-os em guarda, na casa do capitão da guarda, na casa do carcere, no lugar onde José estava preso.","E o capitão da guarda deu cargo deles a José, para que os servisse; e estiveram muitos dias na prisão.","E ambos sonharam um sonho, cada um seu sonho na mesma noite, cada um conforme a interpretação do seu sonho, o copeiro e o padeiro do rei do Egito, que estavam presos na casa do carcere.","E veiu José a eles pela manhã, e olhou para eles, e eis que estavam turbados.","Então perguntou aos eunuchos de Faraó, que com ele estavam no carcere da casa de seu senhor, dizendo: Porque estão hoje tristes os vossos semblantes?","E eles lhe disseram: Temos sonhado um sonho, e ninguem ha que o interprete. E José disse-lhes: Não são de Deus as interpretações? contae-m'o, peço-vos.","Então contou o copeiro-mór o seu sonho a José, e disse-lhe: Eis que em meu sonho havia uma vide diante da minha face,","E na vide tres sarmentos, e estava como brotando; a sua flôr sahia, os seus cachos amadureciam em uvas:","E o copo de Faraó estava na minha mão, e eu tomava as uvas, e as espremia no copo de Faraó, e dava o copo na mão de Faraó.","Então disse-lhe José: Esta é a sua interpretação: os tres sarmentos são tres dias;","Dentro ainda de tres dias Faraó levantara a tua cabeça, e te restaurara ao teu estado, e daràs o copo de Faraó na sua mão, conforme o costume antigo, quando eras seu copeiro.","Porem lembra-te de mim, quando te fôr bem; e rogo-te que uses commigo de compaixão, e que faças menção de mim a Faraó, e faze-me sair desta casa;","Porque, de facto, fui roubado da terra dos hebreus; e tão pouco aqui nada tenho feito para que me puzessem n'esta cova.","Vendo então o padeiro-mór que tinha interpretado bem, disse a José: Eu também sonhava, e eis que tres cestos brancos estavam sobre a minha cabeça;","E no cesto mais alto havia de todos os manjares de Faraó, da obra de padeiro: e as aves o comiam do cesto de sobre a minha cabeça.","Então respondeu José, e disse: Esta é a sua interpretação: os tres cestos são tres dias;","Dentro ainda de tres dias Faraó levantara a tua cabeça sobre ti, e te pendurara num pau, e as aves comerão a tua carne de sobre ti.","E aconteceu ao terceiro dia, o dia do nascimento de Faraó, que fez um banquete a todos os seus servos; e levantou a cabeça do copeiro-mór, e a cabeça do padeiro-mór, no meio dos seus servos.","E fez tornar o copeiro-mór ao seu officio de copeiro, e deu o copo na mão de Faraó,","Mas ao padeiro-mór enforcou, como José havia interpretado.","O copeiro-mór, porém, não se lembrou de José, antes esqueceu-se dele."];
GENESIS_TEXT[41]=["E aconteceu que, ao fim de dois anos inteiros, Faraó sonhou, e eis que estava em pé junto ao rio,","E eis que subiam do rio sete vacas, formosas a vista e gordas de carne, e pastavam no prado.","E eis que subiam do rio após elas outras sete vacas, feias a vista e magras de carne; e paravam junto às outras vacas na praia do rio.","E as vacas feias a vista, e magras de carne, comiam as sete vacas formosas a vista e gordas. Então acordou Faraó.","Depois dormiu, e sonhou outra vez, e eis que brotavam d'uma cana sete espigas cheias e boas,","E eis que sete espigas miudas, e queimadas do vento oriental, brotavam após elas.","E as espigas miudas devoravam as sete espigas grandes e cheias. Então acordou Faraó, e eis que era um sonho.","E aconteceu que pela manhã o seu espirito perturbou-se, e enviou e chamou todos os adivinhadores do Egito, e todos os seus sabios; e Faraó contou-lhes os seus sonhos, mas ninguem havia que os interpretasse a Faraó.","Então falou o copeiro-mór a Faraó, dizendo: Dos meus peccados me lembro hoje:","Estando Faraó mui indignado contra os seus servos, e pondo-me em guarda na casa do capitão da guarda, a mim e ao padeiro-mór,","Então sonhamos um sonho na mesma noite, eu e ele, cada um conforme a interpretação do seu sonho sonhamos.","E estava ali comnosco um mancebo hebreu, servo do capitão da guarda, e contamos-lh'os, e interpretou-nos os nossos sonhos, a cada um os interpretou conforme o seu sonho.","E como ele nos interpretou, assim mesmo foi feito: a mim me fez tornar ao meu estado, e a ele fez enforcar.","Então enviou Faraó, e chamou a José, e o fizeram sair logo da cova; e barbeou-se e mudou os seus vestidos, e veiu a Faraó.","E Faraó disse a José: Eu sonhei um sonho, e ninguem ha que o interprete; mas de ti ouvi dizer que quando ouves um sonho o interpretas.","E respondeu José a Faraó, dizendo: Sem mim é isso: Deus respondera paz a Faraó.","Então disse Faraó a José: Eis que em meu sonho estava eu em pé na praia do rio","E eis que subiam do rio sete vacas gordas de carne e formosas a vista, e pastavam no prado.","E eis que outras sete vacas subiam após estas, muito feias a vista, e magras de carne; não tenho visto outras taes, emquanto a fealdade, em toda a terra do Egito.","E as vacas magras e feias comiam os primeiras sete vacas gordas;","E entravam em suas entranhas, mas não se conhecia que houvessem entrado em suas entranhas: porque o seu parecer era feio como no principio. Então acordei.","Depois vi em meu sonho, e eis que d'uma cana subiam sete espigas cheias e boas;","E eis que sete espigas seccas, miudas e queimadas do vento oriental, brotavam após elas.","E as sete espigas miudas devoravam as sete espigas boas. E eu disse-o aos magos, mas ninguem houve que m'o interpretasse.","Então disse José a Faraó: O sonho de Faraó é um só; o que Deus ha de fazer, notificou a Faraó.","As sete vacas formosas são sete anos; as sete espigas formosas também são sete anos: o sonho é um só","E as sete vacas feias a vista e magras, que subiam depois delas, são sete anos; e as sete espigas miudas e queimadas do vento oriental, serão sete anos de fome.","Esta é a palavra que tenho dito a Faraó; o que Deus ha de fazer, mostrou-o a Faraó.","E eis que veem sete anos, e havera grande fartura em toda a terra do Egito.","E depois deles levantar-se-hão sete anos de fome, e toda aquela fartura sera esquecida na terra do Egito, e a fome consumira a terra;","E não sera conhecida a abundancia na terra, por causa daquela fome que havera depois; porquanto sera gravissima.","E que o sonho foi duplicado duas vezes a Faraó, é porquanto esta coisa é determinada de Deus, e Deus se apressa a fazel-a.","Portanto Faraó se proveja agora d'um varão entendido e sabio, e o ponha sobre a terra do Egito:","Faça isso Faraó, e ponha governadores sobre a terra, e tome a quinta parte da terra do Egito nos sete anos de fartura,","E ajuntem toda a comida destes bons anos, que veem, e amontoem o trigo debaixo da mão de Faraó, para mantimento nas cidades, e o guardem;","Assim sera o mantimento para provimento da terra, para os sete anos de fome, que havera na terra do Egito; para que a terra não pereça de fome.","E esta palavra foi boa aos olhos de Faraó, e aos olhos de todos os seus servos.","E disse Faraó a seus servos: Achariamos um varão como este, em quem haja o espirito de Deus?","Depois disse Faraó a José: Pois que Deus te fez saber tudo isto, ninguem ha tão entendido e sabio como tu","Tu estaràs sobre a minha casa, e por tua bocca se governara todo o meu povo, somente no throno eu serei maior que tu","Disse mais Faraó a José: Vês aqui te tenho posto sobre toda a terra do Egito.","E tirou Faraó o seu annel da sua mão, e o pôs na mão de José, e o fez vestir de vestidos de linho fino, e pôs um collar d'oiro no seu pescoço,","E o fez subir no segundo carro que tinha, e clamavam diante dele: Ajoelhae; assim o pôs sobre toda a terra do Egito.","E disse Faraó a José: Eu sou Faraó; porém sem ti ninguem levantara a sua mão ou o seu pé em toda a terra do Egito","E chamou Faraó o nome de José Zaphnath-paneah, e deu-lhe por mulher a Asenath, filha de Potiphera, sacerdote de On; e saiu José por toda a terra do Egito.","E José era da idade de trinta anos quando esteve diante da face de Faraó, rei do Egito. E saiu José da face de Faraó, e passou por toda a terra do Egito.","E a terra produziu nos sete anos de fartura a mãos cheias.","E ajuntou todo o mantimento dos sete anos, que houve na terra do Egito, e guardou o mantimento nas cidades, pondo nas cidades o mantimento do campo que estava ao redor de cada cidade.","Assim ajuntou José muitissimo trigo, como a areia do mar, até que cessou de contar; porquanto não havia numeração.","E nasceram a José dois filhos (antes que viesse um ano de fome), que lhe pariu Asenath, filha de Potiphera, sacerdote de On.","E chamou José o nome do primogenito Manasseh ; porque disse: Deus me fez esquecer de todo o meu trabalho, e de toda a casa de meu pai.","E o nome do segundo chamou Ephraim ; porque disse: Deus me fez crescer na terra da minha afflicção.","Então acabaram-se os sete anos de fartura que havia na terra do Egito,","E começaram a vir os sete anos de fome, como José tinha dito; e havia fome em todas as terras, mas em toda a terra do Egito havia pão.","E tendo toda a terra do Egito fome, clamou o povo a Faraó por pão; e Faraó disse a todos os egípcios: Ide a José ; o que ele vos disser, fazei.","Havendo pois fome sobre toda a terra, abriu José tudo em que havia mantimento, e vendeu aos egípcios; porque a fome prevaleceu na terra de Egito.","E todas as terras vinham ao Egito, para comprar de José; porquanto a fome prevaleceu em todas as terras."];
GENESIS_TEXT[42]=["Vendo então Jacó que havia mantimento no Egito, disse Jacó a seus filhos: Porque estaes olhando uns para os outros?","Disse mais: Eis que tenho ouvido que ha mantimentos no Egito; descei para la, e comprae-nos d'ali, para que vivamos e não morramos.","Então desceram os dez irmãos de José, para comprarem trigo do Egito.","A Benjamin, porém, irmão de José não enviou Jacó com os seus irmãos, porque dizia: Para que lhe não succeda porventura algum desastre.","Assim vieram os filhos de Israel para comprar, entre os que vinham la; porque havia fome na terra de Canaã.","José, pois, era o governador daquela terra; ele vendia a todo o povo da terra; e os irmãos de José vieram, e inclinaram-se a ele com a face na terra.","E José, vendo os seus irmãos, conheceu-os; porém mostrou-se estranho para com eles, e falou com eles asperamente, e disse-lhes: D'onde vindes? E eles disseram: Da terra de Canaã, para comprarmos mantimento.","José, pois, conheceu os seus irmãos; mas eles não o conheceram.","Então José lembrou-se dos sonhos, que havia sonhado deles, e disse-lhes: Vós sois espias, e sois vindos para ver a nudez da terra.","E eles lhe disseram: Não, senhor meu; mas teus servos são vindos a comprar mantimento.","Todos nós somos filhos de um varão; somos homens de rectidão; os teus servos não são espias.","E ele lhes disse: Não; antes viestes para ver a nudez da terra.","E eles disseram: Nós, teus servos, somos doze irmãos, filhos de um varão na terra de Canaã; e eis que aqui o mais novo esta com nosso pai hoje; mas um não esta mais.","Então lhes disse José: Isso é o que vos tenho dito, dizendo que sois espias:","N'isto sereis provados; pela vida de Faraó, não saireis daqui senão quando vosso irmão mais novo vier aqui.","Enviae um d'entre vós, que traga vosso irmão, mas vós ficareis presos, e vossas palavras sejam provadas, se ha verdade comvosco; e se não, pela vida de Faraó, vós sois espias.","E pôl-os juntos em guarda tres dias.","E ao terceiro dia disse-lhes José: Fazei isso, e vivereis; porque eu temo a Deus.","Se sois homens de rectidão, que fique um de vossos irmãos preso na casa de vossa prisão; e vós ide, levae mantimento para a fome de vossa casa,","E trazei-me o vosso irmão mais novo, e serão verificadas vossas palavras, e não morrereis. E eles assim fizeram.","Então disseram uns aos outros: Na verdade, somos culpados acerca de nosso irmão, pois vimos a angustia da sua alma, quando nos rogava; nós porém não ouvimos: por isso vem sobre nós esta angustia.","E Ruben respondeu-lhes, dizendo: Não vol-o dizia eu, dizendo: Não pequeis contra o moço; mas não ouvistes: e vêdes aqui, o seu sangue também a requerido.","E eles não sabiam que José os entendia, porque havia interprete entre eles.","E retirou-se deles, e chorou. Depois tornou a eles, e falou-lhes, e tomou a Simeão deles, e amarrou-o perante os seus olhos.","E ordenou José, que enchessem os seus saccos de trigo, e que lhes restituissem o seu dinheiro a cada um no seu sacco, e lhes dessem comida para o caminho; e fizeram-lhes assim.","E carregaram o seu trigo sobre os seus jumentos, e partiram d'ali.","E, abrindo um deles o seu sacco, para dar pasto ao seu jumento na venda, viu o seu dinheiro; porque eis que estava na bocca do seu sacco.","E disse a seus irmãos: Tornou-se o meu dinheiro, e eil-o também aqui no meu sacco. Então lhes desfalleceu o coração, e pasmavam, dizendo um ao outro: Que é isto que Deus nos tem feito?","E vieram para Jacó, seu pai, na terra de Canaã; e contaram-lhe tudo o que lhes aconteceu, dizendo:","O varão, o senhor da terra, falou comnosco asperamente, e tratou-nos como espias da terra;","Mas dissemos-lhe: Somos homens de rectidão: não somos espias:","Somos doze irmãos, filhos de nosso pai; um não é mais, e o mais novo esta hoje com nosso pai na terra de Canaã.","E aquele varão, o senhor da terra, nos disse: N'isto conhecerei que vós sois homens de rectidão; deixae commigo um de vossos irmãos, e tomae para a fome de vossas casas, e parti,","E trazei-me vosso irmão mais novo; assim saberei que não sois espias, mas homens de rectidão; então vos darei o vosso irmão e negociareis na terra.","E aconteceu que, despejando eles os seus saccos, eis que cada um tinha a trouxinha com seu dinheiro no seu sacco; e viram as trouxinhas com seu dinheiro, eles e seu pai, e temeram.","Então Jacó, seu pai, disse-lhes: Tendes-me desfilhado; José não esta mais, e Simeão não esta mais: agora levareis a Benjamin. Todas estas coisas vieram sobre mim.","Mas Ruben falou a seu pai, dizendo: Mata os meus dois filhos, se t'o não tornar a trazer; da-m'o em minha mão, e t'o tornarei a trazer.","Ele porém disse: Não descera meu filho comvosco; porquanto o seu irmão é morto, e ele só ficou. Se lhe succedesse algum desastre no caminho que fordes, fareis descer minhas cãs com tristeza a sepultura."];
GENESIS_TEXT[43]=["E a fome era gravissima na terra.","E aconteceu que, como acabaram de comer o mantimento que trouxeram do Egito, disse-lhes seu pai: Tornae, comprae-nos um pouco de alimento.","Mas Judah respondeu-lhe, dizendo: Fortemente nos protestou aquele varão, dizendo: Não vereis a minha face, se o vosso irmão não vier comvosco.","Se enviares comnosco o nosso irmão, desceremos, e te compraremos alimento;","Mas se não o enviares, não desceremos; porquanto aquele varão nos disse: Não vereis a minha face, se o vosso irmão não vier comvosco.","E disse Israel: Porque me fizestes tal mal, fazendo saber aquele varão que tinheis ainda outro irmão?","E eles disseram: Aquele varão particularmente nos perguntou por nós, e pela nossa parentela, dizendo: Vive ainda vosso pai? tendes mais um irmão? e respondemos-lhe conforme as mesmas palavras. Podiamos nós saber que diria: Trazei vosso irmão?","Então disse Judah a Israel, seu pai: Envia o mancebo commigo, e levantar-nos-hemos, e iremos, para que vivamos, e não morramos, nem nós, nem tu, nem os nossos filhos.","Eu serei fiador por ele, da minha mão o requereràs; se eu não t'o trouxer, e não o pôser perante a tua face, serei réu de crime para comtigo para sempre:","E se nós não nos tivessemos detido, certamente ja estariamos segunda vez de volta.","Então disse-lhes Israel, seu pai: Pois que assim é, fazei isso; tomae do mais precioso desta terra em vossos vasos, e levae ao varão um presente: um pouco de balsamo, e um pouco de mel, especiarias, e myrrha, terebintho e amendoas;","E tomae em vossas mãos dinheiro dobrado, e o dinheiro que tornou na bocca dos vossos saccos tornae a levar em vossas mãos; bem pode ser que fosse erro;","Tomae também a vosso irmão, e levantae-vos, e voltae aquele varão;","E Deus Todo-poderoso vos dê misericordia diante do varão, para que deixe vir comvosco vosso outro irmão, e Benjamin; e eu, se fôr desfilhado, desfilhado ficarei.","E os varões tomaram aquele presente, e tomaram dinheiro dobrado em suas mãos, e a Benjamin: e levantaram-se, e desceram ao Egito, e apresentaram-se diante da face de José.","Vendo pois José a Benjamin com eles, disse ao que estava sobre a sua casa: Leva estes varões a casa, e mata rezes, e apresta; porque estes varões comerão commigo ao meio dia.","E o varão fez como José dissera, e o varão levou aqueles varões a casa de José","Então temeram aqueles varões, porquanto foram levados a casa de José, e diziam: Por causa do dinheiro que d'antes foi tornado nos nossos saccos, fomos levados aqui, para nos criminar e cair sobre nós, para que nos tome por servos, e a nossos jumentos.","Por isso chegaram-se ao varão que estava sobre a casa de José, e falaram com ele a porta da casa,","E disseram: Ai! senhor meu, certamente descemos d'antes a comprar mantimento;","E aconteceu que, chegando nós a venda, e abrindo os nossos saccos, eis que o dinheiro de cada varão estava na bocca do seu sacco, nosso dinheiro por seu peso; e tornamos a trazel-o em nossas mãos;","Também trouxemos outro dinheiro em nossas mãos, para comprar mantimento; não sabemos quem tenha posto o nosso dinheiro nos nossos saccos.","E ele disse: Paz seja comvosco, não temaes; o vosso Deus, e o Deus de vosso pai, vos tem dado um thesoiro nos vossos saccos; o vosso dinheiro me chegou a mim. E trouxe-lhes fora a Simeão.","Depois levou o varão aqueles varões a casa de José, e deu-lhes agua, e lavaram os seus pés; também deu pasto aos seus jumentos.","E prepararam o presente, para quando José viesse ao meio dia; porque tinham ouvido que ali haviam de comer pão.","Vindo pois José a casa, trouxeram-lhe a casa o presente, que estava na sua mão; e inclinaram-se a ele a terra.","E ele lhes perguntou como estavam, e disse: Vosso pai, o velho de quem fallastes, esta bem? ainda vive?","E eles disseram: Bem esta o teu servo, nosso pai vive ainda. E abaixaram a cabeça, e inclinaram-se.","E ele levantou os seus olhos, e viu a Benjamin, seu irmão, filho de sua mãe, e disse: Este é vosso irmão mais novo de quem me fallastes? Depois ele disse: Deus te dê a sua graça, meu filho","E José apressou-se, porque as suas entranhas moveram-se para o seu irmão, e procurou onde chorar; e entrou na camara, e chorou ali.","Depois lavou o seu rosto, e saiu; e conteve-se, e disse: Ponde pão.","E pôseram-lhe a ele a parte, e a eles a parte, e aos egípcios, que comiam com ele, a parte; porque os egípcios não podem comer pão com os hebreus, porquanto é abominação para os egípcios.","E assentaram-se diante dele, o primogenito segundo a sua primogenitura, e o menor segundo a sua menoridade: do que os varões se maravilhavam entre si.","E apresentou-lhes as porções que estavam diante dele; porém a porção de Benjamin era cinco vezes maior do que as porções deles todos. E eles beberam, e se regalaram com ele."];
GENESIS_TEXT[44]=["E deu ordem ao que estava sobre a sua casa, dizendo: Enche os saccos destes varões de mantimento, quanto poderem levar, e põe o dinheiro de cada varão na bocca do seu sacco.","E o meu copo, o copo de prata, poràs na bocca do sacco do mais novo, com o dinheiro do seu trigo. E fez conforme a palavra de José, que tinha dito.","Vinda a luz da manhã, despediram-se estes varões, eles com os seus jumentos.","Saindo eles da cidade, e não se havendo ainda distanciado, disse José ao que estava sobre a sua casa: Levanta-te, e persegue aqueles varões: e, alcançando-os, lhes diràs: Porque pagastes mal por bem?","Não é este o copo por que bebe meu senhor? e em que ele bem attenta? fizestes mal no que fizestes.","E alcançou-os, e falou-lhes as mesmas palavras.","E eles disseram-lhe: Porque diz meu senhor taes palavras? longe estejam teus servos de fazerem similhante coisa.","Eis que o dinheiro, que temos achado nas boccas dos nossos saccos, te tornamos a trazer desde a terra de Canaã: como pois furtariamos da casa do teu senhor prata ou oiro?","Aquele, com quem de teus servos fôr achado, morra; e ainda nós seremos escravos do meu senhor.","E ele disse: Ora seja também assim conforme as vossas palavras; aquele com quem se achar sera meu escravo, porém vós sereis desculpados.","E eles apressaram-se, e cada um pôs em terra o seu sacco, e cada um abriu o seu sacco.","E buscou, começando do maior, e acabando no mais novo: e achou-se o copo no sacco de Benjamin.","Então rasgaram os seus vestidos, e carregou cada um o seu jumento, e tornaram a cidade.","E veiu Judah com os seus irmãos a casa de José, porque ele ainda estava ali; e prostraram-se diante dele na terra.","E disse-lhes José: Que é isto que obrastes? não sabeis vós que tal homem como eu bem attentara?","Então disse Judah: Que diremos a meu senhor? que falaremos? e como nos justificaremos? Achou Deus a iniquidade de teus servos; eis que somos escravos de meu senhor, tanto nós como aquele em cuja mão foi achado o copo.","Mas ele disse: Longe de mim que eu tal faça; o varão em cuja mão o copo foi achado, aquele sera meu servo; porém vós subi em paz para vosso pai.","Então Judah se chegou a ele, e disse: Ai! senhor meu, deixa, peço-te, o teu servo dizer uma palavra aos ouvidos de meu senhor, e não se accenda a tua ira contra o teu servo; porque tu és como Faraó.","Meu senhor perguntou a seus servos, dizendo: Tendes vós pai, ou irmão?","E dissemos a meu senhor: Temos um pai velho, e um moço da sua velhice, o mais novo, cujo irmão é morto; e ele ficou só de sua mãe, e seu pai o ama.","Então tu disseste a teus servos: Trazei-m'o a mim, e porei os meus olhos sobre ele.","E nós dissemos a meu senhor: Aquele moço não podera deixar a seu pai: se deixar a seu pai, morrera.","Então tu disseste a teus servos: Se vosso irmão mais novo não descer comvosco, nunca mais vereis a minha face.","E aconteceu que, subindo nós a teu servo meu pai, e contando-lhe as palavras de meu senhor,","Disse nosso pai: Tornae, comprae-nos um pouco de mantimento.","E nós dissemos: Não poderemos descer; se nosso irmão menor fôr comnosco, desceremos; pois não poderemos ver a face do varão, se este nosso irmão menor não estiver comnosco.","Então disse-nos teu servo meu pai: Vós sabeis que minha mulher me pariu dois;","E um saiu de mim, e eu disse: Certamente foi despedaçado, e não o tenho visto até agora;","Se agora também tirardes a este da minha face, e lhe acontecesse algum desastre, farieis descer as minhas cãs com dôr a sepultura.","Agora pois, vindo eu a teu servo meu pai, e o moço não indo comnosco, pois que a sua alma esta atada com a alma dele,","Acontecera que, vendo ele que o moço ali não esta, morrera; e teus servos farão descer as cãs de teu servo, nosso pai, com tristeza a sepultura.","Porque teu servo se deu por fiador por este moço para com meu pai, dizendo: Se não t'o tornar, eu serei culpado a meu pai todos os dias.","Agora, pois, fique teu servo em lugar deste moço por escravo de meu senhor, e que suba o moço com os seus irmãos.","Porque como subirei eu a meu pai, se o moço não fôr commigo? para que não veja eu o mal que sobrevira a meu pai. ,"];
GENESIS_TEXT[45]=["Então José não se podia conter diante de todos os que estavam com ele; e clamou: Fazei sair de mim a todo o varão; e ninguem ficou com ele, quando José se deu a conhecer a seus irmãos.","E levantou a sua voz com chôro, de maneira que os egípcios o ouviam, e a casa de Faraó o ouviu.","E disse José a seus irmãos: Eu sou José: vive ainda meu pai? E seus irmãos não lhe poderam responder, porque estavam pasmados diante da sua face","E disse José a seus irmãos: Peço-vos, chegae-vos a mim. E chegaram-se; então disse ele: Eu sou José, vosso irmão, a quem vendestes para o Egito.","Agora, pois, não vos entristeçaes, nem vos peze aos vossos olhos por me haverdes vendido para ca; porque para conservação da vida, Deus me enviou diante da vossa face","Porque ja houve dois anos de fome no meio da terra, e ainda restam cinco anos em que não havera lavoura nem sega.","Pelo que Deus me enviou diante da vossa face, para que ficasseis um resto na terra, e para guardar-vos em vida por uma grande livração.","Assim não fostes vós que me enviastes para ca, senão Deus, que me tem posto por pai de Faraó, e por senhor de toda a sua casa, e como regente em toda a terra do Egito.","Apressae-vos, e subi a meu pai, e dizei-lhe: Assim tem dito o teu filho José: Deus me tem posto por senhor em toda a terra do Egito; desce a mim, e não te demores;","E habitaràs na terra de Gosen, e estaràs perto de mim, tu e os teus filhos, e os filhos dos teus filhos, e as tuas ovelhas, e as tuas vacas, e tudo o que tens.","E ali te sustentarei, porque ainda havera cinco anos de fome, para que não pereças de pobreza, tu e tua casa, e tudo o que tens.","E eis que vossos olhos o vêem, e os olhos de meu irmão Benjamin, que é minha bocca que vos falla.","E fazei saber a meu pai toda a minha gloria no Egito, e tudo o que tendes visto, e apressae-vos a fazer descer meu pai para ca.","E lançou-se ao pescoço de Benjamin seu irmão, e chorou; e Benjamin chorou também ao seu pescoço.","E beijou a todos os seus irmãos, e chorou sobre eles; e depois seus irmãos falaram com ele.","E a fama ouviu-se na casa de Faraó, dizendo: Os irmãos de José são vindos; e pareceu bem aos olhos de Faraó, e aos olhos de seus servos.","E disse Faraó a José: Dize a teus irmãos: Fazei isto, carregae as vossas bestas e parti, tornae a terra de Canaã,","E tornae a vosso pai, e a vossas familias, e vinde a mim; e eu vos farei o melhor da terra do Egito, e comereis a gordura da terra.","A ti pois é ordenado; fazei isto, tomae vós da terra do Egito carros para vossos meninos, para vossas mulheres, e para vosso pai, e vinde.","E não vos peze coisa alguma das vossas alfaias; porque o melhor de toda a terra do Egito sera vosso.","E os filhos de Israel fizeram assim. E José deu-lhes carros, conforme o mandado de Faraó; também lhes deu comida para o caminho.","A todos lhes deu, a cada um, mudas de vestidos; mas a Benjamin deu trezentas peças de prata, e cinco mudas de vestidos.","E a seu pai enviou similhantemente dez jumentos carregados do melhor do Egito, e dez jumentos carregados de trigo, e pão, e comida para seu pai, para o caminho.","E despediu os seus irmãos, e partiram; e disse-lhes: Não contendaes pelo caminho.","E subiram do Egito, e vieram a terra de Canaã, a Jacó seu pai.","Então lhe annunciaram, dizendo: José ainda vive, e ele também é regente em toda a terra do Egito. E o seu coração desmaiou-se, porque não os acreditava.","Porém, havendo-lhe eles contado todas as palavras de José, que ele lhes fallara, e vendo ele os carros que José enviara para leval-o, reviveu o espirito de Jacó seu pai","E disse Israel: Basta; ainda vive meu filho José; eu irei, e o verei antes que morra."];
GENESIS_TEXT[46]=["E partiu Israel com tudo quanto tinha, e veiu a Berseba, e sacrificou sacrificios ao Deus de seu pai Isaac.","E falou Deus a Israel em visões da noite, e disse: Jacó, Jacó! E ele disse: Eis-me aqui.","E disse: Eu sou o Deus, o Deus de teu pai; não temas de descer ao Egito, porque eu te farei ali uma grande nação.","E descerei comtigo ao Egito, e certamente te farei tornar a subir, e José pora a sua mão sobro os teus olhos.","Então levantou-se Jacó de Berseba, e os filhos de Israel levaram a seu pai Jacó, e seus meninos, e as suas mulheres, nos carros que Faraó enviara para o levar.","E tomaram o seu gado e a sua fazenda que tinham adquirido na terra de Canaã, e vieram ao Egito, Jacó e toda a sua semente com ele,","Os seus filhos, e os filhos de seus filhos com ele, as suas filhas, e as filhas de seus filhos, e toda a sua semente levou comsigo ao Egito.","E estes são os nomes dos filhos de Israel, que vieram ao Egito, Jacó e seus filhos: Ruben, o primogenito de Jacó,","E os filhos de Ruben: Hanoch, e Pallu, e Hezron, e Carmi.","E os filhos de Simeão: Jemuel, e Jamin, e Ohad, e Jachin, e Zohar, e Shaul, filho de uma mulher cananea.","E os filhos de Levi: Gerson, Kohath, e Merari.","E os filhos de Judah: Er, e Onan, e Sela, e Perez, e Serah; Er e Onan, porém, morreram na terra de Canaã; e os filhos de Perez foram Hezron e Hamul.","E os filhos de Issacar: Tola, e Puah, e Iob, e Simron.","E os filhos de Zebulon: Sered, e Elon, e Jahleel.","Estes são os filhos de Lia, que pariu a Jacó em Paddan-aram, com Dinah, sua filha: todas as almas de seus filhos e de suas filhas foram trinta e tres.","E os filhos de Gad: Ziphion, e Haggi, Shuni, e Ezbon, Eri, e Arodi, e Areli.","E os filhos de Asher: Imnah, e Ischva, e Ischvi, e Beria, e Serah, a irmã deles: e os filhos de Beria: Heber e Malchiel.","Estes são os filhos de Zilpah, que Labão deu a sua filha Lia; e pariu a Jacó estas dezeseis almas.","Os filhos de Raquel, mulher de Jacó: José e Benjamin.","E nasceram a José na terra do Egito Manasseh e Ephraim, que lhe pariu Asenath, filha de Potiphera, sacerdote de On.","E os filhos de Benjamin: Belah, Becher, e Asbel, Gera, e, Naaman, Echi e Rosh, Muppim, e Huppim, e Ard.","Estes são os filhos de Raquel, que nasceram a Jacó, ao todo quatorze almas.","E os filhos de Dan: Husim.","E os filhos de Naphtali: Jahzeel, e Guni, e Jezer, e Shilem.","Estes são os filhos de Bilha, que Labão deu a sua filha Raquel; e pariu estes a Jacó; todas as almas foram sete.","Todas as almas que vieram com Jacó ao Egito, que sairam da sua côxa, sem as mulheres dos filhos de Jacó, todas foram sessenta e seis almas.","E os filhos de José, que lhe nasceram no Egito, eram duas almas. Todas as almas da casa de Jacó, que vieram ao Egito, foram setenta.","E enviou a Judah diante da sua face a José, para o encaminhar a Gosen; e chegaram a terra de Gosen.","Então José apromptou o seu carro, e subiu ao encontro de Israel, seu pai, a Gosen. E, mostrando-se-lhe, lançou-se ao seu pescoço, e chorou sobre o seu pescoço longo tempo.","E Israel disse a José: Morra eu agora, pois ja tenho visto o teu rosto, que ainda vives.","Depois disse José a seus irmãos, e a casa de seu pai: Eu subirei, e annunciarei a Faraó, e lhe direi: Meus irmãos, e a casa de meu pai, que estavam na terra de Canaã, vieram a mim!","E os varões são pastores de ovelhas, porque são homens de gado, e trouxeram comsigo as suas ovelhas, e as suas vacas, e tudo o que teem.","Quando pois acontecer que Faraó vos chamar, e disser: Qual é vosso negocio?","Então direis: Teus servos foram homens de gado desde a nossa mocidade até agora, tanto nós como os nossos pais; para que habitemos na terra de Gosen; porque todo o pastor de ovelhas é abominação aos egípcios."];
GENESIS_TEXT[47]=["Então veiu José, e annunciou a Faraó, e disse: Meu pai, e os meus irmãos, e as suas ovelhas, e as suas vacas, com tudo o que teem, são vindos da terra de Canaã, e eis que estão na terra de Gosen","E tomou uma parte de seus irmãos, a saber cinco varões, e os pôs diante de Faraó.","Então disse Faraó a seus irmãos: Qual é vosso negocio? E eles disseram a Faraó: Teus servos são pastores de ovelhas, tanto nós como nossos pais.","Disseram mais a Faraó: Viemos para peregrinar n'esta terra; porque não ha pasto para as ovelhas de teus servos, porquanto a fome é grave na terra de Canaã; agora pois rogamos-te que teus servos habitem na terra de Gosen.","Então falou Faraó a José, dizendo: Teu pai e teus irmãos vieram a ti:","A terra do Egito esta diante da tua face, no melhor da terra faze habitar teu pai e teus irmãos; habitem na terra de Gosen: e se sabes que entre eles ha homens valentes, os poràs por maioraes do gado, sobre o que eu tenho.","E trouxe José a Jacó, seu pai, e o pôs diante de Faraó; e Jacó abençoou a Faraó.","E Faraó disse a Jacó: Quantos são os dias dos anos da tua vida?","E Jacó disse a Faraó: Os dias dos anos das minhas peregrinações são cento e trinta anos; poucos e maus foram os dias dos anos da minha vida, e não chegaram aos dias dos anos da vida de meus pais nos dias das suas peregrinações.","E Jacó abençoou a Faraó, e saiu de diante da face de Faraó.","E José fez habitar a seu pai e seus irmãos, e deu-lhes possessão na terra do Egito, no melhor da terra, na terra de Rameses, como Faraó ordenara.","E José sustentou de pão a seu pai, e seus irmãos, e toda a casa de seu pai, segundo os seus meninos.","E não havia pão em toda a terra, porque a fome era mui grave; de maneira que a terra do Egito e a terra de Canaã desfalleciam por causa da fome.","Então José recolheu todo o dinheiro que se achou na terra do Egito, e na terra de Canaã, pelo trigo que compravam: e José trouxe o dinheiro a casa de Faraó.","Acabando-se pois o dinheiro da terra do Egito, e da terra de Canaã, vieram todos os egípcios a José, dizendo: Da-nos pão; porque morreremos em tua presença? porquanto o dinheiro nos falta.","E José disse: Dae o vosso gado, e eu vol-o darei por vosso gado, se falta o dinheiro.","Então trouxeram o seu gado a José: e José deu-lhes pão em troca de cavalos, e do gado das ovelhas, e do gado das vacas e dos jumentos; e os sustentou de pão aquele ano por todo o seu gado","E acabado aquele ano, vieram a ele no segundo ano, e disseram-lhe: Não occultaremos ao meu senhor que o dinheiro é acabado, e meu senhor possue os animaes, e nenhuma outra coisa nos ficou diante da face de meu senhor, senão o nosso corpo e a nossa terra;","Porque morreremos diante dos teus olhos, tanto nós como a nossa terra? compra-nos a nós e a nossa terra por pão, e nós e a nossa terra seremos servos de Faraó, e da semente para que vivamos, e não morramos, e a terra não se desole.","Assim José comprou toda a terra do Egito para Faraó, porque os egípcios venderam cada um o seu campo, porquanto a fome prevaleceu sobre eles: e a terra ficou sendo de Faraó.","E, quanto ao povo, fel-o passar às cidades, desde uma extremidade da terra do Egito até a outra extremidade.","Somente a terra dos sacerdotes não a comprou, porquanto os sacerdotes tinham porção de Faraó, e eles comiam a sua porção que Faraó lhes tinha dado; por isso não venderam a sua terra.","Então disse José ao povo: Eis que hoje tenho comprado a vós e a vossa terra para Faraó; eis ahi tendes semente para vós, para que semeeis a terra.","Ha de ser, porém, que das colheitas dareis o quinto a Faraó, e as quatro partes serão vossas, para semente do campo, e para o vosso mantimento, e dos que estão nas vossas casas, e para que comam vossos meninos.","E disseram: A vida nos tens dado; achemos graça nos olhos de meu senhor, e seremos servos de Faraó.","José pois pôs isto por estatuto até ao dia de hoje, sobre a terra do Egito, que Faraó tirasse o quinto: só a terra dos sacerdotes não ficou sendo de Faraó.","Assim habitou Israel na terra do Egito, na terra de Gosen, e nela tomaram possessão, e fructificaram, e multiplicaram-se muito.","E Jacó viveu na terra do Egito dezesete anos: de sorte que os dias de Jacó, os anos da sua vida, foram cento e quarenta e sete anos.","Chegando-se pois o tempo da morte d'Israel, chamou a José seu filho, e disse-lhe: Se agora tenho achado graça em teus olhos, rogo-te que ponhas a tua mão debaixo da minha côxa, e usa commigo de beneficencia e verdade; rogo-te que me não enterres no Egito.","Mas que eu jaza com os meus pais; por isso me levaràs do Egito, e me sepultaràs na sepultura deles. E ele disse: Farei conforme a tua palavra.","E disse ele: Jura-me. E ele jurou-lhe; e Israel inclinou-se sobre a cabeceira da cama."];
GENESIS_TEXT[48]=["E aconteceu pois depois destas coisas, que um disse a José: Eis que teu pai esta enfermo. Então tomou comsigo os seus dois filhos Manasseh e Ephraim.","E um deu parte a Jacó, e disse: Eis que José teu filho vem a ti. E esforçou-se Israel, e assentou-se sobre a cama.","E Jacó disse a José: O Deus Todo-poderoso me apareceu em Luz, na terra de Canaã, e me abençoou,","E me disse: Eis que te farei fructificar e multiplicar, e te porei por multidão de povos, e darei esta terra a tua semente depois de ti, em possessão perpetua.","Agora, pois, os teus dois filhos, que te nasceram na terra do Egito, antes que eu viesse a ti no Egito, são meus: Ephraim e Manasseh serão meus, como Ruben e Simeão;","Mas a tua geração, que geraràs depois deles, sera tua: segundo o nome de seus irmãos serão chamados na sua herança.","Vindo pois eu de Paddan, me morreu Raquel na terra de Canaã, no caminho, quando ainda ficava um pequeno espaço de terra para vir a Ephrata; e eu a sepultei ali, no caminho d'Ephrata, que é Beth-lehem.","E Israel viu os filhos de José, e disse: Quem são estes?","E José disse a seu pai: Eles são meus filhos, que Deus me tem dado aqui. E ele disse: Peço-te, traze-m'os aqui, para que os abençoe.","Os olhos porem d'Israel eram carregados de velhice, ja não podia ver; e fel-os chegar a ele, e beijou-os, e abraçou-os.","E Israel disse a José: Eu não cuidara ver o teu rosto; e eis que Deus me fez ver a tua semente também.","Então José os tirou de seus joelhos, e inclinou-se a terra diante da sua face.","E tomou José a ambos eles, a Ephraim na sua mão direita a esquerda d'Israel, e Manasseh na sua mão esquerda a direita d'Israel, e fel-os chegar a ele","Mas Israel estendeu a sua mão direita, e a pôs sobre a cabeça d'Ephraim, ainda que era o menor, e a sua esquerda sobre a cabeça de Manasseh, dirigindo as suas mãos avisadamente, ainda que Manasseh era o primogenito.","E abençoou a José, e disse: O Deus, em cuja presença andaram os meus pais Abraão e Isaac, o Deus que me sustentou, desde que eu nasci até este dia:","O anjo que me livrou de todo o mal, abençôe estes rapazes, e seja chamado nele o meu nome, e o nome de meus pais Abraão e Isaac, e multipliquem-se, como peixes, em multidão no meio da terra.","Vendo pois José que seu pai punha a sua mão direita sobre a cabeça d'Ephraim, foi mau aos seus olhos; e tomou a mão de seu pai, para a transpor de sobre a cabeça de Ephraim a cabeça de Manasseh.","E José disse a seu pai: Não assim, meu pai, porque este é o primogenito; põe a tua mão direita sobre a sua cabeça.","Mas seu pai o recusou, e disse: Eu o sei, filho meu, eu o sei: também ele sera um povo, e também ele sera grande: comtudo o seu irmão menor sera maior que ele, e a sua semente sera uma multidão de nações.","Assim os abençoou naquele dia, dizendo: Em ti abençoara Israel, dizendo: Deus te ponha como a Ephraim e como a Manasseh, E pôs a Ephraim diante de Manasseh.","Depois disse Israel a José: Eis que eu morro, mas Deus sera comvosco, e vos fara tornar a terra de vossos pais.","E eu te tenho dado a ti um pedaço da terra sobre teus irmãos, que tomei com a minha espada e com o meu arco da mão dos amorrheos."];
GENESIS_TEXT[49]=["Depois chamou Jacó a seus filhos, e disse: Ajuntae-vos, e annunciar-vos-hei o que vos ha de acontecer nos derradeiros dias:","Ajuntae-vos, e ouvi, filhos de Jacó; e ouvi a Israel vosso pai:","Ruben, tu és meu primogenito, minha força, e o principio de meu vigor, o mais excelente em alteza, e o mais excelente em potencia.","Fervente como a agua, não seràs o mais excelente; porquanto subiste ao leito de teu pai. Então o contaminaste; subiu a minha cama.","Simeão e Levi são irmãos: as suas espadas são instrumentos de violencia.","No seu secreto conselho não entre minha alma, com a sua congregação minha gloria não se ajunte; porque no seu furor mataram varões, e na sua teima arrebataram bois","Maldito seja o seu furor, pois era forte, e a sua ira, pois era dura: eu os dividirei em Jacó, e os espalharei em Israel.","Judah, te louvarão os teus irmãos; a tua mão sera sobre o pescoço de teus inimigos: os filhos de teu pai a ti se inclinarão.","Judah é um leãosinho, da preza subiste, filho meu: encurva-se, e deita-se como um leão, e como um leão velho: quem o despertara?","O cetro não se arredara de Judah, nem o legislador d'entre seus pés, até que não venha Shiloh; e a ele congregarão os povos","Ele amarrara o seu jumentinho a vide, e o filho da sua jumenta a cepa mais excelente: ele lavara o seu vestido no vinho, e a sua capa em sangue de uvas.","Os olhos serão vermelhos de vinho, e os dentes brancos de leite.","Zabulon habitara no porto dos mares, e sera porto dos navios, e o seu termo sera para Sidon.","Issacar é jumento de fortes ossos, deitado entre dois fardos.","E viu ele que o descanço era bom, e seu hombro para acarretar, e serviu debaixo de tributo.","Dan julgara o seu povo, como uma das tribus d'Israel.","Dan sera serpente junto ao caminho, uma vibora junto a vereda, que morde os calcanhares do cavalo, e faz cair o seu cavalleiro por detràs.","A tua salvação espero, ó Senhor!","Quanto a Gad, uma tropa o accommettera; mas ele a accommettera por fim.","De Aser, o seu pão sera gordo, e ele dara delicias reaes.","Naphtali é uma cerva solta: ele da palavras formosas.","José é um ramo fructifero, ramo fructifero junto a fonte; seus ramos correm sobre o muro.","Os frecheiros lhe deram amargura, e o frecharam e aborreceram.","O seu arco, porém, susteve-se no forte, e os braços de suas mãos foram fortalecidos pelas mãos do Valente de Jacó (d'onde é o pastor e a pedra d'Israel).","Pelo Deus de teu pai, o qual te ajudara, e pelo Todo-poderoso, o qual te abençoara com bençãos dos céus de cima, com bençãos do abysmo que esta debaixo, com bençãos dos peitos e da madre","As bençãos de teu pai excederão as bençãos de meus pais, até a extremidade dos outeiros eternos: elas estarão sobre a cabeça de José, e sobre o alto da cabeça do separado de seus irmãos.","Benjamin é lobo que despedaça; pela manhã comera a preza, e a tarde repartira o despojo.","Todas estas são as doze tribus de Israel: e isto é o que lhes falou seu pai quando os abençoou; a cada um deles abençoou segundo a sua benção.","Depois ordenou-lhes, e disse-lhes: Eu me congrego ao meu povo; sepultae-me com meus pais, na cova que esta no campo de Ephron, o hetheo,","Na cova que esta no campo de Machpela, que esta em frente de Mamre, na terra de Canaã, a qual Abraão comprou com aquele campo de Ephron, o hetheo, por herança de sepultura:","Ali sepultaram a Abraão, e a Sarah sua mulher: ali sepultaram a Isaac, e a Rebecca sua mulher: e ali eu sepultei a Lia.","O campo, e a cova que esta nele, foi comprado aos filhos de Heth.","Acabando pois Jacó de dar mandamentos a seus filhos, encolheu os seu pés na cama, e espirou, e foi congregado ao seu povo."];
GENESIS_TEXT[50]=["Então José se lançou sobre o rosto de seu pai; e chorou sobre ele, e o beijou.","E José ordenou aos seus servos, os medicos, que embalsamassem a seu pai: e os medicos embalsamaram a Israel.","E cumpriram-se-lhe quarenta dias; porque assim se cumprem os dias daqueles que se embalsamam: e os egípcios o choraram setenta dias.","Passados pois os dias de seu choro, falou José a casa de Faraó, dizendo: Se agora tenho achado graça aos vossos olhos, rogo-vos que falleis aos ouvidos de Faraó, dizendo:","Meu pai me fez jurar, dizendo: Eis que eu morro: em meu sepulchro, que cavei para mim na terra de Canaã, ali me sepultaràs. Agora pois, te peço, que eu suba, para que sepulte a meu pai; então voltarei.","E Faraó disse: Sobe, e sepulta a teu pai como ele te fez jurar.","E José subiu para sepultar a seu pai: e subiram com ele todos os servos de Faraó, os anciãos da sua casa, e todos os anciãos da terra do Egito,","Como também toda a casa de José, e seus irmãos, e a casa de seu pai: somente deixaram na terra de Gosen os seus meninos e as suas ovelhas, e as suas vacas.","E subiram também com ele, tanto carros como gente a cavalo; e o concurso foi grandissimo.","Chegando eles pois a planicie do espinhal, que esta além do Jordão, fizeram um grande e gravissimo pranto; e fez a seu pai um grande pranto por sete dias.","E vendo os moradores da terra, os cananeos, o luto na planicie do espinhal, disseram: É este o pranto grande dos egípcios. Por isso chamou-se o seu nome Abelmizraim, que esta além do Jordão.","E fizeram-lhe os seus filhos assim como ele lhes ordenara,","Pois os seus filhos o levaram a terra de Canaã, e o sepultaram na cova do campo de Machpela, que Abraão tinha comprado com o campo, por herança de sepultura, d'Ephron, o hetheo, em frente de Mamre.","Depois tornou-se José para o Egito, ele e seus irmãos, e todos os que com ele subiram a sepultar seu pai, depois de haver sepultado seu pai.","Vendo então os irmãos de José que seu pai ja estava morto, disseram: Porventura nos aborrecera José, e nos pagara certamente todo o mal que lhe fizemos.","Portanto enviaram a José, dizendo: Teu pai mandou, antes da sua morte, dizendo:","Assim direis a José: Perdoa, rogo-te, a transgressão de teus irmãos, e o seu peccado, porque te fizeram mal: agora pois rogamos-te que perdoes a transgressão dos servos do Deus de teu pai. E José chorou quando eles lhe fallavam.","Depois vieram também seus irmãos, e prostraram-se diante dele, e disseram: Eis-nos aqui por teus servos.","E José lhes disse: Não temaes, porque porventura estou eu em lugar de Deus?","Vós bem intentastes mal contra mim, porém Deus o intentou para bem, para fazer como esta n'este dia, para conservar em vida a um povo grande:","Agora pois não temaes: eu vos sustentarei a vós e a vossos meninos. Assim os consolou, e falou segundo o coração deles.","José pois habitou no Egito, ele e a casa de seu pai: e viveu José cento e dez anos,","E viu José os filhos de Ephraim, da terceira geração: também os filhos de Machir, filho de Manasseh, nasceram sobre os joelhos de José.","E disse José a seus irmãos: Eu morro; mas Deus certamente vos visitara, e vos fara subir desta terra a terra que jurou a Abraão, a Isaac e a Jacó","E José fez jurar os filhos de Israel, dizendo: Certamente vos visitara Deus, e fareis transportar os meus ossos daqui.","E morreu José da idade de cento e dez anos; e o embalsamaram, e o pôseram num caixão no Egito."];

const GENESIS_NOTES={"4":{"summary":"Gênesis 4 apresenta o nascimento de Caim e Abel, as ofertas dos dois irmãos, o assassinato de Abel e o confronto de Caim com Deus. A narrativa acompanha as consequências da violência, a proteção que Deus estabelece sobre Caim, a formação de uma linhagem associada à vida urbana e a diferentes ofícios, a escalada da vingança na fala de Lameque e, por fim, o nascimento de Sete e Enos.","explanation":"O capítulo mostra o pecado avançando para além do jardim: a ruptura com Deus aparece agora na relação entre irmãos. O texto não declara explicitamente que a oferta de Caim foi rejeitada por ser vegetal, nem explica todos os critérios da aceitação; Hebreus 11:4 e 1 João 3:12 destacam a fé e as obras de Abel e a maldade de Caim. A advertência de Gênesis 4:7 personifica o pecado como algo à espreita, cujo impulso precisa ser dominado. O sangue de Abel clama do solo, ressaltando que a violência não fica oculta diante de Deus. Mesmo ao julgar Caim, Deus impede que ele seja morto por vingança. A genealogia registra desenvolvimento cultural e técnico, mas a fala de Lameque revela também a multiplicação da violência. O capítulo termina com Sete e Enos, vinculando a continuidade da família humana à invocação do nome de YHWH.","episodes":"1. Nascimento de Caim e Abel (4:1-2)\n2. As ofertas dos irmãos e a reação de Caim (4:3-7)\n3. Caim mata Abel (4:8)\n4. Deus confronta Caim e anuncia as consequências (4:9-12)\n5. O sinal de proteção e a saída de Caim (4:13-16)\n6. A descendência de Caim e o desenvolvimento de ofícios (4:17-22)\n7. O cântico de Lameque e a vingança ampliada (4:23-24)\n8. Nascimento de Sete e Enos; invocação do nome de YHWH (4:25-26)","refs":"Gn 3:17-19; Gn 4:7; Gn 4:10-12; Gn 4:15; Gn 4:23-26; Hb 11:4; 1Jo 3:11-12; Jd 1:11","characters":[["Adão","Pai de Caim, Abel e, posteriormente, Sete; aparece como pai da linhagem humana. (Gn 4:1-2, 25)"],["Eva","Mãe de Caim, Abel e Sete. Ao nomear Caim e Sete, expressa sua percepção do auxílio e da dádiva de Deus. (Gn 4:1-2, 25)"],["Caim","Agricultor, irmão mais velho de Abel. Sua oferta não recebe a mesma atenção que a de Abel; tomado pela ira, mata o irmão e é confrontado e julgado por Deus. (Gn 4:2-16)"],["Abel","Pastor de ovelhas que oferece primícias do rebanho. É morto por Caim, e seu sangue clama desde o solo. (Gn 4:2-10)"],["YHWH Deus","Recebe as ofertas, adverte Caim, ouve o clamor do sangue de Abel e coloca um sinal de proteção sobre Caim. (Gn 4:4-15)"],["Mulher de Caim","É mencionada no relato do nascimento de Enoque; sua origem não é explicada neste capítulo. (Gn 4:17)"],["Enoque","Filho de Caim; seu nome é dado também à cidade que Caim constrói. (Gn 4:17-18)"],["Lameque","Descendente de Caim que toma duas mulheres e pronuncia um cântico de vingança, intensificando o tema da violência. (Gn 4:18-24)"],["Ada e Zilá","Mulheres de Lameque. Ada é mãe de Jabal e Jubal; Zilá é mãe de Tubalcaim e Naamá. (Gn 4:19-22)"],["Jabal","Descendente de Caim associado aos que vivem em tendas e criam rebanhos. (Gn 4:20)"],["Jubal","Descendente de Caim associado aos músicos que tocam lira e flauta. (Gn 4:21)"],["Tubalcaim","Artífice que trabalha com instrumentos de bronze e ferro. (Gn 4:22)"],["Naamá","Irmã de Tubalcaim, mencionada na genealogia. (Gn 4:22)"],["Sete","Filho de Adão e Eva, nascido após a morte de Abel; é apresentado como outra descendência concedida por Deus. (Gn 4:25)"],["Enos","Filho de Sete; em seu tempo, o texto registra o início da invocação do nome de YHWH. (Gn 4:26)"]],"symbols":[["Oferta / oblação","As ofertas de Caim e Abel são apresentadas de modo contrastante. O texto destaca a atenção divina a Abel e sua oferta, mas não afirma que produtos agrícolas fossem, por natureza, ofertas inferiores. (Gn 4:3-5)"],["Primícias e gordura","Abel oferece as primeiras crias do rebanho e sua gordura, indicando a porção selecionada de sua produção. (Gn 4:4)"],["Rosto abatido","Expressão visível da ira e do abatimento de Caim após a não aceitação de sua oferta. (Gn 4:5-6)"],["Pecado à porta","O pecado é descrito como algo à espreita, com desejo de dominar; Caim é chamado a dominá-lo. (Gn 4:7)"],["Sangue que clama","O sangue de Abel representa, na linguagem da narrativa, a violência que testemunha diante de Deus e exige resposta. (Gn 4:10)"],["Solo / terra","O solo recebe o sangue de Abel e deixa de dar sua força a Caim; a relação entre humanidade e terra, já afetada em Gn 3, é aprofundada. (Gn 4:10-12)"],["Errante e fugitivo","Condição de instabilidade e afastamento da terra e da presença de YHWH imposta a Caim. (Gn 4:12-16)"],["Sinal de Caim","Sinal dado por Deus para impedir que Caim seja morto por quem o encontrasse. O texto não descreve sua aparência nem identifica sua forma. (Gn 4:15)"],["Cidade de Enoque","A cidade construída por Caim recebe o nome de seu filho; o texto associa a linhagem a formas de organização urbana. (Gn 4:17)"],["Tendas e rebanhos","A atividade de Jabal é associada à vida pastoril e móvel. (Gn 4:20)"],["Lira e flauta","Instrumentos musicais associados a Jubal e ao desenvolvimento da música. (Gn 4:21)"],["Bronze e ferro","Materiais ligados ao trabalho metalúrgico de Tubalcaim. (Gn 4:22)"],["Sete","Seu nome é associado por Eva à ideia de alguém concedido por Deus no lugar de Abel; o texto faz dele um marco de continuidade familiar. (Gn 4:25)"],["Invocar o nome de YHWH","Expressão associada ao início de uma prática pública ou comunitária de invocação do nome divino. (Gn 4:26)"]]},"5":{"summary":"Registro da descendência de Adão. O capítulo relembra a criação do ser humano como macho e fêmea e a bênção recebida. Em seguida, registra Adão, Sete, Enos, Quenã, Maalalel, Jarede, Enoque, Metusalém, Lameque e Noé, com idades, descendentes e tempo de vida. Enoque é descrito como alguém que andou com Deus e foi tomado por Deus. O capítulo termina mencionando Sem, Cam e Jafé.","explanation":"O texto apresenta uma genealogia e informa a idade de cada homem ao gerar o descendente mencionado, os anos vividos depois disso, a existência de outros filhos e filhas e o total de seus dias. A expressão “e morreu” aparece repetidamente. No registro de Enoque, o texto diz que ele andou com Deus e que Deus o tomou, sem empregar a fórmula usada nos demais registros. Lameque explica o nome Noé relacionando-o ao descanso em face do trabalho e do solo que YHWH amaldiçoou.","episodes":"1. Registro da descendência de Adão e lembrança da criação (5:1-2)\n2. Adão gera Sete (5:3-5)\n3. Descendência de Sete: Enos e Quenã (5:6-14)\n4. Descendência de Quenã: Maalalel e Jarede (5:12-20)\n5. Enoque gera Metusalém e anda com Deus (5:21-24)\n6. Metusalém gera Lameque (5:25-27)\n7. Lameque gera Noé e explica seu nome (5:28-31)\n8. Os filhos de Noé: Sem, Cam e Jafé (5:32)","refs":"Gn 1:26-28; Gn 4:25-26; Gn 5:1-32; Lc 3:36-38; Hb 11:5; Jd 1:14-15","characters":[["Adão","Primeiro homem mencionado na genealogia; viveu 930 anos e gerou Sete, além de outros filhos e filhas. (Gn 5:1-5)"],["Sete","Filho de Adão; gerou Enos aos 105 anos e viveu 912 anos. (Gn 5:3-8)"],["Enos","Filho de Sete; gerou Quenã aos 90 anos e viveu 905 anos. (Gn 5:6-11)"],["Quenã","Filho de Enos; gerou Maalalel aos 70 anos e viveu 910 anos. (Gn 5:9-14)"],["Maalalel","Filho de Quenã; gerou Jarede aos 65 anos e viveu 895 anos. (Gn 5:12-17)"],["Jarede","Filho de Maalalel; gerou Enoque aos 162 anos e viveu 962 anos. (Gn 5:15-20)"],["Enoque","Filho de Jarede; gerou Metusalém aos 65 anos. O texto diz que andou com Deus e que Deus o tomou. Seus dias foram 365 anos. (Gn 5:18-24)"],["Metusalém","Filho de Enoque; gerou Lameque aos 187 anos e viveu 969 anos. (Gn 5:21-27)"],["Lameque","Filho de Metusalém; gerou Noé aos 182 anos e viveu 777 anos. Ao nomear Noé, fala sobre descanso em relação ao trabalho e ao solo. (Gn 5:25-31)"],["Noé","Filho de Lameque; aos 500 anos, gerou Sem, Cam e Jafé. (Gn 5:28-32)"],["Sem","Filho de Noé, mencionado no encerramento do capítulo. (Gn 5:32)"],["Cam","Filho de Noé, mencionado no encerramento do capítulo. (Gn 5:32)"],["Jafé","Filho de Noé, mencionado no encerramento do capítulo. (Gn 5:32)"],["Deus","É mencionado como criador do ser humano e como aquele que tomou Enoque. (Gn 5:1-2, 24)"]],"symbols":[["Registro da descendência","Título e estrutura genealógica que introduzem a lista dos descendentes de Adão. (Gn 5:1)"],["Imagem e semelhança","O texto declara que Deus criou o ser humano à sua semelhança e que Adão gerou Sete conforme sua imagem. (Gn 5:1-3)"],["Bênção","O texto registra que Deus abençoou o homem e a mulher. (Gn 5:2)"],["Idades e anos","Os números registram a idade de cada homem ao gerar o descendente citado, os anos vividos depois e o total de seus dias. (Gn 5:3-32)"],["“E morreu”","Fórmula repetida no encerramento de vários registros genealógicos. (Gn 5:5, 8, 11, 14, 17, 20, 27, 31)"],["Andar com Deus","Expressão usada para descrever Enoque. (Gn 5:22, 24)"],["Deus o tomou","Declaração do texto sobre Enoque; o capítulo não detalha o modo como isso ocorreu. (Gn 5:24)"],["Nome Noé","Lameque relaciona o nome de seu filho à expectativa de descanso do trabalho e do esforço das mãos por causa do solo amaldiçoado. (Gn 5:29)"],["Solo amaldiçoado","Referência de Lameque à declaração anterior sobre o solo. (Gn 3:17; 5:29)"]]}};
const GENESIS_DETAILS={
1:{
characters:[["YHWH Deus","Criador que chama à existência os céus, a terra e todos os seres vivos. (Gn 1:1-31)"],["O ser humano","Criado à imagem e semelhança de Deus, macho e fêmea, recebe a responsabilidade de povoar e cuidar da terra. (Gn 1:26-28)"],["Animais marinhos","Seres vivos criados por Deus nas águas e abençoados para se multiplicarem. (Gn 1:20-22)"],["Aves","Criaturas aladas criadas para voar sobre a terra e sob a expansão dos céus. (Gn 1:20-22)"],["Animais terrestres","Animais domésticos, selvagens e os que rastejam, criados segundo suas espécies. (Gn 1:24-25)"]],
symbols:[["Luz","Primeira ordem criadora narrada; é separada da escuridão e recebe o nome de Dia. (Gn 1:3-5)"],["Escuridão","Condição sobre a face do abismo antes da separação entre dia e noite. (Gn 1:2-5)"],["Águas e abismo","Elementos da cena inicial sobre a qual o sopro de Deus paira. (Gn 1:2)"],["Expansão / céus","Espaço estabelecido para separar águas e chamado Céus. (Gn 1:6-8)"],["Terra seca e mares","A reunião das águas permite que a porção seca apareça e receba o nome Terra. (Gn 1:9-10)"],["Vegetação e sementes","Sinal de fecundidade e continuidade da vida segundo as espécies. (Gn 1:11-13, 29-30)"],["Sol, lua e estrelas","Luminares que marcam dia, noite, sinais e tempos determinados. (Gn 1:14-18)"],["Imagem de Deus","Expressão da dignidade e da vocação representativa do ser humano na criação. (Gn 1:26-27)"],["Bênção e fecundidade","Palavra divina que concede aos seres vivos a capacidade de se multiplicar. (Gn 1:22, 28)"]]
},
2:{
characters:[["YHWH Deus","Criador que forma o ser humano, planta o jardim, dá a ordem e providencia a mulher como companheira. (Gn 2:4-22)"],["Adão / o ser humano","Formado do pó, recebe o fôlego de vida, é colocado no jardim para cultivá-lo e guardá-lo e dá nomes aos animais. (Gn 2:7, 15, 19-20)"],["A mulher","Formada a partir do lado do homem e apresentada como correspondente a ele; neste capítulo ainda não recebe o nome Eva. (Gn 2:18-23)"]],
symbols:[["Pó do solo","Recorda a origem terrena e a condição mortal do ser humano. (Gn 2:7)"],["Fôlego de vida","Imagem da vida recebida de Deus; o texto diz que o ser humano se tornou um ser vivente. (Gn 2:7)"],["Jardim do Éden","Lugar de vida, provisão, comunhão e responsabilidade confiada ao ser humano. (Gn 2:8-15)"],["Árvore da vida","Árvore associada à vida no jardim. (Gn 2:9)"],["Árvore do conhecimento do bem e do mal","Marca o limite estabelecido por Deus e a responsabilidade diante de sua ordem. (Gn 2:9, 16-17)"],["Rio e quatro braços","Imagem da água que irriga e sustenta o jardim. (Gn 2:10-14)"],["Uma só carne","Expressão da união profunda do homem e da mulher no vínculo matrimonial. (Gn 2:24)"]]
},
3:{
characters:[["YHWH Deus","Interroga o casal, pronuncia as consequências da transgressão, veste o homem e a mulher e os retira do jardim. (Gn 3:8-24)"],["A serpente","Animal astuto que questiona a ordem divina, contradiz a advertência e engana a mulher. (Gn 3:1-5, 13-15)"],["A mulher / Eva","Dialoga com a serpente, come do fruto e o oferece ao marido; depois é chamada Eva. (Gn 3:1-6, 20)"],["O homem / Adão","Come do fruto, reconhece que se escondeu e responde à pergunta de Deus. (Gn 3:6-12, 17-19)"],["Querubins","Seres colocados a leste do Éden para guardar o caminho da árvore da vida. (Gn 3:24)"]],
symbols:[["Serpente","No enredo, representa a astúcia enganadora e a oposição à palavra divina. (Gn 3:1-5)"],["Fruto da árvore","O fruto não é identificado por espécie; na narrativa, torna-se o objeto da desobediência. (Gn 3:3-6)"],["Olhos abertos","Expressão da nova percepção após comerem; vem acompanhada da consciência da nudez e do medo. (Gn 3:7)"],["Folhas de figueira","Tentativa humana de cobrir a própria nudez. (Gn 3:7)"],["Nudez e vergonha","A nudez antes sem vergonha (Gn 2:25) passa a ser percebida com medo e constrangimento. (Gn 3:7-11)"],["Voz de Deus no jardim","A presença divina que chama o ser humano a responder por seus atos. (Gn 3:8-10)"],["Vestimentas de pele","Provisão de Deus para cobrir o homem e a mulher após a transgressão. (Gn 3:21)"],["Pó e suor","Sinais da mortalidade e do trabalho penoso associados à vida fora do jardim. (Gn 3:17-19)"],["Espinhos e cardos","Representam a resistência e a dificuldade que passam a marcar o cultivo do solo. (Gn 3:18)"],["Descendência, cabeça e calcanhar","Imagem de inimizade e conflito entre a serpente e a descendência da mulher; interpretações posteriores variam entre tradições. (Gn 3:15)"],["Querubins e espada flamejante","Guardam o caminho da árvore da vida e marcam a expulsão do jardim. (Gn 3:24)"],["Leste do Éden","Direção para a qual o casal é enviado e onde fica a guarda do caminho da árvore da vida. (Gn 3:23-24)"]]}
};
GENESIS_NOTES[6]={"summary":"O capítulo relata a multiplicação dos seres humanos, a menção aos filhos de Deus, às filhas dos seres humanos e aos nefilins. O texto descreve a maldade, a corrupção e a violência na terra. Deus anuncia que eliminará os seres vivos da terra, mas Noé encontra favor diante de YHWH. Noé é apresentado como justo e íntegro entre os de sua geração e como alguém que andava com Deus. Deus lhe ordena construir uma arca, fornece suas medidas e instruções, anuncia o dilúvio e estabelece uma aliança com ele.","explanation":"O capítulo começa com referências aos filhos de Deus, às filhas dos seres humanos e aos nefilins, sem explicar detalhadamente a identidade desses grupos. Em seguida, o narrador descreve a avaliação divina sobre a maldade humana e a condição da terra, caracterizada por corrupção e violência. Noé é destacado no relato. A partir de 6:13, o texto registra as instruções para a construção da arca: material, compartimentos, revestimento, medidas, abertura, porta e andares. Também apresenta quem entraria na arca e a provisão de alimento. O capítulo termina afirmando que Noé fez conforme tudo o que Deus lhe ordenou.","episodes":"1. Multiplicação dos seres humanos e nascimento de filhas (6:1)\n2. Os filhos de Deus tomam mulheres entre as filhas dos seres humanos (6:2-4)\n3. A avaliação de YHWH sobre a maldade humana (6:5-7)\n4. Noé encontra favor diante de YHWH (6:8)\n5. Noé é apresentado e seus três filhos são nomeados (6:9-10)\n6. Corrupção e violência na terra (6:11-12)\n7. Anúncio do fim de toda carne e instruções para a arca (6:13-16)\n8. Anúncio do dilúvio e estabelecimento da aliança (6:17-18)\n9. Entrada dos animais e armazenamento de alimento (6:19-21)\n10. Noé faz conforme a ordem recebida (6:22)","refs":"Gn 5:28-32; Gn 6:1-22; Gn 7:1-5; Mt 24:37-39; Lc 17:26-27; Hb 11:7; 1Pe 3:20; 2Pe 2:5","characters":[["YHWH / Deus","Fala sobre a permanência de seu espírito no ser humano, avalia a maldade da humanidade, anuncia o dilúvio e dá instruções a Noé. (Gn 6:3, 5-7, 13-21)"],["Filhos de Deus","Grupo mencionado no relato que vê as filhas dos seres humanos e toma mulheres dentre elas. O capítulo não detalha sua identidade. (Gn 6:2, 4)"],["Filhas dos seres humanos","Mulheres vistas pelos filhos de Deus, que as tomam como mulheres. (Gn 6:1-2, 4)"],["Nefilins","São mencionados como presentes na terra naqueles dias e também depois; o texto os associa aos valentes da antiguidade, homens de renome. (Gn 6:4)"],["Noé","Encontra favor diante de YHWH, é descrito como justo e íntegro entre os de sua geração, recebe as instruções da arca e as cumpre. (Gn 6:8-22)"],["Sem","Um dos três filhos de Noé. (Gn 6:10, 18)"],["Cam","Um dos três filhos de Noé. (Gn 6:10, 18)"],["Jafé","Um dos três filhos de Noé. (Gn 6:10, 18)"],["Humanidade","É descrita como multiplicada na terra, marcada pela maldade e pela corrupção de seu caminho. (Gn 6:1-7, 11-13)"]],"symbols":[["Filhos de Deus e filhas dos seres humanos","Expressões usadas pelo texto para identificar os grupos mencionados no início do capítulo; suas identidades não são explicadas ali. (Gn 6:1-4)"],["Nefilins","Nome atribuído a seres mencionados na terra naquele período; o texto também os relaciona aos valentes da antiguidade e homens de renome. (Gn 6:4)"],["Cento e vinte anos","Período mencionado na declaração de YHWH sobre os dias do ser humano. (Gn 6:3)"],["Coração e pensamentos","Linguagem usada para descrever a inclinação dos pensamentos humanos como continuamente má. (Gn 6:5)"],["Corrupção","Condição atribuída à terra e ao caminho de toda a humanidade. (Gn 6:11-12)"],["Violência","Característica destacada como presente e abundante na terra. (Gn 6:11, 13)"],["Favor diante de YHWH","Expressão usada para descrever a condição de Noé diante de YHWH. (Gn 6:8)"],["Arca","Construção ordenada a Noé para preservar sua família e representantes dos seres vivos durante o dilúvio. (Gn 6:14-21)"],["Madeira de gofer","Material indicado para a construção da arca. (Gn 6:14)"],["Betume","Material indicado para revestir a arca por dentro e por fora. (Gn 6:14)"],["Abertura e porta lateral","Elementos estruturais especificados nas instruções para a arca. (Gn 6:16)"],["Três andares","Organização interna indicada para a arca: inferior, segundo e terceiro. (Gn 6:16)"],["Dilúvio de águas","Evento anunciado por Deus para destruir toda carne em que há fôlego de vida debaixo dos céus. (Gn 6:17)"],["Aliança","Compromisso anunciado por Deus a Noé, que entraria na arca com sua família. (Gn 6:18)"],["Macho e fêmea","Distinção indicada para os pares de seres vivos que seriam conservados na arca. (Gn 6:19-20)"],["Alimento armazenado","Provisão que Noé deveria reunir para si e para os animais. (Gn 6:21)"]]};
GENESIS_NOTES[7]={"summary":"YHWH ordena que Noé entre na arca com sua família e leve consigo os animais, distinguindo os animais puros dos que não eram puros e indicando também os pares de aves. Após sete dias, começa o dilúvio. O texto informa a idade de Noé, a data do início das águas, a chuva de quarenta dias e quarenta noites, a abertura das fontes do grande abismo e das comportas dos céus. As águas cobrem as montanhas, os seres vivos que estavam fora da arca morrem, e Noé permanece na arca com os que entraram com ele. O capítulo termina informando que as águas prevaleceram por cento e cinquenta dias.","explanation":"O capítulo dá continuidade às instruções de Gênesis 6 e narra sua execução. São mencionados sete pares de animais puros, um par dos animais que não eram puros e sete pares de aves. A entrada na arca ocorre antes do início das águas; o texto menciona um intervalo de sete dias. A data é situada no ano seiscentos da vida de Noé, no segundo mês, dia dezessete. A narrativa descreve duas origens das águas: as fontes do grande abismo e as comportas dos céus. A chuva dura quarenta dias e quarenta noites. O relato enfatiza a elevação das águas, a cobertura das montanhas e a morte dos seres que estavam fora da arca. Noé, sua família e os seres vivos que estavam com eles permanecem dentro da arca.","episodes":"1. Ordem para Noé entrar na arca com sua casa (7:1)\n2. Instruções sobre os animais puros, os que não eram puros e as aves (7:2-3)\n3. Anúncio da chuva após sete dias (7:4)\n4. Noé cumpre a ordem de YHWH (7:5)\n5. Noé, aos seiscentos anos, entra na arca com sua família (7:6-9)\n6. Início do dilúvio após sete dias (7:10)\n7. Data do início do dilúvio e abertura das fontes e comportas dos céus (7:11-12)\n8. Entrada de Noé, sua família e os animais na arca (7:13-16)\n9. A arca é levantada pelas águas e as montanhas ficam cobertas (7:17-20)\n10. Morte dos seres vivos que estavam fora da arca (7:21-23)\n11. As águas prevalecem durante cento e cinquenta dias (7:24)","refs":"Gn 6:13-22; Gn 7:1-24; Gn 8:1-5; Mt 24:37-39; Lc 17:26-27; Hb 11:7; 1Pe 3:20; 2Pe 2:5","characters":[["YHWH","Ordena a entrada de Noé na arca, anuncia a chuva e fecha a porta da arca. (Gn 7:1-4, 16)"],["Noé","Entra na arca com sua família e os animais, seguindo as instruções recebidas. (Gn 7:1-16)"],["Sem","Filho de Noé; entra na arca com sua mulher. (Gn 7:7, 13)"],["Cam","Filho de Noé; entra na arca com sua mulher. (Gn 7:7, 13)"],["Jafé","Filho de Noé; entra na arca com sua mulher. (Gn 7:7, 13)"],["Mulher de Noé","Entra na arca com Noé. (Gn 7:7, 13)"],["Mulheres dos filhos de Noé","As três mulheres dos filhos de Noé entram na arca com eles. (Gn 7:7, 13)"],["Seres humanos e animais","Os seres vivos que estavam fora da arca são atingidos pelas águas; os que entraram com Noé permanecem na arca. (Gn 7:14-23)"]],"symbols":[["Arca","Embarcação na qual Noé, sua família e os animais entram e permanecem durante o dilúvio. (Gn 7:1, 7-9, 13-18)"],["Animais puros","Categoria de animais para os quais são indicados sete pares, macho e fêmea. (Gn 7:2, 8)"],["Animais que não eram puros","Categoria de animais para os quais é indicado um par, macho e fêmea. (Gn 7:2, 8)"],["Aves dos céus","As aves são mencionadas com sete pares para conservar sua descendência sobre a terra. (Gn 7:3, 14)"],["Sete dias","Intervalo anunciado antes de as águas do dilúvio virem sobre a terra. (Gn 7:4, 10)"],["Quarenta dias e quarenta noites","Duração da chuva sobre a terra. (Gn 7:4, 12)"],["Seiscentos anos de Noé","Idade de Noé quando veio o dilúvio de águas. (Gn 7:6, 11)"],["Segundo mês, dia dezessete","Data indicada para o início do dilúvio no relato. (Gn 7:11)"],["Fontes do grande abismo","Fontes que se rompem no dia em que começa o dilúvio. (Gn 7:11)"],["Comportas dos céus","Aberturas dos céus mencionadas junto ao rompimento das fontes do grande abismo. (Gn 7:11)"],["Porta da arca","O texto declara que YHWH fechou a porta atrás de Noé. (Gn 7:16)"],["Montanhas cobertas","As altas montanhas debaixo dos céus ficam cobertas pelas águas. (Gn 7:19-20)"],["Fôlego de vida","Expressão usada para descrever os seres que morreram nas águas quando estavam fora da arca. (Gn 7:21-22)"],["Cento e cinquenta dias","Período durante o qual as águas prevaleceram sobre a terra. (Gn 7:24)"]]};
GENESIS_NOTES[10]={"summary":"Gênesis 10 apresenta a descendência dos filhos de Noé — Jafé, Cam e Sem — e relaciona seus descendentes, clãs, línguas, territórios e nações. O capítulo menciona a expansão das populações pelas terras e destaca Ninrode, associado ao início de um reino cuja primeira referência é Babel, na terra de Sinear. Também registra a linhagem de Canaã e a descendência de Héber, incluindo a observação sobre Pelegue e a divisão da terra.","explanation":"O capítulo está organizado em três seções genealógicas: os descendentes de Jafé (10:2-5), os descendentes de Cam (10:6-20) e os descendentes de Sem (10:21-31). As listas relacionam famílias, línguas, terras e nações depois do dilúvio. Na seção de Cam, o texto destaca Ninrode e cidades associadas ao início de seu reino, além de povos ligados a Mizraim e Canaã. Na seção de Sem, aparecem Héber, Pelegue e Joctã e seus descendentes. O texto não fornece explicações adicionais para todos os nomes e localidades.","episodes":"1. Introdução aos filhos de Noé e seus descendentes (10:1)\n2. Descendentes de Jafé (10:2-5)\n3. Descendentes de Cam (10:6-7)\n4. Ninrode e sua descrição (10:8-9)\n5. Cidades do princípio do reino de Ninrode (10:10-12)\n6. Descendentes de Mizraim (10:13-14)\n7. Descendentes de Canaã e seus territórios (10:15-19)\n8. Resumo dos descendentes de Cam (10:20)\n9. Introdução aos descendentes de Sem (10:21)\n10. Filhos de Sem e descendentes de Arã (10:22-23)\n11. Linha de Arfaxade, Selá e Héber (10:24)\n12. Pelegue e Joctã (10:25)\n13. Descendentes de Joctã e região de habitação (10:26-30)\n14. Resumo dos descendentes de Sem e conclusão (10:31-32)","refs":"Gn 5:32; Gn 9:18-19; Gn 10:1-32; Gn 11:1-9, 10-32; 1Cr 1:5-23; Lc 3:34-36","characters":[["Noé","Pai de Sem, Cam e Jafé; seus descendentes são apresentados como origem das famílias e nações mencionadas depois do dilúvio. (Gn 9:18-19; 10:1)"],["Jafé","Um dos filhos de Noé. Seus descendentes relacionados incluem Gômer, Magogue, Madai, Javã, Tubal, Meseque e Tirás. (Gn 10:1-5)"],["Cam","Um dos filhos de Noé. Seus filhos nomeados são Cuxe, Mizraim, Pute e Canaã. (Gn 10:1, 6-20)"],["Sem","Um dos filhos de Noé, identificado como pai de todos os filhos de Héber e irmão mais velho de Jafé. (Gn 10:1, 21-31)"],["Ninrode","Descendente de Cuxe, descrito como poderoso na terra e poderoso caçador diante de YHWH. O texto relaciona a ele o princípio de um reino. (Gn 10:8-12)"],["Cuxe","Filho de Cam e pai de vários descendentes, entre eles Ninrode e os filhos de Raamá. (Gn 10:6-8)"],["Mizraim","Filho de Cam; seus descendentes são associados aos luditas, anamitas, leabitas, naftuítas, patrusitas, casluítas e caftoritas. (Gn 10:6, 13-14)"],["Canaã","Filho de Cam; seus descendentes incluem Sidom, Hete e diversos povos cananeus. (Gn 10:6, 15-19)"],["Raamá","Descendente de Cuxe e pai de Sabá e Dedã. (Gn 10:7)"],["Héber","Descendente de Sem, por meio de Arfaxade e Selá; pai de Pelegue e Joctã. (Gn 10:24-25)"],["Pelegue","Filho de Héber; o texto relaciona seu nome ao fato de que, em seus dias, a terra foi dividida. (Gn 10:25)"],["Joctã","Filho de Héber e pai dos descendentes enumerados em Gênesis 10:26-29. (Gn 10:25-29)"]],"symbols":[["Genealogias / gerações","Estrutura usada para registrar a descendência dos filhos de Noé e a formação de clãs e nações. (Gn 10:1, 32)"],["Clãs","Grupos de descendência mencionados na organização das genealogias. (Gn 10:5, 18, 20, 31-32)"],["Línguas","Categoria usada para descrever a distribuição dos povos. (Gn 10:5, 20, 31)"],["Terras e nações","Categorias usadas para registrar a distribuição dos descendentes em diferentes regiões e povos. (Gn 10:5, 20, 31-32)"],["Terras costeiras","Regiões associadas aos descendentes de Jafé. (Gn 10:5)"],["Babel e Sinear","Babel é indicada como uma das cidades do princípio do reino de Ninrode, situada na terra de Sinear. (Gn 10:10)"],["Reino de Ninrode","O texto lista Babel, Ereque, Acade e Calné como o princípio de seu reino e menciona cidades na Assíria. (Gn 10:10-12)"],["Nínive, Reobote-I, Calá e Resém","Cidades mencionadas na descrição da expansão para a Assíria. (Gn 10:11-12)"],["Sidom e Hete","Nomes apresentados como descendentes de Canaã; Sidom é identificado como seu primogênito. (Gn 10:15)"],["Território de Canaã","O texto descreve seus limites por meio de cidades e regiões, de Sidom até Gaza e em direção a Sodoma, Gomorra, Admá, Zeboim e Lasa. (Gn 10:19)"],["Pelegue e a divisão da terra","O texto associa os dias de Pelegue à divisão da terra, sem detalhar nesse versículo como ocorreu. (Gn 10:25)"],["Região de Joctã","Área descrita entre Messa, Sefar e a região montanhosa do Oriente. (Gn 10:30)"],["Depois do dilúvio","Referência temporal que situa a dispersão das nações na conclusão do capítulo. (Gn 10:32)"]]};
GENESIS_NOTES[9]={"summary":"Depois de saírem da arca, Deus abençoa Noé e seus filhos e lhes ordena que sejam fecundos e encham a terra. O capítulo registra orientações sobre os animais, o alimento e o sangue, além da declaração sobre a vida humana e a imagem de Deus. Deus estabelece uma aliança com Noé, seus descendentes e todos os seres vivos, e apresenta o arco nas nuvens como sinal dessa aliança. Na parte final, Noé planta uma vinha, bebe vinho e fica embriagado. Cam vê a nudez do pai e conta aos irmãos; Sem e Jafé cobrem Noé sem olhar para ele. Ao despertar, Noé pronuncia palavras sobre Canaã, Sem e Jafé. O capítulo termina com a idade e a morte de Noé.","explanation":"O capítulo começa com bênçãos e instruções dirigidas a Noé e seus filhos. O texto menciona a relação dos seres humanos com os animais, a permissão para comer seres que se movem e vivem, a proibição de comer carne com seu sangue e a prestação de contas pelo sangue humano. Em seguida, Deus declara a aliança com Noé, sua descendência e todos os seres vivos, afirmando que não haverá outro dilúvio para destruir toda carne. O arco nas nuvens é apresentado como sinal dessa aliança. A narrativa então passa à vida de Noé após o dilúvio: o cultivo da vinha, a embriaguez, o episódio envolvendo Cam, Sem e Jafé e as palavras pronunciadas por Noé sobre seus descendentes. O capítulo encerra com o registro dos trezentos e cinquenta anos vividos por Noé depois do dilúvio e sua idade total.","episodes":"1. Deus abençoa Noé e seus filhos e ordena que encham a terra (9:1)\n2. Declaração sobre os animais e a alimentação (9:2-3)\n3. Orientação sobre não comer carne com sangue (9:4)\n4. Declaração sobre a prestação de contas pelo sangue humano (9:5-6)\n5. Repetição da ordem de fecundidade e multiplicação (9:7)\n6. Deus anuncia a aliança com Noé, seus filhos e os seres vivos (9:8-11)\n7. O arco nas nuvens é apresentado como sinal da aliança (9:12-17)\n8. Identificação dos filhos de Noé e menção a Canaã (9:18-19)\n9. Noé planta uma vinha e se embriaga (9:20-21)\n10. Cam vê a nudez do pai e conta aos irmãos (9:22)\n11. Sem e Jafé cobrem Noé sem olhar para sua nudez (9:23)\n12. Noé pronuncia palavras sobre Canaã, Sem e Jafé (9:24-27)\n13. Idade e morte de Noé (9:28-29)","refs":"Gn 1:26-28; Gn 6:18; Gn 8:20-22; Gn 9:1-29; Gn 10:1-32; Is 54:9; Ez 14:14, 20; Mt 24:37-39; Lc 17:26-27; 1Pe 3:20; 2Pe 2:5","characters":[["Deus","Abençoa Noé e seus filhos, dá instruções sobre a vida e o sangue, estabelece a aliança e apresenta o arco como sinal. (Gn 9:1-17)"],["Noé","Recebe as palavras de Deus, planta uma vinha, bebe vinho, fica embriagado e pronuncia palavras sobre Canaã, Sem e Jafé. (Gn 9:1-29)"],["Sem","Filho de Noé; junto com Jafé, cobre a nudez do pai sem olhar para ele. (Gn 9:18, 23, 26)"],["Cam","Filho de Noé e pai de Canaã; vê a nudez do pai e conta aos dois irmãos. (Gn 9:18, 22)"],["Jafé","Filho de Noé; junto com Sem, cobre a nudez do pai. (Gn 9:18, 23, 27)"],["Canaã","Filho de Cam; é mencionado na declaração pronunciada por Noé. (Gn 9:18, 22, 25-27)"],["Descendentes de Noé","São incluídos na aliança anunciada por Deus e na ordem para se multiplicarem sobre a terra. (Gn 9:1, 8-10, 19)"],["Seres vivos","Aves, animais domésticos e animais da terra são incluídos na aliança. (Gn 9:10, 12, 15-16)"]],"symbols":[["Bênção","Deus abençoa Noé e seus filhos e lhes dirige a ordem de serem fecundos e se multiplicarem. (Gn 9:1, 7)"],["Temor dos animais","O texto declara que o temor e o medo dos seres humanos estarão sobre os animais da terra, as aves e os peixes. (Gn 9:2)"],["Alimento","Deus declara que tudo o que se move e vive servirá de alimento, assim como antes havia dado as plantas verdes. (Gn 9:3)"],["Sangue e vida","O texto proíbe comer carne com seu sangue e associa o sangue à vida. (Gn 9:4-5)"],["Imagem de Deus","A declaração sobre o ser humano feito à imagem de Deus aparece como fundamento apresentado no texto para a prestação de contas pelo sangue humano. (Gn 9:6)"],["Aliança","Compromisso estabelecido por Deus com Noé, seus descendentes e todo ser vivo, com a declaração de que não haverá outro dilúvio para destruir toda carne. (Gn 9:8-17)"],["Arco nas nuvens","Sinal da aliança entre Deus, a terra e todo ser vivo. (Gn 9:12-17)"],["Nuvens","O texto menciona a reunião de nuvens sobre a terra junto ao aparecimento do arco. (Gn 9:13-14)"],["Vinha","Plantação feita por Noé após o dilúvio. (Gn 9:20)"],["Vinho e embriaguez","Noé bebe do vinho da vinha, embriaga-se e fica descoberto dentro de sua tenda. (Gn 9:21, 24)"],["Tenda","Local em que Noé fica descoberto após se embriagar. (Gn 9:21)"],["Capa","Peça usada por Sem e Jafé para cobrir a nudez do pai. (Gn 9:23)"],["Nudez","O episódio descreve Cam vendo a nudez de Noé e Sem e Jafé cobrindo-a sem olhar. (Gn 9:22-23)"],["Servidão","Termo presente nas palavras de Noé a respeito de Canaã em relação aos irmãos. (Gn 9:25-27)"],["Tendas de Sem","Expressão que aparece na declaração de Noé sobre Jafé habitar nas tendas de Sem. (Gn 9:27)"],["Trezentos e cinquenta anos","Período que Noé viveu depois do dilúvio. (Gn 9:28)"],["Novecentos e cinquenta anos","Total dos dias de vida de Noé, segundo o registro do capítulo. (Gn 9:29)"]]};
GENESIS_NOTES[8]={"summary":"Deus lembra-se de Noé e dos seres vivos que estão com ele na arca, faz passar um vento sobre a terra e as águas começam a baixar. As fontes do abismo e as comportas dos céus são fechadas, e a chuva é detida. A arca repousa sobre os montes de Ararate. Noé envia um corvo e, em seguida, uma pomba em diferentes ocasiões; a pomba retorna primeiro sem encontrar lugar para pousar, depois traz uma folha nova de oliveira e, na terceira soltura, não retorna. O capítulo registra o secamento das águas e da terra, a ordem de Deus para sair da arca e a saída de Noé, sua família e os animais.","explanation":"O relato acompanha a diminuição das águas por etapas e registra datas específicas: o repouso da arca no sétimo mês, a aparição dos cumes dos montes no décimo mês, as solturas das aves e o secamento da superfície do solo no primeiro mês do ano seiscentos e um de Noé. A terra é declarada seca no segundo mês, dia vinte e sete. Deus então ordena que Noé e os demais saiam da arca. A ordem também determina que os animais saiam e se espalhem, sejam fecundos e se multipliquem. O capítulo termina com a saída de todos conforme suas famílias.","episodes":"1. Deus lembra-se de Noé e faz passar um vento sobre a terra (8:1)\n2. Fechamento das fontes e diminuição das águas (8:2-3)\n3. A arca repousa nos montes de Ararate (8:4)\n4. Aparecem os cumes dos montes (8:5)\n5. Noé abre a janela e solta um corvo (8:6-7)\n6. Primeira soltura da pomba e seu retorno à arca (8:8-9)\n7. Segunda soltura da pomba e retorno com uma folha de oliveira (8:10-11)\n8. Terceira soltura da pomba; ela não retorna (8:12)\n9. Secamento da superfície do solo e remoção da cobertura da arca (8:13)\n10. A terra fica seca e Deus ordena a saída (8:14-17)\n11. Noé, sua família e os animais saem da arca (8:18-19)","refs":"Gn 6:13-22; Gn 7:11-24; Gn 8:1-22; Gn 9:1-17; Is 54:9; Mt 24:37-39; Lc 17:26-27; Hb 11:7; 1Pe 3:20; 2Pe 2:5","characters":[["Deus","Lembra-se de Noé e dos seres vivos na arca, faz passar um vento sobre a terra e ordena a saída da arca. (Gn 8:1, 15-17)"],["Noé","Aguarda a diminuição das águas, envia o corvo e a pomba, observa o estado da terra e sai da arca quando recebe a ordem. (Gn 8:1-19)"],["Mulher de Noé","Sai da arca com Noé. (Gn 8:16, 18)"],["Sem","Filho de Noé; sai da arca com a família. (Gn 8:16, 18)"],["Cam","Filho de Noé; sai da arca com a família. (Gn 8:16, 18)"],["Jafé","Filho de Noé; sai da arca com a família. (Gn 8:16, 18)"],["Mulheres dos filhos de Noé","Saem da arca com Noé e seus filhos. (Gn 8:16, 18)"],["Corvo","Ave solta por Noé; sai e volta repetidamente até que as águas secam de sobre a terra. (Gn 8:7)"],["Pomba","Ave solta por Noé em três ocasiões; retorna na primeira, volta com uma folha de oliveira na segunda e não retorna na terceira. (Gn 8:8-12)"],["Animais da arca","Saem da arca segundo suas famílias, conforme a ordem dada a Noé. (Gn 8:17-19)"]],"symbols":[["Vento","Deus faz passar um vento sobre a terra, e as águas baixam. (Gn 8:1)"],["Fontes do abismo","São fechadas no processo de diminuição das águas. (Gn 8:2)"],["Comportas dos céus","São fechadas, e a chuva dos céus é detida. (Gn 8:2)"],["Cento e cinquenta dias","Período mencionado antes de as águas diminuírem, em continuidade ao registro do capítulo anterior. (Gn 7:24; 8:3)"],["Montes de Ararate","Local onde a arca repousa no sétimo mês, no dia dezessete. (Gn 8:4)"],["Janela da arca","Abertura feita por Noé, usada para soltar as aves. (Gn 8:6-8)"],["Corvo","Ave enviada por Noé para observar a condição das águas; o texto diz que ia e voltava. (Gn 8:7)"],["Pomba","Ave enviada por Noé em três ocasiões para verificar se as águas haviam diminuído. (Gn 8:8-12)"],["Folha nova de oliveira","Folha trazida pela pomba no bico, indicando no próprio relato que as águas haviam diminuído. (Gn 8:11)"],["Cobertura da arca","Noé a remove quando a superfície do solo já está seca. (Gn 8:13)"],["Datas e meses","O capítulo registra o sétimo, décimo, primeiro e segundo meses, além dos dias correspondentes, para marcar as etapas do secamento. (Gn 8:4-5, 13-14)"],["Terra seca","Condição da terra registrada antes da ordem para sair da arca. (Gn 8:13-14)"],["Famílias dos animais","O texto informa que os animais saíram da arca segundo suas famílias. (Gn 8:19)"],["Fecundidade e multiplicação","Ordem dada para que os seres vivos se espalhem e se multipliquem sobre a terra. (Gn 8:17)"]]};
function renderStudyItems(items){return '<div class="study-catalog">'+items.map(([name,description])=>'<article class="guidecard"><h4>'+esc(name)+'</h4><p>'+esc(description)+'</p></article>').join('')+'</div>';}
function studyText(items){return (items||[]).map(([name,description])=>name+' | '+description).join('\n');}
function renderStudyText(value){const items=String(value||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{const p=line.split('|');return [p.shift().trim(),p.join('|').trim()||'Sem descrição adicionada.']});return items.length?renderStudyItems(items):'<span class="related-empty">Nenhum item cadastrado neste capítulo.</span>';}
function renderChapterSymbols(value){
 const names=String(value||'').split(/\r?\n/).map(line=>line.split('|')[0].trim()).filter(Boolean);
 if(!names.length)return '<span class="related-empty">Nenhuma simbologia vinculada à base de dados enviada por você.</span>';
 const library=Array.isArray(window.STUDY_LIBRARY)?window.STUDY_LIBRARY.filter(item=>item&&item.category==='Símbolos'):[];
 const custom=readLocalArray('encBibSymbols').filter(item=>item&&typeof item.name==='string').map(item=>({name:item.name,description:item.text||''}));
 const available=new Map();
 [...library,...custom].forEach(item=>{if(item&&typeof item.name==='string'){const key=item.name.trim().toLocaleLowerCase('pt-BR');if(key&&!available.has(key))available.set(key,item)}});
 const seen=new Set(),matched=[];
 names.forEach(name=>{const key=name.toLocaleLowerCase('pt-BR'),item=available.get(key);if(item&&!seen.has(key)){seen.add(key);matched.push(item)}});
 if(!matched.length)return '<span class="related-empty">Nenhum dos nomes informados foi encontrado na biblioteca de simbologias.</span>';
 return renderStudyItems(matched.map(item=>[item.name,item.description||item.text||'']));
}
function refreshChapterSymbols(bookIndex,chapter,value){
 if(!String(value||'').trim()||Array.isArray(window.STUDY_LIBRARY)||typeof window.loadStudyLibraryData!=='function')return;
 return window.loadStudyLibraryData().then(()=>{
  if(currentBook!==bookIndex||currentChapter!==chapter)return;
  const target=document.querySelector('#reader [data-panel="symbols"] .related-items');
  if(target)target.innerHTML=renderChapterSymbols(value);
 }).catch(error=>recordAppError(error,'Falha ao carregar a biblioteca para vincular simbologias ao capítulo'));
}


const $=id=>document.getElementById(id);
const key='enciclopediaBiblicaEditsV1';
const AUTO_BACKUP_KEY='encBibAutoBackupV1';
const AUTO_BACKUP_HISTORY_KEY='encBibAutoBackupHistoryV1';
const ERROR_LOG_KEY='encBibErrorLogV1';
const BOOK_INFO_EDITS_KEY='encBibBookInfoEdits';
const BACKUP_KEYS=[key,'encBibGuides','encBibStudyEdits','encBibSymbols','encBibCharacters',BOOK_INFO_EDITS_KEY];
function readLocalData(storageKey,fallback){
 try{const raw=localStorage.getItem(storageKey);return raw===null?fallback:JSON.parse(raw)}
 catch(error){if(storageKey!==ERROR_LOG_KEY)recordAppError(error,'Falha ao ler dados locais: '+storageKey);return fallback}
}
function readLocalArray(storageKey){
 const value=readLocalData(storageKey,[]);
 if(Array.isArray(value))return value;
 recordAppError('O dado local não é uma lista válida.','Leitura: '+storageKey);
 return [];
}
function readLocalObject(storageKey){
 const value=readLocalData(storageKey,{});
 if(value&&typeof value==='object'&&!Array.isArray(value))return value;
 recordAppError('O dado local não é um objeto válido.','Leitura: '+storageKey);
 return {};
}
function saveLocalData(storageKey,value){
 try{localStorage.setItem(storageKey,value)}
 catch(error){recordAppError(error,'Falha ao salvar dados locais: '+storageKey);return {saved:false,backedUp:false}}
 if(!BACKUP_KEYS.includes(storageKey))return {saved:true,backedUp:true};
 try{
  const data={};
  BACKUP_KEYS.forEach(k=>{const saved=localStorage.getItem(k);if(saved!==null)data[k]=saved});
  const snapshot={savedAt:new Date().toISOString(),data};
  localStorage.setItem(AUTO_BACKUP_KEY,JSON.stringify(snapshot));
  const history=readLocalData(AUTO_BACKUP_HISTORY_KEY,[]);
  if(!Array.isArray(history))throw new Error('Histórico de backup local inválido');
  history.unshift(snapshot);
  localStorage.setItem(AUTO_BACKUP_HISTORY_KEY,JSON.stringify(history.slice(0,8)));
  return {saved:true,backedUp:true};
 }catch(error){
  recordAppError(error,'Falha ao atualizar backup automático: '+storageKey);
  console.warn('Os dados foram salvos, mas o backup automático não foi atualizado:',error);
  return {saved:true,backedUp:false};
 }
}
function recordAppError(message,source=''){
  try{
    const logs=readLocalData(ERROR_LOG_KEY,[]);
    logs.unshift({at:new Date().toISOString(),message:String(message||'Erro desconhecido').slice(0,500),source:String(source||'').slice(0,300)});
    localStorage.setItem(ERROR_LOG_KEY,JSON.stringify(logs.slice(0,20)));
  }catch(error){console.warn('Não foi possível registrar o erro localmente:',error)}
}
window.addEventListener('error',event=>recordAppError(event.message,event.filename));
window.addEventListener('unhandledrejection',event=>recordAppError(event.reason&&event.reason.message?event.reason.message:event.reason,'Promise rejeitada'));
(function restoreMissingLocalData(){
  try{
    let backup=JSON.parse(localStorage.getItem(AUTO_BACKUP_KEY)||'null');
    if(!backup||!backup.data){
      const history=readLocalData(AUTO_BACKUP_HISTORY_KEY,[]);
      backup=history.find(item=>item&&item.data)||null;
    }
    if(!backup||!backup.data)return;
    BACKUP_KEYS.forEach(k=>{if(localStorage.getItem(k)===null&&typeof backup.data[k]==='string')localStorage.setItem(k,backup.data[k])});
  }catch(error){console.warn('Backup automático local indisponível:',error)}
})();
let edits=readLocalObject(key);
let currentBook=0,currentChapter=1;
const old=$('oldBooks'), neo=$('newBooks');
function renderBooks(filter=''){old.innerHTML='';neo.innerHTML='';BOOKS.forEach((b,i)=>{if(!b.name.toLowerCase().includes(filter.toLowerCase()))return;let el=document.createElement('button');el.className='book';el.innerHTML=`<span class="book-art">${window.bookArtwork?window.bookArtwork(i):''}</span><span class="book-name">${b.name}</span><small>${b.chapters} capítulos</small>`;el.onclick=()=>openBook(i);(i<39?old:neo).appendChild(el)})}
function show(view){['homeView','readerView','adminView','symbolsView','charactersView','detailView'].forEach(id=>$(id).classList.add('hidden'));$(view+'View').classList.remove('hidden');document.querySelectorAll('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('.bottom-tab').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function openBook(i){currentBook=i;show('reader');renderBook()}
window.openChapterFromButton=function(chapter){
 try{
  const n=Number(chapter);
  if(!Number.isInteger(n)||n<1||n>BOOKS[currentBook].chapters)return;
  openChapter(n);
 }catch(error){
  recordAppError(error&&error.stack?error.stack:error,'Falha ao abrir capítulo '+chapter);
  const message='Erro ao abrir o capítulo '+chapter+': '+(error&&error.message?error.message:String(error));
  const reader=$('reader');
  if(reader)reader.innerHTML='<div class="readerbox"><h2>Erro ao abrir o capítulo</h2><p>'+esc(message)+'</p><button type="button" class="back" onclick="renderBook()">← Voltar à lista de capítulos</button></div>';
  alert(message);
  console.error(message,error);
 }
};

